const NAVIGATION_TRAVERSAL_EVIDENCE_SELECT = `
  SELECT t.id, t.traversal_kind, t.label, t.path_json, t.bidirectional,
    t.speed_units_per_second, t.reviewed_purpose, t.evidence_asset_id,
    t.evidence_sha256, t.evidence_manifest_id,
    t.evidence_manifest_sha256, t.evidence_adapter,
    t.evidence_manifest_review_generation,
    t.evidence_registration_sha256, t.evidence_source_to_world_json,
    t.evidence_source_path_json,
    t.status, t.created_at, t.updated_at,
    evidence.sha256 AS current_evidence_sha256,
    evidence.integrity_status AS evidence_integrity_status,
    evidence.deleted_at AS evidence_deleted_at,
    manifest.manifest_hash AS current_evidence_manifest_sha256,
    COALESCE(manifest.adapter_v2, manifest.adapter) AS current_evidence_adapter,
    manifest.status AS evidence_manifest_status,
    manifest.result AS evidence_manifest_result,
    manifest.review_decision AS evidence_manifest_review_decision,
    manifest.review_generation AS current_evidence_manifest_review_generation,
    json_extract(
      CASE WHEN json_valid(manifest.canonical_manifest_json)
        THEN manifest.canonical_manifest_json ELSE '{}' END,
      '$.sceneRegistration.transformSha256'
    ) AS current_evidence_registration_sha256,
    json_extract(
      CASE WHEN json_valid(manifest.canonical_manifest_json)
        THEN manifest.canonical_manifest_json ELSE '{}' END,
      '$.sceneRegistration.sourceToWorld'
    ) AS current_evidence_source_to_world_json
  FROM scene_navigation_traversals t
  LEFT JOIN assets evidence ON evidence.id = t.evidence_asset_id
  LEFT JOIN capture_bundle_manifests manifest ON manifest.id = t.evidence_manifest_id
`;

const app = new Hono<AppEnvironment>();
const maximumPartBytes = 95 * 1024 * 1024;
const captureUploadPartBytes = 10 * 1024 * 1024;
// R2 completes at most 10,000 parts per multipart upload. Keep headroom so a
// resumed session that re-uploads a boundary part can never exhaust the ceiling.
const maximumUploadParts = 9500;
// 2 GiB: covers the largest known vendor Gaussian masters (the FJD P2 sample is
// ~536.8 MB, only ~57 KB under the previous 512 MiB bound) while native
// DigestStream hashing stays ~1s CPU; wall time is R2 streaming. Above this the
// digest degrades to client_declared and the processor re-verifies on download.
const serverHashMaximumBytes = 2 * 1024 * 1024 * 1024;
const jobDispatchBackoffMinutes = 10;
// attempt_count only moves at lease grant, so a job whose dispatches never
// reach a processor would otherwise be re-enqueued forever. Six undelivered
// dispatches at the ten-minute reconciliation backoff, plus the final window,
// give the dispatch path roughly an hour to deliver before the job
// dead-letters as dispatch_exhausted.
const jobDispatchExhaustionLimit = 6;
const maximumOperatorJobRetries = 5;
const maximumPrivacyImageBytes = 10 * 1024 * 1024;
const privacyDetector = "@cf/moondream/moondream3.1-9B-A2B";
const privacyDetectorVersion = "moondream3.1-9B-A2B:2026-07";
const workerJobIdPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const privacyTargets = [
  { target: "human face", label: "Human face" },
  { target: "vehicle license plate", label: "Vehicle license plate" },
  { target: "document showing personal information", label: "Personal document" },
  { target: "screen displaying readable personal or confidential information", label: "Sensitive screen" },
  { target: "security keypad or written access code", label: "Access credential" },
  { target: "personal photograph containing a person", label: "Personal photograph" },
] as const;
const allowedWebFormats = new Set(["rad", "spz", "sog"]);
const workerOutputFormats = new Map<string, Set<string>>([
  ["master", new Set(["ply", "rad"])],
  ["web", allowedWebFormats],
  ["portable", new Set(["ply", "spz", "sog"])],
  ["poster", new Set(["webp", "png", "jpg", "jpeg"])],
  ["pointcloud", new Set(["e57", "las", "laz", "ply"])],
  ["collision", new Set(["glb"])],
  ["navmesh", new Set(["bin"])],
  ["report", new Set(["json"])],
]);

app.use("*", async (context, next) => {
  const requestId = context.req.header("CF-Ray") ?? crypto.randomUUID();
  const startedAt = Date.now();
  context.set("requestId", requestId);
  try {
    await next();
  } finally {
    context.header("X-Request-Id", requestId);
    applySecurityHeaders(context);
    if ([401, 403, 429].includes(context.res.status)) {
      const matchedPath = routePath(context, -1);
      console.warn(JSON.stringify({
        event: "request.denied",
        requestId,
        method: context.req.method,
        path: (matchedPath === "/*" || matchedPath === "*" ? context.req.path : matchedPath).slice(0, 200),
        status: context.res.status,
        ip: context.req.header("CF-Connecting-IP") ?? "unknown",
      }));
    }
    console.log(JSON.stringify({
      event: "request.completed",
      requestId,
      method: context.req.method,
      path: context.req.path,
      status: context.res.status,
      durationMs: Date.now() - startedAt,
      environment: context.env.APP_ENV,
    }));
  }
});

app.onError((error, context) => {
  if (error instanceof RequestBodyError) {
    console.warn(JSON.stringify({
      event: "request.body_rejected",
      requestId: context.get("requestId"),
      path: context.req.path,
      code: error.kind,
    }));
    if (error.kind === "too_large") {
      return context.json({
        error: error.message,
        code: "request_body_too_large",
        requestId: context.get("requestId"),
      }, 413);
    }
    return context.json({
      error: error.message,
      code: "invalid_json",
      requestId: context.get("requestId"),
    }, 400);
  }
  console.error(JSON.stringify({
    event: "request.failed",
    requestId: context.get("requestId"),
    path: context.req.path,
    error: error.message,
    stack: error.stack,
  }));
  return context.json({ error: "Internal server error", requestId: context.get("requestId") }, 500);
});

app.notFound((context) => context.json({ error: "Not found", requestId: context.get("requestId") }, 404));

app.get("/api/health", async (context) => {
  const clientAddress = context.req.header("CF-Connecting-IP") ?? "unknown";
  let withinRateLimit = true;
  try {
    withinRateLimit = await allowRate(context.env.DB, "health-ip", clientAddress, 120, 60);
  } catch {
    // Database unavailability is reported by the database probe below.
  }
  if (!withinRateLimit) return tooManyRequests(context, 60);
  const probe = async (check: () => Promise<boolean>): Promise<"ok" | "degraded"> => {
    try {
      const healthy = await Promise.race([
        check(),
        new Promise<boolean>((resolve) => setTimeout(() => resolve(false), 1_500)),
      ]);
      return healthy ? "ok" : "degraded";
    } catch {
      return "degraded";
    }
  };
  const [database, cache, storage] = await Promise.all([
    probe(async () => {
      const row = await context.env.DB.prepare("SELECT 1 AS ready").first<{ ready: number }>();
      return row?.ready === 1;
    }),
    probe(async () => {
      await context.env.AUTH_CACHE.get("health:probe");
      return true;
    }),
    probe(async () => {
      await context.env.SPATIAL_ASSETS.head("health/probe");
      return true;
    }),
  ]);
  const healthy = database === "ok";
  return context.json({
    status: healthy && cache === "ok" && storage === "ok" ? "ok" : "degraded",
    environment: context.env.APP_ENV,
    dependencies: { database, cache, storage },
    timestamp: new Date().toISOString(),
    requestId: context.get("requestId"),
  }, healthy ? 200 : 503);
});

