app.get("/api/projects/:projectId/spatial/authoring-renderable", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  const projectId = context.req.param("projectId");
  const versionId = context.req.query("versionId")?.trim();
  if (!versionId) return validationError(context, { versionId: ["Choose an immutable scene version"] });
  const project = await scopedProject(context.env.DB, auth.organisationId, projectId);
  if (!project) return notFound(context, "Project not found");
  const version = await context.env.DB.prepare(`
    SELECT id, version_number, status
    FROM scene_versions
    WHERE id = ? AND project_id = ?
  `).bind(versionId, projectId).first<{
    id: string;
    version_number: number;
    status: string;
  }>();
  if (!version) return notFound(context, "Scene version not found");
  const asset = await context.env.DB.prepare(`
    SELECT id, format, file_name, mime_type, object_key, size_bytes, sha256
    FROM assets
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND kind = 'web' AND integrity_status = 'verified' AND deleted_at IS NULL
      AND format IN ('rad', 'spz', 'sog')
    ORDER BY created_at DESC
    LIMIT 1
  `).bind(auth.organisationId, projectId, versionId).first<{
    id: string;
    format: "rad" | "spz" | "sog";
    file_name: string;
    mime_type: string;
    object_key: string;
    size_bytes: number;
    sha256: string | null;
  }>();
  if (!asset || !(await context.env.SPATIAL_ASSETS.head(asset.object_key))) {
    return conflict(context, "This version does not have a verified browser scene to author against");
  }
  const [sceneRegistration, release] = await Promise.all([
    qualifiedSceneRegistration(
      context.env.DB,
      auth.organisationId,
      projectId,
      versionId,
    ),
    context.env.DB.prepare(`
      SELECT viewer_config_json
      FROM releases
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND revoked_at IS NULL
      ORDER BY published_at DESC
      LIMIT 1
    `).bind(auth.organisationId, projectId, versionId).first<{
      viewer_config_json: string;
    }>(),
  ]);
  if (!sceneRegistration) {
    return conflict(
      context,
      "This version has no verified paired-upload frame receipt. Upload the visual and registered metric geometry together from the same unchanged capture frame, or attach an accepted measured capture-to-scene registration.",
    );
  }
  const storedViewer = release ? parseStoredObject(release.viewer_config_json) : {};
  const viewer = storedViewer && typeof storedViewer === "object"
    ? { ...storedViewer }
    : {};
  Reflect.set(viewer, "sourceToWorld", sceneRegistration.sourceToWorld);
  Reflect.set(viewer, "captureRegistration", sceneRegistration.receipt);
  const tokenTtl = positiveInteger(context.env.SCENE_SESSION_TTL_SECONDS, 1800);
  const sessionExpiresAt = Math.floor(Date.now() / 1000) + tokenTtl;
  const token = await signSceneToken({
    releaseId: comparisonAssetTokenScope(projectId, versionId, asset.id),
    expiresAt: sessionExpiresAt,
  }, context.env.SESSION_PEPPER);
  context.header("Cache-Control", "private, no-store");
  return context.json({
    version: {
      id: version.id,
      number: version.version_number,
      status: version.status,
    },
    renderable: {
      purpose: "spatial-authoring",
      versionId,
      assetId: asset.id,
      format: asset.format,
      fileName: asset.file_name,
      mimeType: asset.mime_type,
      sizeBytes: asset.size_bytes,
      sha256: asset.sha256,
      contentUrl: `/comparison-asset/${projectId}/${versionId}/${asset.id}/${encodeURIComponent(asset.file_name)}?token=${encodeURIComponent(token)}`,
      sessionExpiresAt: new Date(sessionExpiresAt * 1000).toISOString(),
      viewer,
    },
  });
});

app.get("/api/projects/:projectId/versions/:versionId/preview", async (context) => {
  const access = await requireReviewProject(context, context.req.param("projectId"));
  if (access instanceof Response) return access;
  const versionId = context.req.param("versionId");
  const version = await context.env.DB.prepare(`
    SELECT id, version_number, status, source_provenance_json
    FROM scene_versions
    WHERE id = ? AND project_id = ?
  `).bind(versionId, access.project.id).first<{
    id: string;
    version_number: number;
    status: string;
    source_provenance_json: string | null;
  }>();
  if (!version) return notFound(context, "Scene version not found");
  const assets = await context.env.DB.prepare(`
    SELECT id, version_id, format, file_name, mime_type, object_key,
      size_bytes, sha256, integrity_status
    FROM assets
    WHERE project_id = ? AND organisation_id = ? AND version_id = ?
      AND kind = 'web' AND integrity_status = 'verified' AND deleted_at IS NULL
    ORDER BY created_at DESC
  `).bind(access.project.id, access.auth.organisationId, versionId).all<{
    id: string;
    version_id: string;
    format: string;
    file_name: string;
    mime_type: string;
    object_key: string;
    size_bytes: number;
    sha256: string | null;
    integrity_status: string;
  }>();
  const asset = assets.results.find((candidate) => allowedWebFormats.has(candidate.format));
  if (!asset || !(await context.env.SPATIAL_ASSETS.head(asset.object_key))) {
    return conflict(context, "This version does not have a verified browser scene yet");
  }
  context.header("Cache-Control", "private, no-store");
  const navigationQualification = await qualifyNavigationPreview(
    context.env,
    access.auth.organisationId,
    access.project.id,
    version.id,
  );
  if (!navigationQualification.ready) {
    return conflict(context, navigationQualification.message);
  }
  const navigation = navigationQualification.value;
  const releaseConfig = await context.env.DB.prepare(`
    SELECT viewer_config_json
    FROM releases
    WHERE project_id = ? AND organisation_id = ? AND version_id = ?
      AND revoked_at IS NULL
    ORDER BY published_at DESC
    LIMIT 1
  `).bind(access.project.id, access.auth.organisationId, versionId).first<{
    viewer_config_json: string;
  }>();
  const tokenTtl = positiveInteger(context.env.SCENE_SESSION_TTL_SECONDS, 1800);
  const sessionExpiresAt = Math.floor(Date.now() / 1000) + tokenTtl;
  const token = await signSceneToken({
    releaseId: comparisonAssetTokenScope(access.project.id, version.id, asset.id),
    expiresAt: sessionExpiresAt,
  }, context.env.SESSION_PEPPER);
  const collisionToken = await signSceneToken({
    releaseId: comparisonAssetTokenScope(
      access.project.id,
      version.id,
      navigation.collisionAsset.id,
    ),
    expiresAt: sessionExpiresAt,
  }, context.env.SESSION_PEPPER);
  const storedViewerValue = releaseConfig
    ? parseStoredObject(releaseConfig.viewer_config_json)
    : {};
  const storedViewer = storedViewerValue && typeof storedViewerValue === "object"
    ? storedViewerValue
    : {};
  const contentUrl = `/comparison-asset/${access.project.id}/${version.id}/${asset.id}/${encodeURIComponent(asset.file_name)}?token=${encodeURIComponent(token)}`;
  const collisionUrl = `/comparison-asset/${access.project.id}/${version.id}/${navigation.collisionAsset.id}/${encodeURIComponent(navigation.collisionAsset.file_name)}?token=${encodeURIComponent(collisionToken)}`;
  const viewer = {
    title: access.project.name,
    measurementDisclaimer: PROVISIONAL_MEASUREMENT_DISCLAIMER,
    ...storedViewer,
    sourceToWorld: navigation.registration.sourceToWorld,
    captureRegistration: navigation.registration.receipt,
  };
  return context.json({
    version: {
      id: version.id,
      number: version.version_number,
      status: version.status,
    },
    renderable: {
      versionId: version.id,
      assetId: asset.id,
      format: asset.format,
      fileName: asset.file_name,
      mimeType: asset.mime_type,
      sizeBytes: asset.size_bytes,
      sha256: asset.sha256,
      contentUrl,
      collisionUrl,
      sessionExpiresAt: new Date(sessionExpiresAt * 1000).toISOString(),
      viewer,
      spatial: navigation.spatial,
    },
    manifest: {
      schemaVersion: "1.0.0",
      release: {
        id: `preview:${version.id}`,
        number: 0,
        slug: `preview-${version.id}`,
        publishedAt: new Date().toISOString(),
        expiresAt: new Date(sessionExpiresAt * 1000).toISOString(),
        accessPolicy: "private-preview",
      },
      project: {
        id: access.project.id,
        versionId: version.id,
        versionNumber: version.version_number,
        name: access.project.name,
        captureAdapter: access.project.capture_adapter,
        provenance: parseStoredObject(version.source_provenance_json ?? "{}"),
      },
      scene: {
        format: asset.format,
        contentUrl,
        posterUrl: null,
        collisionUrl,
        sizeBytes: asset.size_bytes,
        etag: null,
      },
      viewer,
      spatial: navigation.spatial,
      integrity: {
        assetSha256: asset.sha256,
        sessionExpiresAt: new Date(sessionExpiresAt * 1000).toISOString(),
      },
    },
  });
});

