app.post("/api/projects/:projectId/retention/restore-drill", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const project = await scopedProject(context.env.DB, auth.organisationId, context.req.param("projectId"));
  if (!project) return notFound(context, "Project not found");
  const asset = await context.env.DB.prepare(`
    SELECT id, object_key, size_bytes, etag FROM assets
    WHERE project_id = ? AND organisation_id = ? AND deleted_at IS NULL
    ORDER BY CASE kind WHEN 'master' THEN 1 WHEN 'web' THEN 2 ELSE 3 END, created_at DESC
    LIMIT 1
  `).bind(project.id, auth.organisationId).first<{
    id: string;
    object_key: string;
    size_bytes: number;
    etag: string | null;
  }>();
  if (!asset) return notFound(context, "No retained asset is available for a restore drill");
  const runId = crypto.randomUUID();
  await context.env.DB.prepare(`
    INSERT INTO lifecycle_runs (id, trigger_type, status)
    VALUES (?, 'restore_drill', 'running')
  `).bind(runId).run();
  try {
    const stored = await context.env.SPATIAL_ASSETS.get(asset.object_key, { range: { offset: 0, length: 64 } });
    if (!stored) throw new Error("The retained R2 object is missing");
    const sample = await stored.arrayBuffer();
    if (asset.size_bytes > 0 && sample.byteLength === 0) throw new Error("The retained object returned no readable bytes");
    await context.env.DB.batch([
      context.env.DB.prepare(`
        INSERT INTO lifecycle_actions
          (id, run_id, organisation_id, project_id, action, resource_type, resource_id, metadata_json)
        VALUES (?, ?, ?, ?, 'restore_verified', 'asset', ?, ?)
      `).bind(
        crypto.randomUUID(),
        runId,
        auth.organisationId,
        project.id,
        asset.id,
        JSON.stringify({ sampleBytes: sample.byteLength, expectedBytes: asset.size_bytes, etag: asset.etag }),
      ),
      context.env.DB.prepare(`
        UPDATE lifecycle_runs SET status = 'succeeded', completed_at = datetime('now'),
          summary_json = ? WHERE id = ?
      `).bind(JSON.stringify({ restoredAssets: 1, sampledBytes: sample.byteLength }), runId),
    ]);
    await audit(context, auth, "retention.restore_drill", "asset", asset.id, { runId, sampledBytes: sample.byteLength });
    return context.json({
      runId,
      status: "succeeded",
      assetId: asset.id,
      sampledBytes: sample.byteLength,
      expectedBytes: asset.size_bytes,
    });
  } catch (error) {
    const message = errorMessage(error).slice(0, 1000);
    await context.env.DB.prepare(`
      UPDATE lifecycle_runs SET status = 'failed', completed_at = datetime('now'),
        error_message = ? WHERE id = ?
    `).bind(message, runId).run();
    return context.json({ error: `Restore drill failed: ${message}`, requestId: context.get("requestId") }, 409);
  }
});

app.put("/api/projects/:projectId/hosting", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = hostingSubscriptionSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(context.env.DB, auth.organisationId, context.req.param("projectId"));
  if (!project) return notFound(context, "Project not found");
  const plan = await context.env.DB.prepare(
    "SELECT code, monthly_price_cents FROM hosting_plans WHERE code = ? AND active = 1",
  ).bind(parsed.data.planCode).first<{ code: string; monthly_price_cents: number }>();
  if (!plan) return notFound(context, "Hosting plan not found");
  if (plan.code === "enterprise" || plan.monthly_price_cents === 0) {
    return conflict(context, "Enterprise private hosting requires a signed contract and manual provisioning");
  }
  const config = stripeBillingConfig(context.env);
  if (!config) {
    return context.json({
      error: "The payment provider is not configured; no subscription or invoice was created",
      retryable: false,
      requestId: context.get("requestId"),
    }, 503);
  }
  const planCode = plan.code as StripePlanCode;
  const requestHash = await sha256Hex(JSON.stringify({
    projectId: project.id,
    planCode,
    renewsAutomatically: parsed.data.renewsAutomatically,
    archiveOnExpiry: parsed.data.archiveOnExpiry,
  }));
  let checkout = await context.env.DB.prepare(`
    SELECT * FROM billing_checkout_sessions
    WHERE organisation_id = ? AND client_operation_id = ?
  `).bind(
    auth.organisationId,
    parsed.data.clientOperationId,
  ).first<BillingCheckoutRow>();
  if (checkout && checkout.request_hash !== requestHash) {
    return conflict(context, "This checkout operation identifier was already used for different settings");
  }
  if (
    checkout &&
    checkout.provider_checkout_id &&
    checkout.checkout_url &&
    ["open", "complete"].includes(checkout.status)
  ) {
    return context.json({
      checkout: publicBillingCheckout(checkout),
      idempotent: true,
    });
  }
  const checkoutId = checkout?.id ?? crypto.randomUUID();
  if (!checkout) {
    await context.env.DB.prepare(`
      INSERT INTO billing_checkout_sessions (
        id, organisation_id, project_id, plan_code, status, amount_cents,
        currency, customer_email, archive_on_expiry, request_hash,
        client_operation_id, created_by
      ) VALUES (?, ?, ?, ?, 'pending', ?, 'MYR', ?, ?, ?, ?, ?)
    `).bind(
      checkoutId,
      auth.organisationId,
      project.id,
      planCode,
      plan.monthly_price_cents,
      auth.email,
      parsed.data.archiveOnExpiry ? 1 : 0,
      requestHash,
      parsed.data.clientOperationId,
      auth.userId,
    ).run();
  } else {
    await context.env.DB.prepare(`
      UPDATE billing_checkout_sessions
      SET status = 'pending', last_error = NULL, updated_at = datetime('now')
      WHERE id = ? AND organisation_id = ?
    `).bind(checkoutId, auth.organisationId).run();
  }
  try {
    const providerCheckout = await createStripeCheckoutSession(config, {
      checkoutId,
      organisationId: auth.organisationId,
      projectId: project.id,
      planCode,
      customerEmail: auth.email,
      successUrl: `${context.env.APP_ORIGIN}/studio.html?checkout=success&session_id={CHECKOUT_SESSION_ID}#hosting`,
      cancelUrl: `${context.env.APP_ORIGIN}/studio.html?checkout=cancelled#hosting`,
    });
    await context.env.DB.prepare(`
      UPDATE billing_checkout_sessions
      SET status = ?, provider_checkout_id = ?, provider_customer_id = ?,
        provider_subscription_id = ?, checkout_url = ?, payment_status = ?,
        expires_at = ?, last_error = NULL, updated_at = datetime('now')
      WHERE id = ? AND organisation_id = ?
    `).bind(
      providerCheckout.status === "open" ? "open" : "pending",
      providerCheckout.id,
      providerCheckout.customerId,
      providerCheckout.subscriptionId,
      providerCheckout.url,
      providerCheckout.paymentStatus,
      providerCheckout.expiresAt
        ? new Date(providerCheckout.expiresAt * 1000).toISOString()
        : null,
      checkoutId,
      auth.organisationId,
    ).run();
    checkout = await context.env.DB.prepare(
      "SELECT * FROM billing_checkout_sessions WHERE id = ? AND organisation_id = ?",
    ).bind(checkoutId, auth.organisationId).first<BillingCheckoutRow>();
    await audit(context, auth, "billing.checkout.create", "billing_checkout", checkoutId, {
      projectId: project.id,
      planCode,
      provider: "stripe",
      providerCheckoutId: providerCheckout.id,
    });
    return context.json({
      checkout: publicBillingCheckout(checkout!),
      idempotent: false,
    }, 201);
  } catch (error) {
    const providerError = error instanceof StripeBillingError
      ? error
      : new StripeBillingError(errorMessage(error), 503, null, true);
    await context.env.DB.prepare(`
      UPDATE billing_checkout_sessions
      SET status = 'failed', last_error = ?, updated_at = datetime('now')
      WHERE id = ? AND organisation_id = ?
    `).bind(providerError.message.slice(0, 500), checkoutId, auth.organisationId).run();
    await audit(context, auth, "billing.checkout.failed", "billing_checkout", checkoutId, {
      providerCode: providerError.providerCode,
      providerStatus: providerError.status,
      retryable: providerError.retryable,
    });
    return context.json({
      error: providerError.message,
      providerCode: providerError.providerCode,
      retryable: providerError.retryable,
      requestId: context.get("requestId"),
    }, providerError.retryable ? 503 : 409);
  }
});

app.post("/api/projects/:projectId/hosting/renew", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  return context.json({
    error: "Provider-managed subscriptions renew through Stripe; start a new checkout to recover a past-due plan",
    retryable: false,
    requestId: context.get("requestId"),
  }, 409);
});

app.post("/api/projects/:projectId/hosting/cancel", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  // At most one subscription per project is non-terminal, so cancellation always
  // resolves the same row instead of picking one of several duplicates.
  const subscription = await context.env.DB.prepare(`
    SELECT id, status, payment_provider, provider_subscription_id, current_period_end
    FROM project_hosting_subscriptions
    WHERE project_id = ? AND organisation_id = ? AND status IN ('trial', 'active', 'past_due')
    ORDER BY CASE WHEN status IN ('active', 'past_due') THEN 0 ELSE 1 END,
      updated_at DESC, created_at DESC, id
    LIMIT 1
  `).bind(context.req.param("projectId"), auth.organisationId).first<{
    id: string;
    status: string;
    payment_provider: string | null;
    provider_subscription_id: string | null;
    current_period_end: string;
  }>();
  if (!subscription) return notFound(context, "Active hosting subscription not found");
  if (subscription.payment_provider !== "stripe" || !subscription.provider_subscription_id) {
    return conflict(context, "This legacy hosting record has no provider subscription to cancel");
  }
  const config = stripeBillingConfig(context.env);
  if (!config) {
    return context.json({
      error: "The payment provider is not configured; refusing to claim the subscription was cancelled",
      retryable: false,
      requestId: context.get("requestId"),
    }, 503);
  }
  try {
    const provider = await cancelStripeSubscriptionAtPeriodEnd(
      config,
      subscription.provider_subscription_id,
    );
    await context.env.DB.prepare(`
      UPDATE project_hosting_subscriptions
      SET renews_automatically = 0, provider_cancel_at_period_end = ?,
        current_period_end = COALESCE(?, current_period_end),
        updated_at = datetime('now')
      WHERE id = ? AND organisation_id = ?
    `).bind(
      provider.cancelAtPeriodEnd ? 1 : 0,
      provider.currentPeriodEnd
        ? new Date(provider.currentPeriodEnd * 1000).toISOString()
        : null,
      subscription.id,
      auth.organisationId,
    ).run();
    await audit(context, auth, "hosting.subscription.cancel_at_period_end", "hosting_subscription", subscription.id, {
      provider: "stripe",
      providerSubscriptionId: subscription.provider_subscription_id,
      cancelAtPeriodEnd: provider.cancelAtPeriodEnd,
    });
    return context.json({
      subscription: {
        id: subscription.id,
        status: subscription.status,
        cancelAtPeriodEnd: provider.cancelAtPeriodEnd,
        currentPeriodEnd: provider.currentPeriodEnd
          ? new Date(provider.currentPeriodEnd * 1000).toISOString()
          : subscription.current_period_end,
      },
    });
  } catch (error) {
    const providerError = error instanceof StripeBillingError
      ? error
      : new StripeBillingError(errorMessage(error), 503, null, true);
    return context.json({
      error: providerError.message,
      providerCode: providerError.providerCode,
      retryable: providerError.retryable,
      requestId: context.get("requestId"),
    }, providerError.retryable ? 503 : 409);
  }
});

app.put("/api/projects/:projectId/retention", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = retentionPolicySchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(context.env.DB, auth.organisationId, context.req.param("projectId"));
  if (!project) return notFound(context, "Project not found");
  await context.env.DB.prepare(`
    INSERT INTO project_retention_policies
      (project_id, organisation_id, raw_retention_days, derivative_retention_days,
        release_retention_days, delete_after, legal_hold, updated_by)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(project_id) DO UPDATE SET
      raw_retention_days = excluded.raw_retention_days,
      derivative_retention_days = excluded.derivative_retention_days,
      release_retention_days = excluded.release_retention_days,
      delete_after = excluded.delete_after,
      legal_hold = excluded.legal_hold,
      updated_by = excluded.updated_by,
      updated_at = datetime('now')
  `).bind(
    project.id,
    auth.organisationId,
    parsed.data.rawRetentionDays,
    parsed.data.derivativeRetentionDays,
    parsed.data.releaseRetentionDays,
    parsed.data.deleteAfter ?? null,
    parsed.data.legalHold ? 1 : 0,
    auth.userId,
  ).run();
  await audit(context, auth, "retention.policy.update", "project", project.id, parsed.data);
  return context.json({ policy: parsed.data });
});

app.get("/api/projects/:projectId/spatial", async (context) => {
  const access = await requireReviewProject(context, context.req.param("projectId"));
  if (access instanceof Response) return access;
  const versionId = context.req.query("versionId") ?? access.project.latest_version_id;
  if (!versionId) return context.json({
    versionId: null,
    entities: [],
    routes: [],
    routeStops: [],
    privacyRegions: [],
    privacyScans: [],
    privacyCandidates: [],
    changeReports: [],
    captureCompletenessReports: [],
    captureScanStructures: [],
    rawChangeReports: [],
    semanticExtractions: [],
    semanticCandidates: [],
    floorplanExtractions: [],
    floorplanRevisions: [],
    floorplanExports: [],
    navigationObstacles: [],
    navigationTraversals: [],
    traversalEvidenceOptions: [],
    navigationBuilds: [],
    walkTests: [],
    releaseRepublishIntents: [],
    navigationArtifact: null,
    deliveryPolicy: null,
    collisionProxy: { version: "box-union-v1", boxes: [] },
    navigationMesh: { version: "room-box-triangles-v1", vertices: [], indices: [], sourceEntityIds: [] },
    obstacleProxy: { version: "authored-obstacle-boxes-v1", boxes: [] },
    navigationProfile: defaultNavigationProfile,
  });
  const version = await context.env.DB.prepare(
    "SELECT id, version_number FROM scene_versions WHERE id = ? AND project_id = ?",
  ).bind(versionId, access.project.id).first<{ id: string; version_number: number }>();
  if (!version) return notFound(context, "Scene version not found");
  const results = await context.env.DB.batch([
    context.env.DB.prepare(`
      SELECT * FROM scene_entities WHERE version_id = ? AND project_id = ? AND status = 'active'
      ORDER BY kind, sort_order, label
    `).bind(version.id, access.project.id),
    context.env.DB.prepare(`
      SELECT * FROM scene_routes WHERE version_id = ? AND project_id = ? AND status = 'active'
      ORDER BY created_at
    `).bind(version.id, access.project.id),
    context.env.DB.prepare(`
      SELECT rs.* FROM scene_route_stops rs JOIN scene_routes r ON r.id = rs.route_id
      WHERE r.version_id = ? AND r.project_id = ? ORDER BY rs.route_id, rs.sequence_number
    `).bind(version.id, access.project.id),
    context.env.DB.prepare(`
      SELECT * FROM privacy_regions WHERE version_id = ? AND project_id = ?
      ORDER BY created_at DESC
    `).bind(version.id, access.project.id),
    context.env.DB.prepare(`
      SELECT * FROM privacy_scans
      WHERE version_id = ? AND project_id = ? AND organisation_id = ?
      ORDER BY created_at DESC LIMIT 25
    `).bind(version.id, access.project.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT pc.*, a.file_name AS asset_file_name, a.mime_type AS asset_mime_type
      FROM privacy_candidates pc
      JOIN assets a ON a.id = pc.asset_id
      WHERE pc.version_id = ? AND pc.project_id = ? AND pc.organisation_id = ?
      ORDER BY pc.created_at DESC LIMIT 250
    `).bind(version.id, access.project.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT * FROM change_detection_reports WHERE project_id = ? AND organisation_id = ?
      ORDER BY created_at DESC LIMIT 50
    `).bind(access.project.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT * FROM capture_completeness_reports
      WHERE project_id = ? AND organisation_id = ?
      ORDER BY created_at DESC LIMIT 25
    `).bind(access.project.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT r.*, j.state AS job_state, j.progress AS job_progress,
        j.progress_message AS job_progress_message, j.attempt_count,
        j.max_attempts, j.error_json AS job_error_json,
        bv.version_number AS baseline_version_number,
        cv.version_number AS candidate_version_number,
        ba.file_name AS baseline_file_name,
        ca.file_name AS candidate_file_name
      FROM registered_scene_change_reports r
      JOIN processing_jobs j ON j.id = r.job_id
      JOIN scene_versions bv ON bv.id = r.baseline_version_id
      JOIN scene_versions cv ON cv.id = r.candidate_version_id
      JOIN assets ba ON ba.id = r.baseline_asset_id
      JOIN assets ca ON ca.id = r.candidate_asset_id
      WHERE r.project_id = ? AND r.organisation_id = ?
      ORDER BY r.created_at DESC LIMIT 25
    `).bind(access.project.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT * FROM project_delivery_policies WHERE project_id = ? AND organisation_id = ?
    `).bind(access.project.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT r.*, j.state AS job_state, j.progress AS job_progress,
        j.progress_message AS job_progress_message, j.attempt_count,
        j.max_attempts, j.error_json AS job_error_json,
        a.file_name AS input_file_name, a.size_bytes AS input_size_bytes
      FROM semantic_extraction_runs r
      JOIN processing_jobs j ON j.id = r.job_id
      JOIN assets a ON a.id = r.input_asset_id
      WHERE r.project_id = ? AND r.version_id = ? AND r.organisation_id = ?
      ORDER BY r.created_at DESC LIMIT 25
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT * FROM semantic_candidates
      WHERE project_id = ? AND version_id = ? AND organisation_id = ?
      ORDER BY created_at DESC, candidate_key LIMIT 250
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT r.*, j.state AS job_state, j.progress AS job_progress,
        j.progress_message AS job_progress_message, j.attempt_count,
        j.max_attempts, j.error_json AS job_error_json,
        a.file_name AS input_file_name, a.format AS input_format,
        a.size_bytes AS input_size_bytes
      FROM floorplan_extraction_runs r
      JOIN processing_jobs j ON j.id = r.job_id
      JOIN assets a ON a.id = r.input_asset_id
      WHERE r.project_id = ? AND r.version_id = ? AND r.organisation_id = ?
      ORDER BY r.created_at DESC LIMIT 25
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT * FROM floorplan_revisions
      WHERE project_id = ? AND version_id = ? AND organisation_id = ?
      ORDER BY revision_number DESC, created_at DESC LIMIT 100
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT e.*, a.file_name, a.mime_type, a.size_bytes, a.sha256
      FROM floorplan_exports e
      JOIN assets a ON a.id = e.asset_id
      WHERE e.project_id = ? AND e.version_id = ? AND e.organisation_id = ?
      ORDER BY e.created_at DESC LIMIT 300
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT * FROM scene_navigation_obstacles
      WHERE project_id = ? AND version_id = ? AND organisation_id = ? AND status = 'active'
      ORDER BY label, created_at
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT world_unit, agent_radius, agent_height, eye_height, max_step_metres,
        max_slope_degrees, max_speed, max_acceleration
      FROM scene_navigation_profiles
      WHERE project_id = ? AND version_id = ? AND organisation_id = ?
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT id, collision_asset_id, job_id, status, parameters_json, authoring_hash,
        artifact_json, navmesh_asset_id, report_asset_id, review_note,
        reviewed_at, created_at, updated_at
      FROM scene_navigation_builds
      WHERE project_id = ? AND version_id = ? AND organisation_id = ?
      ORDER BY created_at DESC LIMIT 25
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`${NAVIGATION_TRAVERSAL_EVIDENCE_SELECT}
      WHERE t.project_id = ? AND t.version_id = ? AND t.organisation_id = ?
      ORDER BY t.label, t.created_at
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT s.*, a.file_name AS asset_file_name, a.format AS asset_format,
        r.file_name AS report_file_name, r.sha256 AS report_asset_sha256
      FROM capture_scan_structures s
      JOIN assets a ON a.id = s.asset_id
      LEFT JOIN assets r ON r.id = s.report_asset_id
      WHERE s.project_id = ? AND s.version_id = ? AND s.organisation_id = ?
      ORDER BY s.created_at DESC LIMIT 25
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT i.id, i.navigation_build_id, i.source_release_id, i.status,
        i.completed_release_id, i.error_message, i.created_at, i.updated_at,
        i.completed_at,
        COALESCE(
          (SELECT active.slug FROM release_channels active
            WHERE active.active_release_id = i.completed_release_id
              AND active.organisation_id = i.organisation_id LIMIT 1),
          (SELECT historical.slug FROM release_channels historical
            WHERE historical.project_id = i.project_id
              AND historical.organisation_id = i.organisation_id
            ORDER BY historical.updated_at DESC LIMIT 1)
        ) AS slug
      FROM release_republish_intents i
      WHERE i.project_id = ? AND i.version_id = ? AND i.organisation_id = ?
      ORDER BY i.created_at DESC
    `).bind(access.project.id, version.id, access.auth.organisationId),
    context.env.DB.prepare(`
      SELECT id, navigation_build_id, start_pose_json, end_pose_json,
        runtime_evidence_json, completed_by, completed_at
      FROM scene_navigation_walk_tests
      WHERE project_id = ? AND version_id = ? AND organisation_id = ?
      ORDER BY completed_at DESC
    `).bind(access.project.id, version.id, access.auth.organisationId),
  ]);
  const entities = requiredBatchResult(results, 0).results;
  const navigationObstacles = requiredBatchResult(results, 15).results;
  const navigationProfile = requiredBatchResult(results, 16).results[0];
  const navigationBuilds = requiredBatchResult(results, 17).results;
  const navigationTraversalRows = requiredBatchResult(results, 18).results;
  const navigationTraversals = navigationTraversalRows.filter(
    (row) => row && typeof row === "object" && Reflect.get(row, "status") === "active",
  );
  const authoringHash = await navigationAuthoringHash(
    navigationProfile,
    entities,
    navigationObstacles,
    requiredBatchResult(results, 2).results,
    navigationTraversalRows,
  );
  const navigationArtifact = approvedNavigationArtifact(navigationBuilds, authoringHash);
  const runtime = buildSpatialRuntime(entities, navigationObstacles, navigationProfile);
  const traversalEvidenceOptions = await qualifiedTraversalEvidenceOptions(
    context.env.DB,
    access.auth.organisationId,
    access.project.id,
    version.id,
  );
  return context.json({
    version,
    entities,
    routes: requiredBatchResult(results, 1).results,
    routeStops: requiredBatchResult(results, 2).results,
    privacyRegions: requiredBatchResult(results, 3).results,
    privacyScans: requiredBatchResult(results, 4).results,
    privacyCandidates: requiredBatchResult(results, 5).results,
    changeReports: requiredBatchResult(results, 6).results,
    captureCompletenessReports: requiredBatchResult(results, 7).results,
    captureScanStructures: requiredBatchResult(results, 19).results.map(
      captureScanStructureApi,
    ),
    rawChangeReports: requiredBatchResult(results, 8).results,
    deliveryPolicy: requiredBatchResult(results, 9).results[0] ?? null,
    semanticExtractions: requiredBatchResult(results, 10).results,
    semanticCandidates: requiredBatchResult(results, 11).results.map(
      semanticCandidateApi,
    ),
    floorplanExtractions: requiredBatchResult(results, 12).results,
    floorplanRevisions: requiredBatchResult(results, 13).results,
    floorplanExports: (requiredBatchResult(results, 14).results as Array<Record<string, unknown>>).map((row) => ({
      ...row,
      download_url:
        `/api/projects/${access.project.id}/spatial/floorplan-exports/${String(row.id)}/download`,
    })),
    navigationObstacles,
    navigationTraversals,
    traversalEvidenceOptions,
    navigationBuilds,
    releaseRepublishIntents: requiredBatchResult(results, 20).results,
    walkTests: requiredBatchResult(results, 21).results,
    navigationArtifact,
    collisionProxy: runtime.collisionProxy,
    navigationMesh: runtime.navigationMesh,
    obstacleProxy: runtime.obstacleProxy,
    navigationProfile: runtime.navigationProfile,
  });
});

app.post("/api/projects/:projectId/spatial/entities", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = sceneEntitySchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(context.env.DB, auth.organisationId, context.req.param("projectId"));
  if (!project) return notFound(context, "Project not found");
  const version = await context.env.DB.prepare(
    "SELECT id FROM scene_versions WHERE id = ? AND project_id = ?",
  ).bind(parsed.data.versionId, project.id).first<{ id: string }>();
  if (!version) return notFound(context, "Scene version not found");
  if (parsed.data.parentId) {
    const parent = await context.env.DB.prepare(
      "SELECT id FROM scene_entities WHERE id = ? AND version_id = ? AND project_id = ?",
    ).bind(parsed.data.parentId, version.id, project.id).first();
    if (!parent) return validationError(context, { parentId: ["Parent entity is not in this version"] });
  }
  if (parsed.data.clientOperationId) {
    const existing = await context.env.DB.prepare(
      "SELECT * FROM scene_entities WHERE organisation_id = ? AND client_operation_id = ?",
    ).bind(auth.organisationId, parsed.data.clientOperationId).first();
    if (existing) return context.json({ entity: existing, idempotent: true });
  }
  const id = crypto.randomUUID();
  const created = await context.env.DB.prepare(`
    INSERT INTO scene_entities
      (id, organisation_id, project_id, version_id, parent_id, kind, label,
        description, position_json, geometry_json, metadata_json, sort_order,
        client_operation_id, created_by, world_unit)
    SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
      COALESCE((
        SELECT world_unit FROM scene_navigation_profiles
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      ), 'metres')
    RETURNING world_unit
  `).bind(
    id,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.parentId ?? null,
    parsed.data.kind,
    parsed.data.label,
    parsed.data.description ?? null,
    parsed.data.position ? JSON.stringify(parsed.data.position) : null,
    parsed.data.geometry ? JSON.stringify(parsed.data.geometry) : null,
    JSON.stringify(parsed.data.metadata),
    parsed.data.sortOrder,
    parsed.data.clientOperationId ?? null,
    auth.userId,
    auth.organisationId,
    project.id,
    version.id,
  ).first<{ world_unit: string }>();
  if (!created) throw new Error("Spatial entity was not persisted");
  const worldUnit = parseWorldUnit(created.world_unit);
  await audit(context, auth, "spatial.entity.create", "scene_entity", id, { kind: parsed.data.kind, versionId: version.id });
  return context.json({ entity: { id, ...parsed.data, world_unit: worldUnit } }, 201);
});

app.patch("/api/projects/:projectId/spatial/entities/:entityId", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = sceneEntityUpdateSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const existing = await context.env.DB.prepare(`
    SELECT id, label, description, position_json, geometry_json, metadata_json, sort_order
    FROM scene_entities
    WHERE id = ? AND project_id = ? AND organisation_id = ? AND status = 'active'
  `).bind(
    context.req.param("entityId"),
    context.req.param("projectId"),
    auth.organisationId,
  ).first<{
    id: string;
    label: string;
    description: string | null;
    position_json: string | null;
    geometry_json: string | null;
    metadata_json: string;
    sort_order: number;
  }>();
  if (!existing) return notFound(context, "Spatial entity not found");
  const next = {
    label: parsed.data.label ?? existing.label,
    description: parsed.data.description === undefined
      ? existing.description
      : parsed.data.description,
    positionJson: parsed.data.position === undefined
      ? existing.position_json
      : parsed.data.position === null
      ? null
      : JSON.stringify(parsed.data.position),
    geometryJson: parsed.data.geometry === undefined
      ? existing.geometry_json
      : parsed.data.geometry === null
      ? null
      : JSON.stringify(parsed.data.geometry),
    metadataJson: parsed.data.metadata === undefined
      ? existing.metadata_json
      : JSON.stringify(parsed.data.metadata),
    sortOrder: parsed.data.sortOrder ?? existing.sort_order,
  };
  await context.env.DB.prepare(`
    UPDATE scene_entities
    SET label = ?, description = ?, position_json = ?, geometry_json = ?,
      metadata_json = ?, sort_order = ?, updated_at = datetime('now')
    WHERE id = ?
  `).bind(
    next.label,
    next.description,
    next.positionJson,
    next.geometryJson,
    next.metadataJson,
    next.sortOrder,
    existing.id,
  ).run();
  await audit(context, auth, "spatial.entity.update", "scene_entity", existing.id, {
    fields: Object.keys(parsed.data).sort(),
  });
  return context.json({ entity: { id: existing.id, ...next } });
});

app.delete("/api/projects/:projectId/spatial/entities/:entityId", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const result = await context.env.DB.prepare(`
    UPDATE scene_entities SET status = 'archived', updated_at = datetime('now')
    WHERE id = ? AND project_id = ? AND organisation_id = ? AND status = 'active'
    RETURNING id
  `).bind(context.req.param("entityId"), context.req.param("projectId"), auth.organisationId).first();
  if (!result) return notFound(context, "Spatial entity not found");
  await audit(context, auth, "spatial.entity.archive", "scene_entity", context.req.param("entityId"));
  return context.body(null, 204);
});

app.post("/api/projects/:projectId/spatial/navigation-obstacles", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = navigationObstacleSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(
    context.env.DB,
    auth.organisationId,
    context.req.param("projectId"),
  );
  if (!project) return notFound(context, "Project not found");
  const version = await context.env.DB.prepare(
    "SELECT id FROM scene_versions WHERE id = ? AND project_id = ?",
  ).bind(parsed.data.versionId, project.id).first<{ id: string }>();
  if (!version) return notFound(context, "Scene version not found");
  if (parsed.data.clientOperationId) {
    const existing = await context.env.DB.prepare(`
      SELECT * FROM scene_navigation_obstacles
      WHERE organisation_id = ? AND client_operation_id = ?
    `).bind(auth.organisationId, parsed.data.clientOperationId).first();
    if (existing) return context.json({ obstacle: existing, idempotent: true });
  }
  const id = crypto.randomUUID();
  const created = await context.env.DB.prepare(`
    INSERT INTO scene_navigation_obstacles
      (id, organisation_id, project_id, version_id, label, bounds_json,
        metadata_json, client_operation_id, created_by, world_unit)
    SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?,
      COALESCE((
        SELECT world_unit FROM scene_navigation_profiles
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      ), 'metres')
    RETURNING world_unit
  `).bind(
    id,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.label,
    JSON.stringify(parsed.data.geometry),
    JSON.stringify(parsed.data.metadata),
    parsed.data.clientOperationId ?? null,
    auth.userId,
    auth.organisationId,
    project.id,
    version.id,
  ).first<{ world_unit: string }>();
  if (!created) throw new Error("Navigation obstacle was not persisted");
  const worldUnit = parseWorldUnit(created.world_unit);
  await audit(context, auth, "spatial.navigation_obstacle.create", "scene_navigation_obstacle", id, {
    versionId: version.id,
    label: parsed.data.label,
  });
  return context.json({ obstacle: { id, ...parsed.data, world_unit: worldUnit } }, 201);
});

app.delete("/api/projects/:projectId/spatial/navigation-obstacles/:obstacleId", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const result = await context.env.DB.prepare(`
    UPDATE scene_navigation_obstacles
    SET status = 'archived', updated_at = datetime('now')
    WHERE id = ? AND project_id = ? AND organisation_id = ? AND status = 'active'
    RETURNING id
  `).bind(
    context.req.param("obstacleId"),
    context.req.param("projectId"),
    auth.organisationId,
  ).first();
  if (!result) return notFound(context, "Navigation obstacle not found");
  await audit(
    context,
    auth,
    "spatial.navigation_obstacle.archive",
    "scene_navigation_obstacle",
    context.req.param("obstacleId"),
  );
  return context.body(null, 204);
});

type QualifiedTraversalEvidenceOption = {
  assetId: string;
  fileName: string;
  kind: string;
  sha256: string;
  manifestId: string;
  manifestSha256: string;
  manifestCanonicalJson: string;
  manifestAssetSha256: string;
  adapter: string;
  reviewGeneration: number;
  registrationEvidenceAssetId: string;
  registrationEvidenceSha256: string;
  registrationSha256: string;
  sourceToWorld: CaptureSceneRegistration["sourceToWorld"];
};

type PairedCaptureAuthoringRegistration = {
  journeyId: string;
  sourceProvenanceJson: string;
  processorQualified: boolean;
  primaryAssetId: string;
  primarySha256: string;
  evidenceAssetId: string;
  evidenceSha256: string;
  registrationSha256: string;
  receiptSha256: string;
  sourceToWorld: CaptureSceneRegistration["sourceToWorld"];
};

type MeasurementRegistrationGuard =
  | {
    kind: "manifest";
    manifestId: string;
    reviewGeneration: number;
    manifestSha256: string;
    manifestCanonicalJson: string;
    manifestAssetSha256: string;
    adapter: string;
    traversalAssetId: string;
    traversalAssetSha256: string;
    registrationEvidenceAssetId: string;
    registrationEvidenceSha256: string;
  }
  | {
    kind: "paired";
    sourceProvenanceJson: string;
    primaryAssetId: string;
    primaryAssetSha256: string;
    evidenceAssetId: string;
    evidenceAssetSha256: string;
  };

const recognizedMeasurementRegistrationPredicateSql = `(
  (? = 'manifest' AND EXISTS (
    SELECT 1
    FROM capture_bundle_manifests registration_manifest
    JOIN assets registration_manifest_asset
      ON registration_manifest_asset.id = registration_manifest.manifest_asset_id
      AND registration_manifest_asset.organisation_id = registration_manifest.organisation_id
      AND registration_manifest_asset.project_id = registration_manifest.project_id
      AND registration_manifest_asset.version_id = registration_manifest.version_id
    JOIN assets registration_traversal_asset
      ON registration_traversal_asset.organisation_id = registration_manifest.organisation_id
      AND registration_traversal_asset.project_id = registration_manifest.project_id
      AND registration_traversal_asset.version_id = registration_manifest.version_id
    JOIN assets registration_evidence_asset
      ON registration_evidence_asset.organisation_id = registration_manifest.organisation_id
      AND registration_evidence_asset.project_id = registration_manifest.project_id
      AND registration_evidence_asset.version_id = registration_manifest.version_id
    WHERE registration_manifest.id = ?
      AND registration_manifest.organisation_id = ?
      AND registration_manifest.project_id = ?
      AND registration_manifest.version_id = ?
      AND registration_manifest.status = 'reviewed'
      AND registration_manifest.review_decision = 'accepted'
      AND registration_manifest.result != 'blocked'
      AND registration_manifest.review_generation = ?
      AND registration_manifest.manifest_hash = ?
      AND registration_manifest.canonical_manifest_json = ?
      AND COALESCE(registration_manifest.adapter_v2, registration_manifest.adapter) = ?
      AND registration_manifest_asset.kind = 'report'
      AND registration_manifest_asset.format = 'capture-bundle-manifest-json'
      AND registration_manifest_asset.integrity_status = 'verified'
      AND registration_manifest_asset.deleted_at IS NULL
      AND registration_manifest_asset.sha256 = ?
      AND registration_traversal_asset.id = ?
      AND registration_traversal_asset.integrity_status = 'verified'
      AND registration_traversal_asset.deleted_at IS NULL
      AND registration_traversal_asset.sha256 = ?
      AND registration_evidence_asset.id = ?
      AND registration_evidence_asset.integrity_status = 'verified'
      AND registration_evidence_asset.deleted_at IS NULL
      AND registration_evidence_asset.sha256 = ?
  ))
  OR (? = 'paired' AND EXISTS (
    SELECT 1
    FROM scene_versions registered_version
    JOIN assets registered_primary_asset
      ON registered_primary_asset.version_id = registered_version.id
      AND registered_primary_asset.project_id = registered_version.project_id
    JOIN assets registered_evidence_asset
      ON registered_evidence_asset.version_id = registered_version.id
      AND registered_evidence_asset.project_id = registered_version.project_id
    WHERE registered_version.id = ?
      AND registered_version.project_id = ?
      AND registered_version.source_provenance_json = ?
      AND registered_primary_asset.organisation_id = ?
      AND registered_primary_asset.id = ?
      AND registered_primary_asset.integrity_status = 'verified'
      AND registered_primary_asset.deleted_at IS NULL
      AND registered_primary_asset.sha256 = ?
      AND registered_evidence_asset.organisation_id = registered_primary_asset.organisation_id
      AND registered_evidence_asset.id = ?
      AND registered_evidence_asset.kind = 'pointcloud'
      AND registered_evidence_asset.integrity_status = 'verified'
      AND registered_evidence_asset.deleted_at IS NULL
      AND registered_evidence_asset.sha256 = ?
  ))
)`;

const metricSpatialVersionPredicateSql = `(
  NOT EXISTS (
    SELECT 1 FROM scene_navigation_profiles
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND world_unit <> 'metres'
    UNION ALL
    SELECT 1 FROM scene_entities
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND status = 'active' AND world_unit <> 'metres'
    UNION ALL
    SELECT 1 FROM scene_navigation_obstacles
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND status = 'active' AND world_unit <> 'metres'
  )
)`;

function measurementRegistrationGuardBindings(
  guard: MeasurementRegistrationGuard | null,
  organisationId: string,
  projectId: string,
  versionId: string,
): Array<string | number> {
  const manifest = guard?.kind === "manifest" ? guard : null;
  const paired = guard?.kind === "paired" ? guard : null;
  return [
    manifest?.kind ?? "none",
    manifest?.manifestId ?? "",
    organisationId,
    projectId,
    versionId,
    manifest?.reviewGeneration ?? 0,
    manifest?.manifestSha256 ?? "",
    manifest?.manifestCanonicalJson ?? "",
    manifest?.adapter ?? "",
    manifest?.manifestAssetSha256 ?? "",
    manifest?.traversalAssetId ?? "",
    manifest?.traversalAssetSha256 ?? "",
    manifest?.registrationEvidenceAssetId ?? "",
    manifest?.registrationEvidenceSha256 ?? "",
    paired?.kind ?? "none",
    versionId,
    projectId,
    paired?.sourceProvenanceJson ?? "",
    organisationId,
    paired?.primaryAssetId ?? "",
    paired?.primaryAssetSha256 ?? "",
    paired?.evidenceAssetId ?? "",
    paired?.evidenceAssetSha256 ?? "",
  ];
}

function metricSpatialVersionBindings(
  organisationId: string,
  projectId: string,
  versionId: string,
): string[] {
  return [
    organisationId, projectId, versionId,
    organisationId, projectId, versionId,
    organisationId, projectId, versionId,
  ];
}

type QualifiedSceneRegistration = {
  // A measured registration is always metric, but a shell authored on a
  // provisional scene-unit visual registers the same frame without inventing a
  // metre scale for it, so the unit stays open here.
  sourceToWorld: SourceToWorldTransform;
  receipt: Record<string, unknown>;
};

async function pairedCaptureAuthoringRegistration(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<PairedCaptureAuthoringRegistration | null> {
  const version = await database.prepare(`
    SELECT source_provenance_json
    FROM scene_versions
    WHERE id = ? AND project_id = ?
  `).bind(versionId, projectId).first<{ source_provenance_json: string }>();
  if (!version) return null;
  const journey = storedPairedCaptureJourney(version.source_provenance_json);
  if (!journey?.geometryAssetId || !pairedCaptureJourneyHasAcceptedRegistration(journey)) return null;
  const assets = await database.prepare(`
    SELECT id, kind, sha256, integrity_status, deleted_at
    FROM assets
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND id IN (?, ?)
  `).bind(
    organisationId,
    projectId,
    versionId,
    journey.primaryAssetId,
    journey.geometryAssetId,
  ).all<{
    id: string;
    kind: string;
    sha256: string | null;
    integrity_status: string;
    deleted_at: string | null;
  }>();
  const primary = assets.results.find((candidate) => candidate.id === journey.primaryAssetId);
  const geometry = assets.results.find((candidate) => candidate.id === journey.geometryAssetId);
  if (
    !primary || primary.integrity_status !== "verified" || primary.deleted_at ||
    !primary.sha256 || !/^[a-f0-9]{64}$/i.test(primary.sha256) ||
    !geometry || geometry.kind !== "pointcloud" ||
    geometry.integrity_status !== "verified" || geometry.deleted_at ||
    !geometry.sha256 || !/^[a-f0-9]{64}$/i.test(geometry.sha256)
  ) return null;
  const automaticQualification = pairedCaptureJourneyMeetsAssurance(
      journey,
      "processor-qualified",
    ) && journey.qualification?.method ===
      AUTOMATIC_PAIRED_CAPTURE_METHOD &&
      journey.qualification.status === "verified"
    ? journey.qualification
    : null;
  const registrationPayload = captureSceneRegistrationPayload({
    schemaVersion: CAPTURE_SCENE_REGISTRATION_SCHEMA_VERSION,
    sourceCoordinateFrameId: journey.sourceCoordinateFrameId,
    targetCoordinateFrameId: SCENE_WORLD_COORDINATE_FRAME,
    evidenceAssetId: geometry.id,
    evidenceSha256: geometry.sha256,
    method: automaticQualification
      ? "Processor-verified paired PLY coordinates: embedded frame identity, metre scale, Y-up axis, and exact vertex bounds overlap."
      : "Operator-attested paired export: the visual splat and registered metric point cloud are direct exports of one capture and retain the same right-handed Y-up metre frame.",
    sourceToWorld: pairedCaptureIdentityTransform,
  });
  const registrationSha256 = await sha256Hex(JSON.stringify(registrationPayload));
  const receiptPayload = {
    schemaVersion: "paired-capture-authoring-receipt-v1",
    journeyId: journey.id,
    sourceCoordinateFrameId: journey.sourceCoordinateFrameId,
    primaryAsset: {
      id: journey.primaryAssetId,
      sha256: primary.sha256.toLowerCase(),
    },
    geometryAsset: {
      id: geometry.id,
      sha256: geometry.sha256.toLowerCase(),
    },
    qualification: journey.qualification ?? {
      method: ATTESTED_PAIRED_CAPTURE_METHOD,
      status: "verified",
      legacyReceipt: true,
    },
    registrationSha256,
  };
  return {
    journeyId: journey.id,
    sourceProvenanceJson: version.source_provenance_json,
    processorQualified: Boolean(automaticQualification),
    primaryAssetId: journey.primaryAssetId,
    primarySha256: primary.sha256.toLowerCase(),
    evidenceAssetId: geometry.id,
    evidenceSha256: geometry.sha256.toLowerCase(),
    registrationSha256,
    receiptSha256: await sha256Hex(JSON.stringify(receiptPayload)),
    sourceToWorld: pairedCaptureIdentityTransform,
  };
}

/**
 * Registration for a shell an operator drew directly on one visual master.
 *
 * A scene reconstructed from a single visual has no separately registered
 * geometry to align against, so neither a capture manifest nor a paired journey
 * can ever describe it — yet its frames do coincide, because the operator
 * authored the shell on that exact master and no transform was applied. The
 * approved build states which master it was drawn against; this re-derives the
 * binding from the version's own verified asset rows, so the receipt rests on a
 * digest the Worker checked rather than on anything an operator asserted.
 *
 * It establishes the frame, not the geometry. A shell can still disagree with
 * the capture it was drawn on, which is what the shell-capture agreement
 * command exists to surface.
 */
async function authoredShellVisualRegistration(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<QualifiedSceneRegistration | null> {
  const build = await database.prepare(`
    SELECT artifact_json
    FROM scene_navigation_builds
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND status = 'APPROVED' AND artifact_json IS NOT NULL
    ORDER BY reviewed_at DESC, created_at DESC
    LIMIT 1
  `).bind(organisationId, projectId, versionId).first<{ artifact_json: string }>();
  if (!build?.artifact_json) return null;
  const artifact = parseStoredObject(build.artifact_json);
  const source = artifact && typeof artifact === "object"
    ? Reflect.get(artifact, "source")
    : null;
  const binding = source && typeof source === "object"
    ? Reflect.get(source, "authoredVisualBinding")
    : null;
  const declaredSha256 = binding && typeof binding === "object"
    ? readNullableStringProperty(binding, "visualMasterSha256")
    : null;
  if (!declaredSha256 || !/^[a-f0-9]{64}$/i.test(declaredSha256)) return null;
  const master = await database.prepare(`
    SELECT id, sha256
    FROM assets
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND kind = 'master' AND integrity_status = 'verified'
      AND deleted_at IS NULL AND lower(sha256) = lower(?)
    LIMIT 1
  `).bind(organisationId, projectId, versionId, declaredSha256).first<{
    id: string;
    sha256: string;
  }>();
  if (!master) return null;
  const coordinateSystem = artifact && typeof artifact === "object"
    ? Reflect.get(artifact, "coordinateSystem")
    : null;
  const worldUnit = coordinateSystem && typeof coordinateSystem === "object" &&
      readNullableStringProperty(coordinateSystem, "worldUnit") === "metres"
    ? "metres" as const
    : "scene_units" as const;
  return {
    sourceToWorld: {
      sourceUpAxis: "Y",
      worldUnit,
      metresPerSourceUnit: 1,
      yawDegrees: 0,
      translationMetres: [0, 0, 0],
    },
    receipt: {
      source: "authored-shell-visual-binding",
      visualMasterAssetId: master.id,
      visualMasterSha256: master.sha256.toLowerCase(),
      method:
        "The approved structural shell names this exact verified visual master; " +
        "the shell was authored on it, so the scene frame is the capture frame " +
        "with no transform applied.",
    },
  };
}

async function qualifiedSceneRegistration(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<QualifiedSceneRegistration | null> {
  const [manifestRegistrations, pairedRegistration] = await Promise.all([
    qualifiedTraversalEvidenceOptions(database, organisationId, projectId, versionId),
    pairedCaptureAuthoringRegistration(database, organisationId, projectId, versionId),
  ]);
  const manifestRegistration = manifestRegistrations[0];
  if (manifestRegistration) {
    return {
      sourceToWorld: manifestRegistration.sourceToWorld,
      receipt: {
        source: "accepted-capture-manifest",
        manifestId: manifestRegistration.manifestId,
        manifestSha256: manifestRegistration.manifestSha256,
        transformSha256: manifestRegistration.registrationSha256,
      },
    };
  }
  if (!pairedRegistration) {
    // Last, because a measured registration should always outrank a frame that
    // coincides only because the shell was drawn on the visual.
    return authoredShellVisualRegistration(database, organisationId, projectId, versionId);
  }
  return {
    sourceToWorld: pairedRegistration.sourceToWorld,
    receipt: {
      source: "paired-capture-journey",
      journeyId: pairedRegistration.journeyId,
      primaryAssetId: pairedRegistration.primaryAssetId,
      primarySha256: pairedRegistration.primarySha256,
      evidenceAssetId: pairedRegistration.evidenceAssetId,
      evidenceSha256: pairedRegistration.evidenceSha256,
      transformSha256: pairedRegistration.registrationSha256,
      receiptSha256: pairedRegistration.receiptSha256,
    },
  };
}

async function qualifiedTraversalEvidenceOptions(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<QualifiedTraversalEvidenceOption[]> {
  const results = await database.batch([
    database.prepare(`
      SELECT manifest.id, manifest.project_id AS manifest_project_id,
        manifest.version_id AS manifest_version_id, manifest.manifest_asset_id,
        manifest.manifest_hash, manifest.canonical_manifest_json,
        manifest.review_generation, manifest_asset.sha256 AS manifest_asset_sha256,
        COALESCE(manifest.adapter_v2, manifest.adapter) AS adapter
      FROM capture_bundle_manifests manifest
      JOIN assets manifest_asset
        ON manifest_asset.id = manifest.manifest_asset_id
        AND manifest_asset.organisation_id = manifest.organisation_id
        AND manifest_asset.project_id = manifest.project_id
        AND manifest_asset.version_id = manifest.version_id
        AND manifest_asset.kind = 'report'
        AND manifest_asset.format = 'capture-bundle-manifest-json'
        AND manifest_asset.integrity_status = 'verified'
        AND manifest_asset.deleted_at IS NULL
      WHERE manifest.organisation_id = ? AND manifest.project_id = ?
        AND manifest.version_id = ? AND manifest.status = 'reviewed'
        AND manifest.review_decision = 'accepted' AND manifest.result != 'blocked'
        AND EXISTS (
          SELECT 1
          FROM json_each(
            CASE WHEN json_valid(manifest.canonical_manifest_json)
              THEN manifest.canonical_manifest_json ELSE '{"assets":[]}' END,
            '$.assets'
          ) declaration
          JOIN json_each(
            CASE WHEN json_valid(declaration.value)
              THEN declaration.value ELSE '{"roles":[]}' END,
            '$.roles'
          ) role
          WHERE role.value = 'traversal_evidence'
        )
      ORDER BY manifest.created_at DESC, manifest.id
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      WITH reviewed_manifests AS (
        SELECT canonical_manifest_json
        FROM capture_bundle_manifests
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
          AND status = 'reviewed' AND review_decision = 'accepted'
          AND result != 'blocked' AND json_valid(canonical_manifest_json)
      ), declared_asset_ids AS (
        SELECT DISTINCT json_extract(declaration.value, '$.id') AS asset_id
        FROM reviewed_manifests manifest
        JOIN json_each(manifest.canonical_manifest_json, '$.assets') declaration
        WHERE json_valid(declaration.value) AND (
          json_extract(declaration.value, '$.id') = json_extract(
            manifest.canonical_manifest_json,
            '$.sceneRegistration.evidenceAssetId'
          ) OR EXISTS (
            SELECT 1 FROM json_each(declaration.value, '$.roles') role
            WHERE role.value = 'traversal_evidence'
          )
        )
      )
      SELECT asset.id, asset.file_name, asset.kind, asset.sha256
      FROM declared_asset_ids declaration
      JOIN assets asset ON asset.id = declaration.asset_id
      WHERE asset.organisation_id = ? AND asset.project_id = ? AND asset.version_id = ?
        AND asset.integrity_status = 'verified' AND asset.deleted_at IS NULL
        AND asset.sha256 IS NOT NULL
      ORDER BY asset.id
    `).bind(
      organisationId,
      projectId,
      versionId,
      organisationId,
      projectId,
      versionId,
    ),
  ]);
  const assets = new Map(
    requiredBatchResult(results, 1).results.flatMap((candidate) => {
      if (!candidate || typeof candidate !== "object") return [];
      const id = readStringProperty(candidate, "id");
      const fileName = readStringProperty(candidate, "file_name");
      const kind = readStringProperty(candidate, "kind");
      const sha256 = readStringProperty(candidate, "sha256")?.toLowerCase();
      return id && fileName && kind && sha256 && /^[a-f0-9]{64}$/.test(sha256)
        ? [[id, { assetId: id, fileName, kind, sha256 }] as const]
        : [];
    }),
  );
  const optionGroups = await Promise.all(
    requiredBatchResult(results, 0).results.map((candidate) =>
      qualifiedTraversalEvidenceFromManifest(candidate, assets)
    ),
  );
  const options = new Map<string, QualifiedTraversalEvidenceOption>();
  for (const option of optionGroups.flat()) {
    options.set(`${option.manifestId}:${option.assetId}`, option);
  }
  return [...options.values()];
}

async function qualifiedTraversalEvidenceFromManifest(
  candidate: unknown,
  assets: ReadonlyMap<string, {
    assetId: string;
    fileName: string;
    kind: string;
    sha256: string;
  }>,
): Promise<QualifiedTraversalEvidenceOption[]> {
  if (!candidate || typeof candidate !== "object") return [];
  const manifestId = readStringProperty(candidate, "id");
  const manifestProjectId = readStringProperty(candidate, "manifest_project_id");
  const manifestVersionId = readStringProperty(candidate, "manifest_version_id");
  const manifestAssetId = readStringProperty(candidate, "manifest_asset_id");
  const manifestAssetSha256 = readStringProperty(candidate, "manifest_asset_sha256")
    ?.toLowerCase();
  const manifestSha256 = readStringProperty(candidate, "manifest_hash")?.toLowerCase();
  const canonicalManifestJson = readStringProperty(candidate, "canonical_manifest_json");
  const adapter = readStringProperty(candidate, "adapter");
  const reviewGeneration = Number(Reflect.get(candidate, "review_generation"));
  if (
    !manifestId || !manifestProjectId || !manifestVersionId || !manifestAssetId ||
    !manifestAssetSha256 || !manifestSha256 || manifestAssetSha256 !== manifestSha256 ||
    !canonicalManifestJson || !adapter ||
    !Number.isSafeInteger(reviewGeneration) || reviewGeneration < 1 ||
    await sha256Hex(canonicalManifestJson) !== manifestSha256
  ) return [];
  let manifest: unknown;
  try {
    manifest = JSON.parse(canonicalManifestJson);
  } catch {
    return [];
  }
  if (
    !manifest || typeof manifest !== "object" ||
    Reflect.get(manifest, "format") !== "whymelabs.spatial.capture-bundle" ||
    Reflect.get(manifest, "schemaVersion") !== "1.0.0" ||
    Reflect.get(manifest, "manifestId") !== manifestId
  ) return [];
  const manifestProject = Reflect.get(manifest, "project");
  const manifestVersion = Reflect.get(manifest, "version");
  if (
    !manifestProject || typeof manifestProject !== "object" ||
    Reflect.get(manifestProject, "id") !== manifestProjectId ||
    Reflect.get(manifestProject, "captureAdapter") !== adapter ||
    !manifestVersion || typeof manifestVersion !== "object" ||
    Reflect.get(manifestVersion, "id") !== manifestVersionId
  ) return [];
  const declarations = Reflect.get(manifest, "assets");
  if (!Array.isArray(declarations)) return [];
  const sceneRegistration = parseCaptureSceneRegistration(
    Reflect.get(manifest, "sceneRegistration"),
  );
  const coordinateFrame = Reflect.get(manifest, "coordinateFrame");
  if (
    !sceneRegistration || !coordinateFrame || typeof coordinateFrame !== "object" ||
    Reflect.get(coordinateFrame, "id") !== sceneRegistration.sourceCoordinateFrameId ||
    !captureSceneRegistrationMatchesCoordinateFrame(sceneRegistration, coordinateFrame) ||
    await sha256Hex(JSON.stringify(captureSceneRegistrationPayload(sceneRegistration))) !==
      sceneRegistration.transformSha256
  ) return [];
  const registrationEvidence = assets.get(sceneRegistration.evidenceAssetId);
  const registrationDeclaration = declarations.find((declaration) =>
    declaration && typeof declaration === "object" &&
    Reflect.get(declaration, "id") === sceneRegistration.evidenceAssetId
  );
  if (
    !registrationEvidence ||
    registrationEvidence.sha256 !== sceneRegistration.evidenceSha256 ||
    !registrationDeclaration ||
    readStringProperty(registrationDeclaration, "sha256")?.toLowerCase() !==
      sceneRegistration.evidenceSha256
  ) return [];
  return declarations.flatMap((declaration): QualifiedTraversalEvidenceOption[] => {
    if (!declaration || typeof declaration !== "object") return [];
    const roles = Reflect.get(declaration, "roles");
    if (!Array.isArray(roles) || !roles.includes("traversal_evidence")) return [];
    const assetId = readStringProperty(declaration, "id");
    const declaredSha256 = readStringProperty(declaration, "sha256")?.toLowerCase();
    const asset = assetId ? assets.get(assetId) : null;
    return asset && declaredSha256 === asset.sha256
      ? [{
        ...asset,
        manifestId,
        manifestSha256,
        manifestCanonicalJson: canonicalManifestJson,
        manifestAssetSha256,
        adapter,
        reviewGeneration,
        registrationEvidenceAssetId: registrationEvidence.assetId,
        registrationEvidenceSha256: registrationEvidence.sha256,
        registrationSha256: sceneRegistration.transformSha256,
        sourceToWorld: sceneRegistration.sourceToWorld,
      }]
      : [];
  });
}

async function verifiedTraversalEvidence(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
  assetId: string,
  manifestId: string,
): Promise<{
  id: string;
  sha256: string;
  manifestId: string;
  manifestSha256: string;
  adapter: string;
  reviewGeneration: number;
  registrationSha256: string;
  sourceToWorld: CaptureSceneRegistration["sourceToWorld"];
} | null> {
  const row = await database.prepare(`
    SELECT manifest.id, manifest.project_id AS manifest_project_id,
      manifest.version_id AS manifest_version_id, manifest.manifest_asset_id,
      manifest.manifest_hash, manifest.canonical_manifest_json,
      manifest.review_generation, manifest_asset.sha256 AS manifest_asset_sha256,
      COALESCE(manifest.adapter_v2, manifest.adapter) AS adapter,
      asset.id AS asset_id, asset.file_name AS asset_file_name,
      asset.kind AS asset_kind, asset.sha256 AS asset_sha256
    FROM capture_bundle_manifests manifest
    JOIN assets manifest_asset
      ON manifest_asset.id = manifest.manifest_asset_id
      AND manifest_asset.organisation_id = manifest.organisation_id
      AND manifest_asset.project_id = manifest.project_id
      AND manifest_asset.version_id = manifest.version_id
      AND manifest_asset.kind = 'report'
      AND manifest_asset.format = 'capture-bundle-manifest-json'
      AND manifest_asset.integrity_status = 'verified'
      AND manifest_asset.deleted_at IS NULL
    JOIN assets asset ON asset.id = ?
    WHERE manifest.id = ? AND manifest.organisation_id = ?
      AND manifest.project_id = ? AND manifest.version_id = ?
      AND manifest.status = 'reviewed' AND manifest.review_decision = 'accepted'
      AND manifest.result != 'blocked'
      AND asset.organisation_id = manifest.organisation_id
      AND asset.project_id = manifest.project_id AND asset.version_id = manifest.version_id
      AND asset.integrity_status = 'verified' AND asset.deleted_at IS NULL
      AND asset.sha256 IS NOT NULL
  `).bind(assetId, manifestId, organisationId, projectId, versionId).first();
  if (!row) return null;
  const canonicalManifestJson = readStringProperty(row, "canonical_manifest_json");
  if (!canonicalManifestJson) return null;
  let canonicalManifest: unknown;
  try {
    canonicalManifest = JSON.parse(canonicalManifestJson);
  } catch {
    return null;
  }
  const registration = parseCaptureSceneRegistration(
    canonicalManifest && typeof canonicalManifest === "object"
      ? Reflect.get(canonicalManifest, "sceneRegistration")
      : null,
  );
  if (!registration) return null;
  const registrationAsset = registration.evidenceAssetId === assetId
    ? row
    : await database.prepare(`
      SELECT id AS asset_id, file_name AS asset_file_name, kind AS asset_kind,
        sha256 AS asset_sha256
      FROM assets
      WHERE id = ? AND organisation_id = ? AND project_id = ? AND version_id = ?
        AND integrity_status = 'verified' AND deleted_at IS NULL AND sha256 IS NOT NULL
    `).bind(
      registration.evidenceAssetId,
      organisationId,
      projectId,
      versionId,
    ).first();
  if (!registrationAsset) return null;
  const assets = new Map<string, {
    assetId: string;
    fileName: string;
    kind: string;
    sha256: string;
  }>();
  for (const candidate of [row, registrationAsset]) {
    const id = readStringProperty(candidate, "asset_id");
    const fileName = readStringProperty(candidate, "asset_file_name");
    const kind = readStringProperty(candidate, "asset_kind");
    const sha256 = readStringProperty(candidate, "asset_sha256")?.toLowerCase();
    if (id && fileName && kind && sha256 && /^[a-f0-9]{64}$/.test(sha256)) {
      assets.set(id, { assetId: id, fileName, kind, sha256 });
    }
  }
  const option = (await qualifiedTraversalEvidenceFromManifest(row, assets)).find(
    (candidate) => candidate.assetId === assetId,
  );
  return option ? {
    id: option.assetId,
    sha256: option.sha256,
    manifestId: option.manifestId,
    manifestSha256: option.manifestSha256,
    adapter: option.adapter,
    reviewGeneration: option.reviewGeneration,
    registrationSha256: option.registrationSha256,
    sourceToWorld: option.sourceToWorld,
  } : null;
}

function captureSceneRegistrationMatchesCoordinateFrame(
  registration: CaptureSceneRegistration,
  coordinateFrame: object,
): boolean {
  const units = Reflect.get(coordinateFrame, "units");
  const axisConvention = Reflect.get(coordinateFrame, "axisConvention");
  const expectedScale = units === "metres" ? 1 : units === "millimetres" ? 0.001 : null;
  const expectedUpAxis = typeof axisConvention === "string" && axisConvention.endsWith("y-up")
    ? "Y"
    : typeof axisConvention === "string" && axisConvention.endsWith("z-up") ? "Z" : null;
  return typeof axisConvention === "string" && axisConvention.startsWith("right-handed") &&
    expectedScale !== null &&
    registration.sourceToWorld.metresPerSourceUnit === expectedScale &&
    registration.sourceToWorld.sourceUpAxis === expectedUpAxis;
}

async function hasMetricNavigationProfile(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<boolean> {
  return Boolean(await database.prepare(`
    SELECT 1 AS metric
    FROM scene_navigation_profiles
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND world_unit = 'metres'
  `).bind(organisationId, projectId, versionId).first<{ metric: number }>());
}

app.post("/api/projects/:projectId/spatial/navigation-traversals", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = navigationTraversalCreateSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(
    context.env.DB,
    auth.organisationId,
    context.req.param("projectId"),
  );
  if (!project) return notFound(context, "Project not found");
  const version = await context.env.DB.prepare(
    "SELECT id FROM scene_versions WHERE id = ? AND project_id = ?",
  ).bind(parsed.data.versionId, project.id).first<{ id: string }>();
  if (!version) return notFound(context, "Scene version not found");
  const requestHash = await sha256Hex(JSON.stringify(parsed.data));
  const existing = await context.env.DB.prepare(`
    SELECT * FROM scene_navigation_traversals
    WHERE organisation_id = ? AND client_operation_id = ?
  `).bind(auth.organisationId, parsed.data.clientOperationId).first();
  if (existing) {
    if (readStringProperty(existing, "request_hash") !== requestHash) {
      return conflict(
        context,
        "Operation ID was already used for a different authored traversal request",
      );
    }
    return context.json({ traversal: existing, idempotent: true });
  }
  if (!await hasMetricNavigationProfile(
    context.env.DB,
    auth.organisationId,
    project.id,
    version.id,
  )) {
    return conflict(
      context,
      "Capture-registered traversal authoring requires a metric navigation profile for this scene version",
    );
  }
  const evidence = await verifiedTraversalEvidence(
    context.env.DB,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.evidenceAssetId,
    parsed.data.evidenceManifestId,
  );
  if (!evidence) {
    return unprocessable(context, {
      evidenceManifestId: [
        "Choose an accepted non-blocked capture manifest from this scene version with a verified numerical capture-to-scene registration that declares the selected asset as traversal_evidence",
      ],
    }, "Traversal evidence needs a registered capture manifest");
  }
  const sourcePath = parsed.data.sourcePath as Vector3Tuple[];
  const worldPath = sourcePath.map((point) =>
    transformSourcePoint(point, evidence.sourceToWorld)
  );
  const id = crypto.randomUUID();
  const traversal = await context.env.DB.prepare(`
    INSERT INTO scene_navigation_traversals (
      id, organisation_id, project_id, version_id, traversal_kind, label,
      path_json, bidirectional, speed_units_per_second, reviewed_purpose,
      evidence_asset_id, evidence_sha256, evidence_manifest_id,
      evidence_manifest_sha256, evidence_adapter,
      evidence_manifest_review_generation, evidence_registration_sha256,
      evidence_source_to_world_json, evidence_source_path_json,
      client_operation_id, request_hash, created_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(organisation_id, client_operation_id) DO NOTHING
    RETURNING *
  `).bind(
    id,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.traversalKind,
    parsed.data.label,
    JSON.stringify(worldPath),
    parsed.data.bidirectional ? 1 : 0,
    parsed.data.speedUnitsPerSecond,
    parsed.data.reviewedPurpose,
    evidence.id,
    evidence.sha256,
    evidence.manifestId,
    evidence.manifestSha256,
    evidence.adapter,
    evidence.reviewGeneration,
    evidence.registrationSha256,
    JSON.stringify(evidence.sourceToWorld),
    JSON.stringify(sourcePath),
    parsed.data.clientOperationId,
    requestHash,
    auth.userId,
  ).first();
  if (!traversal) {
    const concurrent = await context.env.DB.prepare(`
      SELECT * FROM scene_navigation_traversals
      WHERE organisation_id = ? AND client_operation_id = ?
    `).bind(auth.organisationId, parsed.data.clientOperationId).first();
    if (!concurrent) throw new Error("Authored navigation traversal was not persisted");
    if (readStringProperty(concurrent, "request_hash") !== requestHash) {
      return conflict(
        context,
        "Operation ID was already used for a different authored traversal request",
      );
    }
    return context.json({ traversal: concurrent, idempotent: true });
  }
  await audit(
    context,
    auth,
    "spatial.navigation_traversal.create",
    "scene_navigation_traversal",
    id,
    {
      versionId: version.id,
      traversalKind: parsed.data.traversalKind,
      bidirectional: parsed.data.bidirectional,
    },
  );
  return context.json({ traversal }, 201);
});

app.patch(
  "/api/projects/:projectId/spatial/navigation-traversals/:traversalId",
  async (context) => {
    const auth = await requireOperator(context);
    if (auth instanceof Response) return auth;
    if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
    const parsed = navigationTraversalUpdateSchema.safeParse(await readJson(context));
    if (!parsed.success) return validationError(context, parsed.error.flatten());
    const existing = await context.env.DB.prepare(`
      SELECT id, version_id, traversal_kind, label, path_json, bidirectional,
        speed_units_per_second, reviewed_purpose, evidence_asset_id, evidence_sha256,
        evidence_manifest_id, evidence_manifest_sha256, evidence_adapter,
        evidence_manifest_review_generation, evidence_registration_sha256,
        evidence_source_to_world_json, evidence_source_path_json
      FROM scene_navigation_traversals
      WHERE id = ? AND project_id = ? AND organisation_id = ? AND status = 'active'
    `).bind(
      context.req.param("traversalId"),
      context.req.param("projectId"),
      auth.organisationId,
    ).first<{
      id: string;
      version_id: string;
      traversal_kind: string;
      label: string;
      path_json: string;
      bidirectional: number;
      speed_units_per_second: number;
      reviewed_purpose: string;
      evidence_asset_id: string;
      evidence_sha256: string;
      evidence_manifest_id: string;
      evidence_manifest_sha256: string;
      evidence_adapter: string;
      evidence_manifest_review_generation: number;
      evidence_registration_sha256: string;
      evidence_source_to_world_json: string;
      evidence_source_path_json: string;
    }>();
    if (!existing) return notFound(context, "Authored navigation traversal not found");
    if (!await hasMetricNavigationProfile(
      context.env.DB,
      auth.organisationId,
      context.req.param("projectId"),
      existing.version_id,
    )) {
      return conflict(
        context,
        "Capture-registered traversal authoring requires a metric navigation profile for this scene version",
      );
    }
    const evidence = await verifiedTraversalEvidence(
      context.env.DB,
      auth.organisationId,
      context.req.param("projectId"),
      existing.version_id,
      parsed.data.evidenceAssetId ?? existing.evidence_asset_id,
      parsed.data.evidenceManifestId ?? existing.evidence_manifest_id,
    );
    if (!evidence) {
      return unprocessable(context, {
        evidenceManifestId: [
          "Choose an accepted non-blocked capture manifest from this scene version with a verified numerical capture-to-scene registration that declares the selected asset as traversal_evidence",
        ],
      }, "Traversal evidence needs a registered capture manifest");
    }
    if (
      parsed.data.sourcePath === undefined &&
      evidence.registrationSha256 !== existing.evidence_registration_sha256
    ) {
      return unprocessable(context, {
        sourcePath: [
          "Changing the capture registration requires a path authored in the new capture frame",
        ],
      }, "Traversal needs capture-frame coordinates for the selected registration");
    }
    const sourcePath = parsed.data.sourcePath ?? canonicalTraversalSourcePath(
      existing.evidence_source_path_json,
    );
    if (!sourcePath) {
      return unprocessable(context, {
        sourcePath: [
          "This legacy traversal has no capture-frame path; archive it and author a new evidence-derived traversal",
        ],
      }, "Traversal needs capture-frame coordinates");
    }
    const worldPath = sourcePath.map((point) =>
      transformSourcePoint(point, evidence.sourceToWorld)
    );
    const traversal = await context.env.DB.prepare(`
      UPDATE scene_navigation_traversals
      SET traversal_kind = ?, label = ?, path_json = ?, bidirectional = ?,
        speed_units_per_second = ?, reviewed_purpose = ?, evidence_asset_id = ?,
        evidence_sha256 = ?, evidence_manifest_id = ?,
        evidence_manifest_sha256 = ?, evidence_adapter = ?,
        evidence_manifest_review_generation = ?, evidence_registration_sha256 = ?,
        evidence_source_to_world_json = ?, evidence_source_path_json = ?,
        updated_at = datetime('now')
      WHERE id = ?
      RETURNING *
    `).bind(
      parsed.data.traversalKind ?? existing.traversal_kind,
      parsed.data.label ?? existing.label,
      JSON.stringify(worldPath),
      parsed.data.bidirectional === undefined
        ? existing.bidirectional
        : parsed.data.bidirectional ? 1 : 0,
      parsed.data.speedUnitsPerSecond ?? existing.speed_units_per_second,
      parsed.data.reviewedPurpose ?? existing.reviewed_purpose,
      evidence.id,
      evidence.sha256,
      evidence.manifestId,
      evidence.manifestSha256,
      evidence.adapter,
      evidence.reviewGeneration,
      evidence.registrationSha256,
      JSON.stringify(evidence.sourceToWorld),
      JSON.stringify(sourcePath),
      existing.id,
    ).first();
    await audit(
      context,
      auth,
      "spatial.navigation_traversal.update",
      "scene_navigation_traversal",
      existing.id,
      { fields: Object.keys(parsed.data).sort() },
    );
    return context.json({ traversal });
  },
);

app.delete(
  "/api/projects/:projectId/spatial/navigation-traversals/:traversalId",
  async (context) => {
    const auth = await requireOperator(context);
    if (auth instanceof Response) return auth;
    if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
    const result = await context.env.DB.prepare(`
      UPDATE scene_navigation_traversals
      SET status = 'archived', updated_at = datetime('now')
      WHERE id = ? AND project_id = ? AND organisation_id = ? AND status = 'active'
      RETURNING id
    `).bind(
      context.req.param("traversalId"),
      context.req.param("projectId"),
      auth.organisationId,
    ).first();
    if (!result) return notFound(context, "Authored navigation traversal not found");
    await audit(
      context,
      auth,
      "spatial.navigation_traversal.archive",
      "scene_navigation_traversal",
      context.req.param("traversalId"),
    );
    return context.body(null, 204);
  },
);

app.put("/api/projects/:projectId/spatial/navigation-profile", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = navigationProfileSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(
    context.env.DB,
    auth.organisationId,
    context.req.param("projectId"),
  );
  if (!project) return notFound(context, "Project not found");
  const version = await context.env.DB.prepare(
    "SELECT id FROM scene_versions WHERE id = ? AND project_id = ?",
  ).bind(parsed.data.versionId, project.id).first<{ id: string }>();
  if (!version) return notFound(context, "Scene version not found");
  const currentProfileAndTraversal = await context.env.DB.batch([
    context.env.DB.prepare(`
      SELECT world_unit, agent_radius, max_step_metres, max_slope_degrees
      FROM scene_navigation_profiles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
    `).bind(auth.organisationId, project.id, version.id),
    context.env.DB.prepare(`
      SELECT id FROM scene_navigation_traversals
      WHERE organisation_id = ? AND project_id = ? AND version_id = ? AND status = 'active'
      LIMIT 1
    `).bind(auth.organisationId, project.id, version.id),
  ]);
  const currentProfile = requiredBatchResult(currentProfileAndTraversal, 0).results[0] as
    | {
      world_unit?: string;
      agent_radius?: number;
      max_step_metres?: number;
      max_slope_degrees?: number;
    }
    | undefined;
  const currentWorldUnit = currentProfile?.world_unit;
  if (
    currentWorldUnit && currentWorldUnit !== parsed.data.worldUnit &&
    requiredBatchResult(currentProfileAndTraversal, 1).results.length
  ) {
    return conflict(
      context,
      "Authored traversal coordinates fix this version's world unit. Create a new version instead of relabelling them.",
    );
  }
  const profileUpdate = context.env.DB.prepare(`
    INSERT INTO scene_navigation_profiles (
      version_id, organisation_id, project_id, world_unit, agent_radius,
      agent_height, eye_height, max_step_metres, max_slope_degrees,
      max_speed, max_acceleration, updated_by
    )
    SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
    WHERE NOT EXISTS (
      SELECT 1 FROM scene_entities
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND status = 'active' AND world_unit <> ?
      UNION ALL
      SELECT 1 FROM scene_navigation_obstacles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND status = 'active' AND world_unit <> ?
      UNION ALL
      SELECT 1 FROM measurement_briefs
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND ? <> 'metres'
    )
    ON CONFLICT(version_id) DO UPDATE SET
      world_unit = excluded.world_unit,
      agent_radius = excluded.agent_radius,
      agent_height = excluded.agent_height,
      eye_height = excluded.eye_height,
      max_step_metres = excluded.max_step_metres,
      max_slope_degrees = excluded.max_slope_degrees,
      max_speed = excluded.max_speed,
      max_acceleration = excluded.max_acceleration,
      updated_by = excluded.updated_by,
      updated_at = datetime('now')
    WHERE scene_navigation_profiles.organisation_id = excluded.organisation_id
      AND scene_navigation_profiles.project_id = excluded.project_id
      AND NOT EXISTS (
        SELECT 1 FROM scene_entities
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
          AND status = 'active' AND world_unit <> ?
        UNION ALL
        SELECT 1 FROM scene_navigation_obstacles
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
          AND status = 'active' AND world_unit <> ?
        UNION ALL
        SELECT 1 FROM measurement_briefs
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
          AND ? <> 'metres'
      )
    RETURNING world_unit
  `).bind(
    version.id,
    auth.organisationId,
    project.id,
    parsed.data.worldUnit,
    parsed.data.agentRadius,
    parsed.data.agentHeight,
    parsed.data.eyeHeight,
    parsed.data.maxStepMetres,
    parsed.data.maxSlopeDegrees,
    parsed.data.maxSpeed,
    parsed.data.maxAcceleration,
    auth.userId,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.worldUnit,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.worldUnit,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.worldUnit,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.worldUnit,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.worldUnit,
    auth.organisationId,
    project.id,
    version.id,
    parsed.data.worldUnit,
  );
  const atomicUpdate = await context.env.DB.batch([profileUpdate]);
  const updatedProfile = requiredBatchResult(atomicUpdate, 0).results[0] as
    | { world_unit: string }
    | undefined;
  if (!updatedProfile) {
    return conflict(
      context,
      "This scene version already contains authored geometry or measurement evidence that fixes another unit. Create a new version instead of relabelling the existing coordinates.",
    );
  }
  await audit(context, auth, "spatial.navigation_profile.update", "scene_version", version.id, {
    worldUnit: parsed.data.worldUnit,
    agentRadius: parsed.data.agentRadius,
    agentHeight: parsed.data.agentHeight,
    eyeHeight: parsed.data.eyeHeight,
    maxStepMetres: parsed.data.maxStepMetres,
    maxSlopeDegrees: parsed.data.maxSlopeDegrees,
    maxSpeed: parsed.data.maxSpeed,
    maxAcceleration: parsed.data.maxAcceleration,
  });
  return context.json({
    navigationProfile: {
      worldUnit: parsed.data.worldUnit,
      agentRadius: parsed.data.agentRadius,
      agentHeight: parsed.data.agentHeight,
      eyeHeight: parsed.data.eyeHeight,
      maxStepMetres: parsed.data.maxStepMetres,
      maxSlopeDegrees: parsed.data.maxSlopeDegrees,
      maxSpeed: parsed.data.maxSpeed,
      maxAcceleration: parsed.data.maxAcceleration,
    },
  });
});

app.post("/api/projects/:projectId/spatial/navigation-builds", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = navigationBuildSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(
    context.env.DB,
    auth.organisationId,
    context.req.param("projectId"),
  );
  if (!project) return notFound(context, "Project not found");
  if (project.status === "ARCHIVED") return conflict(context, "Archived projects cannot build navigation");
  const requestHash = await sha256Hex(JSON.stringify(parsed.data));
  const prior = await context.env.DB.prepare(`
    SELECT id, status, request_hash, job_id FROM scene_navigation_builds
    WHERE organisation_id = ? AND client_operation_id = ?
  `).bind(auth.organisationId, parsed.data.clientOperationId).first<{
    id: string;
    status: string;
    request_hash: string;
    job_id: string;
  }>();
  if (prior) {
    if (prior.request_hash !== requestHash) {
      return conflict(context, "Operation ID was already used for a different navigation build");
    }
    return context.json({ build: prior, idempotent: true });
  }
  const version = await context.env.DB.prepare(`
    SELECT id FROM scene_versions WHERE id = ? AND project_id = ?
  `).bind(parsed.data.versionId, project.id).first<{ id: string }>();
  if (!version) return notFound(context, "Immutable scene version not found");
  const results = await context.env.DB.batch([
    context.env.DB.prepare(`
      SELECT id, version_id, kind, format, integrity_status, sha256
      FROM assets
      WHERE id = ? AND project_id = ? AND organisation_id = ? AND deleted_at IS NULL
    `).bind(parsed.data.collisionAssetId, project.id, auth.organisationId),
    context.env.DB.prepare(`
      SELECT world_unit, agent_radius, agent_height, eye_height, max_step_metres,
        max_slope_degrees, max_speed, max_acceleration
      FROM scene_navigation_profiles
      WHERE version_id = ? AND project_id = ? AND organisation_id = ?
    `).bind(version.id, project.id, auth.organisationId),
    context.env.DB.prepare(`
      SELECT id, kind, label, position_json, geometry_json
      FROM scene_entities
      WHERE version_id = ? AND project_id = ? AND organisation_id = ?
        AND status = 'active' AND kind IN ('room', 'floor', 'doorway')
      ORDER BY kind DESC, sort_order, label
    `).bind(version.id, project.id, auth.organisationId),
    context.env.DB.prepare(`
      SELECT id, label, bounds_json
      FROM scene_navigation_obstacles
      WHERE version_id = ? AND project_id = ? AND organisation_id = ?
        AND status = 'active'
      ORDER BY label, created_at
    `).bind(version.id, project.id, auth.organisationId),
    context.env.DB.prepare(`
      SELECT rs.route_id, rs.entity_id, rs.sequence_number, rs.camera_pose_json,
        e.kind, e.position_json, e.geometry_json
      FROM scene_route_stops rs
      JOIN scene_routes r ON r.id = rs.route_id
      JOIN scene_entities e ON e.id = rs.entity_id
      WHERE r.version_id = ? AND r.project_id = ? AND r.organisation_id = ?
        AND r.status = 'active' AND e.status = 'active'
      ORDER BY rs.route_id, rs.sequence_number
    `).bind(version.id, project.id, auth.organisationId),
    context.env.DB.prepare(`${NAVIGATION_TRAVERSAL_EVIDENCE_SELECT}
      WHERE t.version_id = ? AND t.project_id = ? AND t.organisation_id = ?
      ORDER BY t.id
    `).bind(version.id, project.id, auth.organisationId),
    context.env.DB.prepare(`
      SELECT revision.id, revision.plan_hash, revision.collision_asset_id,
        revision.collision_sha256, revision.navigation_receipt_version,
        revision.capture_agreement_json,
        collision.sha256 AS current_collision_sha256,
        collision.integrity_status AS collision_integrity_status,
        collision.deleted_at AS collision_deleted_at
      FROM floorplan_revisions revision
      LEFT JOIN assets collision ON collision.id = revision.collision_asset_id
      WHERE revision.version_id = ? AND revision.project_id = ?
        AND revision.organisation_id = ? AND revision.status = 'approved'
      ORDER BY revision.revision_number DESC, revision.created_at DESC LIMIT 1
    `).bind(version.id, project.id, auth.organisationId),
  ]);
  const asset = requiredBatchResult(results, 0).results[0] as Record<string, unknown> | undefined;
  if (!asset) return notFound(context, "Collision GLB asset not found");
  if (
    asset.version_id !== version.id ||
    asset.kind !== "collision" ||
    String(asset.format).toLowerCase() !== "glb"
  ) {
    return unprocessable(context, {
      collisionAssetId: ["Navigation requires a verified collision GLB from the selected version"],
    });
  }
  if (asset.integrity_status !== "verified" || typeof asset.sha256 !== "string") {
    return conflict(context, "Collision GLB has not passed immutable SHA-256 verification");
  }
  const profile = requiredBatchResult(results, 1).results[0] as Record<string, unknown> | undefined;
  if (!profile) return conflict(context, "Author the version navigation profile before building navigation");
  const worldUnit = parseWorldUnit(profile.world_unit);
  if (worldUnit === "scene_units" && !parsed.data.provisional) {
    return conflict(context, "Scene-unit navigation builds must be explicitly marked provisional");
  }
  const authoredDestinations = requiredBatchResult(results, 2).results
    .flatMap(navigationDestinationFromEntity);
  const routeStopRows = requiredBatchResult(results, 4).results;
  const traversalRows = requiredBatchResult(results, 5).results;
  const activeTraversalRows = traversalRows.filter(
    (row) => row && typeof row === "object" && Reflect.get(row, "status") === "active",
  );
  if (activeTraversalRows.length && worldUnit !== "metres") {
    return conflict(
      context,
      "Capture-registered traversals require a metric navigation profile; provisional scene-unit builds cannot include them",
    );
  }
  const routeDestinations = routeStopRows.flatMap((row) =>
    navigationDestinationFromRouteStop(row, Number(profile.eye_height))
  );
  const destinationMap = new Map(
    [...authoredDestinations, ...routeDestinations, ...parsed.data.destinations]
      .map((destination) => [destination.id, destination]),
  );
  const obstacleBoxes = requiredBatchResult(results, 3).results
    .flatMap(navigationObstacleBoxFromRow);
  const floorplanReceipt = floorplanNavigationReceipt(
    requiredBatchResult(results, 6).results[0],
  );
  if (isInvalidFloorplanNavigationReceipt(floorplanReceipt)) {
    return conflict(
      context,
      "The approved floor-plan collision receipt is missing or no longer matches its verified immutable asset.",
    );
  }
  if (
    floorplanReceipt?.schemaVersion === "reviewed-floorplan-navigation-receipt-v1" &&
    (
      floorplanReceipt.collisionAssetId !== asset.id ||
      floorplanReceipt.collisionSha256 !== String(asset.sha256).toLowerCase()
    )
  ) {
    return conflict(
      context,
      "Navigation must use the verified collision asset bound to the current approved floor-plan revision.",
    );
  }
  const authoringHash = await navigationAuthoringHash(
    profile,
    requiredBatchResult(results, 2).results,
    requiredBatchResult(results, 3).results,
    routeStopRows,
    traversalRows,
    floorplanReceipt,
  );
  const offMeshConnections = traversalRows.flatMap((row, index) =>
    navigationTraversalConnectionFromRow(row, Number(profile.agent_radius), index)
  );
  if (offMeshConnections.length !== activeTraversalRows.length) {
    return conflict(
      context,
      `Active authored traversal records are invalid: stored=${activeTraversalRows.length}, usable=${offMeshConnections.length}. Archive or correct the invalid records before building.`,
    );
  }
  const parameters = {
    provisional: parsed.data.provisional,
    bounds: parsed.data.bounds,
    spawn: parsed.data.spawn,
    destinations: [...destinationMap.values()],
    offMeshConnections,
    obstacleBoxes,
    build: parsed.data.build,
    source: {
      assetId: String(asset.id),
      sha256: String(asset.sha256),
      authoringHash,
      worldUnit,
    },
    agent: {
      radius: Number(profile.agent_radius),
      height: Number(profile.agent_height),
      eyeHeight: Number(profile.eye_height),
      maxClimb: Number(profile.max_step_metres),
      maxSlopeDegrees: Number(profile.max_slope_degrees),
      maxSpeed: Number(profile.max_speed),
      maxAcceleration: Number(profile.max_acceleration),
    },
  };
  const buildId = crypto.randomUUID();
  const jobId = crypto.randomUUID();
  await context.env.DB.batch([
    context.env.DB.prepare(`
      INSERT INTO processing_jobs (
        id, organisation_id, project_id, version_id, input_asset_id, job_type,
        processor_version, contract_version, idempotency_key, state, priority, max_attempts,
        progress_message
      ) VALUES (?, ?, ?, ?, ?, 'navigation.build-v1',
        'spatial-processor/0.11.0', 'spatial-processor/0.11.0', ?, 'QUEUED', 65, 3,
        'Waiting for an offline Recast navigation worker')
    `).bind(
      jobId,
      auth.organisationId,
      project.id,
      version.id,
      parsed.data.collisionAssetId,
      `navigation-build:${auth.organisationId}:${parsed.data.clientOperationId}`,
    ),
    context.env.DB.prepare(`
      INSERT INTO scene_navigation_builds (
        id, organisation_id, project_id, version_id, collision_asset_id,
        job_id, status, parameters_json, client_operation_id, request_hash,
        authoring_hash, created_by
      ) VALUES (?, ?, ?, ?, ?, ?, 'QUEUED', ?, ?, ?, ?, ?)
    `).bind(
      buildId,
      auth.organisationId,
      project.id,
      version.id,
      parsed.data.collisionAssetId,
      jobId,
      JSON.stringify(parameters),
      parsed.data.clientOperationId,
      requestHash,
      authoringHash,
      auth.userId,
    ),
  ]);
  await audit(context, auth, "spatial.navigation_build.create", "scene_navigation_build", buildId, {
    jobId,
    collisionAssetId: parsed.data.collisionAssetId,
    parameters,
  });
  dispatchProcessingJob(context, jobId);
  return context.json({
    build: { id: buildId, status: "QUEUED", jobId, parameters },
  }, 202);
});

app.post("/api/projects/:projectId/spatial/navigation-builds/:buildId/review", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = navigationBuildReviewSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const reviewable = await context.env.DB.prepare(`
    SELECT id, version_id, status, artifact_json, parameters_json, authoring_hash
    FROM scene_navigation_builds
    WHERE id = ? AND project_id = ? AND organisation_id = ?
  `).bind(
    context.req.param("buildId"),
    context.req.param("projectId"),
    auth.organisationId,
  ).first<{
    id: string;
    version_id: string;
    status: string;
    artifact_json: string | null;
    parameters_json: string;
    authoring_hash: string;
  }>();
  if (!reviewable || reviewable.status !== "READY_FOR_REVIEW" || !reviewable.artifact_json) {
    return conflict(context, "Only a completed navigation build can be reviewed");
  }
  let manualApprovalCoverage: FinalAgreementCoverage[] = [];
  let manualApprovalRevisionId: string | null = null;
  if (parsed.data.decision === "approve") {
    const parameters = parseStoredObject(reviewable.parameters_json);
    const automaticLayout = parameters && typeof parameters === "object"
      ? Reflect.get(parameters, "automaticLayout")
      : null;
    if (automaticLayout && typeof automaticLayout === "object") {
      const extractionId = Reflect.get(automaticLayout, "floorplanExtractionId");
      const revisionId = Reflect.get(automaticLayout, "floorplanRevisionId");
      if (typeof extractionId === "string" && typeof revisionId !== "string") {
        return conflict(
          context,
          "This navigation build is a proposal preview. Approve the corrected floor plan to create an approvable build.",
        );
      }
    }
    let currentState: Awaited<ReturnType<typeof currentNavigationAuthoringState>>;
    try {
      currentState = await currentNavigationAuthoringState(
        context.env.DB,
        auth.organisationId,
        context.req.param("projectId"),
        reviewable.version_id,
      );
    } catch (error) {
      return conflict(
        context,
        `Current navigation authoring is invalid: ${error instanceof Error ? error.message : String(error)}`,
      );
    }
    if (currentState.authoringHash !== reviewable.authoring_hash) {
      return conflict(
        context,
        `Navigation authoring changed after this build: expected_authoring_hash=${reviewable.authoring_hash}, asked_authoring_hash=${currentState.authoringHash}. Rebuild navigation before approval.`,
      );
    }
    if (automaticLayout && typeof automaticLayout === "object") {
      const revisionId = Reflect.get(automaticLayout, "floorplanRevisionId");
      const planHash = Reflect.get(automaticLayout, "planHash");
      if (typeof revisionId === "string") {
        const revision = await context.env.DB.prepare(`
          SELECT status, plan_hash FROM floorplan_revisions
          WHERE id = ? AND project_id = ? AND organisation_id = ?
        `).bind(
          revisionId,
          context.req.param("projectId"),
          auth.organisationId,
        ).first<{ status: string; plan_hash: string }>();
        if (!revision || revision.status !== "approved" || revision.plan_hash !== planHash) {
          return conflict(
            context,
            "Navigation evidence is not bound to the current approved floor-plan revision.",
          );
        }
      }
    }
    const artifact = navigationArtifactSchema.safeParse(
      parseStoredObject(reviewable.artifact_json),
    );
    if (
      !artifact.success ||
      !navigationArtifactMatchesFrozenConnections(artifact.data, parameters)
    ) {
      return conflict(
        context,
        "Navigation artifact traversal payload does not match the Worker-frozen build parameters.",
      );
    }
    // Manual approval clears the exact final capture-agreement gate that
    // automatic acceptance enforces — an operator's Approve button is not a
    // bypass. A crossing the capture only revealed on the final corrected
    // barriers has no proposal classification to inherit, so the operator
    // resolves it per finding in this very request; each supplied resolution
    // must also qualify against a real final crossing, so the receipt can
    // never claim more review than happened.
    const manualResolutions = parsed.data.finalCaptureAgreementResolutions ?? [];
    const captureExpected = Boolean(
      automaticLayout && typeof automaticLayout === "object" &&
        Reflect.get(automaticLayout, "capture") &&
        typeof Reflect.get(automaticLayout, "capture") === "object",
    );
    if (!captureExpected && manualResolutions.length) {
      return unprocessable(context, {
        finalCaptureAgreementResolutions: [
          "This build pins no capture, so there are no final crossings to resolve",
        ],
      });
    }
    if (captureExpected) {
      const revisionId = automaticLayout && typeof automaticLayout === "object"
        ? Reflect.get(automaticLayout, "floorplanRevisionId")
        : null;
      const agreementRevision = typeof revisionId === "string"
        ? await context.env.DB.prepare(`
          SELECT capture_agreement_json FROM floorplan_revisions
          WHERE id = ? AND project_id = ? AND organisation_id = ?
        `).bind(
          revisionId,
          context.req.param("projectId"),
          auth.organisationId,
        ).first<{ capture_agreement_json: string | null }>()
        : null;
      const resolutionIssues = invalidFinalAgreementResolutionIssues(
        artifact.data.finalCaptureAgreement,
        manualResolutions,
      );
      if (resolutionIssues.length) {
        return unprocessable(context, {
          finalCaptureAgreementResolutions: resolutionIssues,
        });
      }
      const reconciliation = finalCaptureAgreementReconciliation({
        captureExpected,
        finalAgreement: artifact.data.finalCaptureAgreement,
        captureAgreementJson: agreementRevision?.capture_agreement_json ?? null,
        manualResolutions,
      });
      if (reconciliation.blockReason) {
        return unprocessable(context, {
          finalCaptureAgreementResolutions: [
            reconciliation.blockReason.replace(
              /^Automatic acceptance blocked/,
              "Approval blocked",
            ),
          ],
        });
      }
      manualApprovalCoverage = reconciliation.coverage;
      manualApprovalRevisionId = typeof revisionId === "string" ? revisionId : null;
    }
  }
  const status = parsed.data.decision === "approve" ? "APPROVED" : "REJECTED";
  const manualAgreementJson = parsed.data.decision === "approve"
    ? await buildFinalCaptureApprovalReceipt({
      artifactJson: reviewable.artifact_json,
      coverage: manualApprovalCoverage,
      sourceRevisionId: manualApprovalRevisionId,
      reviewedBy: auth.userId,
    })
    : null;
  const build = await context.env.DB.prepare(`
    UPDATE scene_navigation_builds
    SET status = ?, reviewed_by = ?, review_note = ?, reviewed_at = datetime('now'),
      final_capture_agreement_json = ?, updated_at = datetime('now')
    WHERE id = ? AND project_id = ? AND organisation_id = ?
      AND status = 'READY_FOR_REVIEW' AND artifact_json IS NOT NULL
    RETURNING id, status, reviewed_at
  `).bind(
    status,
    auth.userId,
    parsed.data.note,
    manualAgreementJson,
    context.req.param("buildId"),
    context.req.param("projectId"),
    auth.organisationId,
  ).first<{ id: string; status: string; reviewed_at: string }>();
  if (!build) return conflict(context, "Only a completed navigation build can be reviewed");
  await audit(context, auth, "spatial.navigation_build.review", "scene_navigation_build", build.id, parsed.data);
  const republishIntent = status === "APPROVED"
    ? await completeReleaseRepublishIntent(context.env, build.id, context.get("requestId"))
    : await failReleaseRepublishIntent(
      context.env.DB,
      build.id,
      "Automatic republish stopped because the rebuilt walking map was rejected",
    );
  return context.json({ build, republishIntent });
});

app.post("/api/projects/:projectId/spatial/navigation-builds/:buildId/walk-tests", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = navigationWalkTestSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const projectId = context.req.param("projectId");
  const buildId = context.req.param("buildId");
  const requestHash = await sha256Hex(JSON.stringify(parsed.data));
  const prior = await context.env.DB.prepare(`
    SELECT id, navigation_build_id, request_hash, completed_at
    FROM scene_navigation_walk_tests
    WHERE organisation_id = ? AND client_operation_id = ?
  `).bind(auth.organisationId, parsed.data.clientOperationId).first<{
    id: string;
    navigation_build_id: string;
    request_hash: string;
    completed_at: string;
  }>();
  if (prior) {
    if (prior.navigation_build_id !== buildId || prior.request_hash !== requestHash) {
      return conflict(context, "Operation ID was already used for a different walk-test receipt");
    }
    return context.json({ walkTest: prior, idempotent: true });
  }
  const build = await context.env.DB.prepare(`
    SELECT id, version_id, status, artifact_json
    FROM scene_navigation_builds
    WHERE id = ? AND project_id = ? AND organisation_id = ?
  `).bind(buildId, projectId, auth.organisationId).first<{
    id: string;
    version_id: string;
    status: string;
    artifact_json: string | null;
  }>();
  if (!build) return notFound(context, "Navigation build not found");
  if (
    build.status !== "APPROVED" || !build.artifact_json ||
    build.version_id !== parsed.data.versionId
  ) {
    return conflict(
      context,
      "Walk-test completion requires the approved walking map for this exact immutable scene version",
    );
  }
  const walkTestId = crypto.randomUUID();
  await context.env.DB.prepare(`
    INSERT INTO scene_navigation_walk_tests (
      id, organisation_id, project_id, version_id, navigation_build_id,
      client_operation_id, request_hash, start_pose_json, end_pose_json,
      runtime_evidence_json, completed_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).bind(
    walkTestId,
    auth.organisationId,
    projectId,
    build.version_id,
    build.id,
    parsed.data.clientOperationId,
    requestHash,
    JSON.stringify(parsed.data.startPose),
    JSON.stringify(parsed.data.endPose),
    JSON.stringify(parsed.data.runtimeEvidence),
    auth.userId,
  ).run();
  await audit(context, auth, "spatial.navigation_walk_test.complete", "scene_navigation_walk_test", walkTestId, {
    navigationBuildId: build.id,
    versionId: build.version_id,
    runtimeEvidence: parsed.data.runtimeEvidence,
  });
  const republishIntent = await completeReleaseRepublishIntent(
    context.env,
    build.id,
    context.get("requestId"),
  );
  return context.json({
    walkTest: {
      id: walkTestId,
      navigation_build_id: build.id,
      completed_at: new Date().toISOString(),
    },
    republishIntent,
  }, 201);
});

app.post("/api/projects/:projectId/spatial/routes", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = sceneRouteSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(context.env.DB, auth.organisationId, context.req.param("projectId"));
  if (!project) return notFound(context, "Project not found");
  const entities = await context.env.DB.prepare(`
    SELECT id FROM scene_entities WHERE project_id = ? AND version_id = ?
      AND id IN (${parsed.data.stops.map(() => "?").join(",")}) AND status = 'active'
  `).bind(project.id, parsed.data.versionId, ...parsed.data.stops.map((stop) => stop.entityId)).all();
  if (entities.results.length !== new Set(parsed.data.stops.map((stop) => stop.entityId)).size) {
    return validationError(context, { stops: ["Every route stop must reference an active entity in this version"] });
  }
  const routeId = crypto.randomUUID();
  const statements = [
    context.env.DB.prepare(`
      INSERT INTO scene_routes
        (id, organisation_id, project_id, version_id, label, description,
          accessibility, estimated_seconds, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(
      routeId, auth.organisationId, project.id, parsed.data.versionId,
      parsed.data.label, parsed.data.description ?? null, parsed.data.accessibility,
      parsed.data.estimatedSeconds ?? null, auth.userId,
    ),
    ...parsed.data.stops.map((stop, index) => context.env.DB.prepare(`
      INSERT INTO scene_route_stops
        (route_id, entity_id, sequence_number, camera_pose_json, narration)
      VALUES (?, ?, ?, ?, ?)
    `).bind(routeId, stop.entityId, index, stop.cameraPose ? JSON.stringify(stop.cameraPose) : null, stop.narration ?? null)),
  ];
  await context.env.DB.batch(statements);
  await audit(context, auth, "spatial.route.create", "scene_route", routeId, { versionId: parsed.data.versionId });
  return context.json({ route: { id: routeId, ...parsed.data } }, 201);
});

app.post("/api/projects/:projectId/privacy-scans", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const parsed = privacyScanSchema.safeParse(await readJson(context));
  if (!parsed.success) return validationError(context, parsed.error.flatten());
  const project = await scopedProject(context.env.DB, auth.organisationId, context.req.param("projectId"));
  if (!project) return notFound(context, "Project not found");
  const version = await context.env.DB.prepare(
    "SELECT id FROM scene_versions WHERE id = ? AND project_id = ?",
  ).bind(parsed.data.versionId, project.id).first<{ id: string }>();
  if (!version) return notFound(context, "Scene version not found");

  const requestHash = await sha256Hex(JSON.stringify({
    versionId: parsed.data.versionId,
    assetIds: parsed.data.assetIds,
    detector: privacyDetectorVersion,
    targets: privacyTargets.map(({ target }) => target),
  }));
  const existing = await context.env.DB.prepare(`
    SELECT * FROM privacy_scans
    WHERE organisation_id = ? AND client_operation_id = ?
  `).bind(auth.organisationId, parsed.data.clientOperationId).first<PrivacyScanRow>();
  if (existing) {
    if (existing.request_hash !== requestHash || existing.project_id !== project.id) {
      return conflict(context, "Operation ID was already used for a different privacy scan");
    }
    return context.json({ scan: privacyScanApi(existing), idempotent: true }, 202);
  }

  const placeholders = parsed.data.assetIds.map(() => "?").join(",");
  const assets = await context.env.DB.prepare(`
    SELECT * FROM assets
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
      AND id IN (${placeholders}) AND kind = 'poster'
      AND integrity_status = 'verified' AND deleted_at IS NULL
  `).bind(
    auth.organisationId,
    project.id,
    version.id,
    ...parsed.data.assetIds,
  ).all<AssetRow>();
  if (assets.results.length !== parsed.data.assetIds.length) {
    return validationError(context, {
      assetIds: ["Every privacy input must be a verified poster image in this scene version"],
    });
  }
  for (const asset of assets.results) {
    if (!asset.mime_type.startsWith("image/")) {
      return validationError(context, { assetIds: [`${asset.file_name} is not an image`] });
    }
    if (asset.size_bytes > maximumPrivacyImageBytes) {
      return validationError(context, {
        assetIds: [`${asset.file_name} exceeds the 10 MiB privacy-input limit`],
      });
    }
    if (!(await context.env.SPATIAL_ASSETS.head(asset.object_key))) {
      return validationError(context, { assetIds: [`${asset.file_name} is missing from private storage`] });
    }
  }

  const scanId = crypto.randomUUID();
  const targetsJson = JSON.stringify(privacyTargets);
  await context.env.DB.batch([
    context.env.DB.prepare(`
      INSERT INTO privacy_scans
        (id, organisation_id, project_id, version_id, client_operation_id,
          request_hash, detector, detector_version, targets_json, status,
          input_count, created_by)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'QUEUED', ?, ?)
    `).bind(
      scanId,
      auth.organisationId,
      project.id,
      version.id,
      parsed.data.clientOperationId,
      requestHash,
      privacyDetector,
      privacyDetectorVersion,
      targetsJson,
      assets.results.length,
      auth.userId,
    ),
    ...assets.results.map((asset) => context.env.DB.prepare(`
      INSERT INTO privacy_scan_inputs
        (scan_id, asset_id, asset_sha256, mime_type, size_bytes)
      VALUES (?, ?, ?, ?, ?)
    `).bind(scanId, asset.id, asset.sha256, asset.mime_type, asset.size_bytes)),
  ]);
  try {
    await context.env.PRIVACY_SCAN_QUEUE.send({ scanId } satisfies PrivacyScanQueueMessage, {
      contentType: "json",
    });
  } catch (error) {
    await markPrivacyScanEnqueueFailure(context.env.DB, scanId, error);
    return context.json({
      error: "Privacy scan could not be queued",
      scan: { id: scanId, status: "FAILED" },
      retryable: true,
      requestId: context.get("requestId"),
    }, 503);
  }
  await audit(context, auth, "privacy.scan.queue", "privacy_scan", scanId, {
    versionId: version.id,
    assetIds: parsed.data.assetIds,
    detector: privacyDetectorVersion,
  });
  const scan = await context.env.DB.prepare(
    "SELECT * FROM privacy_scans WHERE id = ?",
  ).bind(scanId).first<PrivacyScanRow>();
  return context.json({ scan: privacyScanApi(scan!) }, 202);
});

app.post("/api/projects/:projectId/privacy-scans/:scanId/retry", async (context) => {
  const auth = await requireOperator(context);
  if (auth instanceof Response) return auth;
  if (!(await isSameOrigin(context))) return forbidden(context, "Cross-origin request rejected");
  const scan = await context.env.DB.prepare(`
    SELECT * FROM privacy_scans
    WHERE id = ? AND project_id = ? AND organisation_id = ?
  `).bind(
    context.req.param("scanId"),
    context.req.param("projectId"),
    auth.organisationId,
  ).first<PrivacyScanRow>();
  if (!scan) return notFound(context, "Privacy scan not found");
  if (scan.status === "COMPLETED") return conflict(context, "Completed privacy scans cannot be retried");
  if (scan.status === "RUNNING") return conflict(context, "Privacy scan is already running");
  await context.env.DB.prepare(`
    UPDATE privacy_scans
    SET status = 'QUEUED', error_json = NULL, completed_at = NULL,
      updated_at = datetime('now')
    WHERE id = ?
  `).bind(scan.id).run();
  try {
    await context.env.PRIVACY_SCAN_QUEUE.send({ scanId: scan.id } satisfies PrivacyScanQueueMessage, {
      contentType: "json",
    });
  } catch (error) {
    await markPrivacyScanEnqueueFailure(context.env.DB, scan.id, error);
    return context.json({
      error: "Privacy scan could not be queued",
      scan: { id: scan.id, status: "FAILED" },
      retryable: true,
      requestId: context.get("requestId"),
    }, 503);
  }
  await audit(context, auth, "privacy.scan.retry", "privacy_scan", scan.id);
  const queued = await context.env.DB.prepare(
    "SELECT * FROM privacy_scans WHERE id = ?",
  ).bind(scan.id).first<PrivacyScanRow>();
  return context.json({ scan: privacyScanApi(queued!) }, 202);
});

