type TeamMemberRecord = {
  userId: string;
  email: string;
  displayName: string;
  role: "platform_admin" | "production_operator";
  joinedAt: string;
  updatedAt: string | null;
  revokedAt: string | null;
  status: "active" | "invited";
};

async function activeTeamMember(
  database: D1Database,
  organisationId: string,
  userId: string,
): Promise<TeamMemberRecord | null> {
  return database.prepare(`
    SELECT u.id AS userId, u.email, u.display_name AS displayName, m.role, m.status,
      m.created_at AS joinedAt, m.updated_at AS updatedAt, m.revoked_at AS revokedAt
    FROM memberships m JOIN users u ON u.id = m.user_id
    WHERE m.organisation_id = ? AND m.user_id = ? AND m.revoked_at IS NULL
      AND m.status IN ('active', 'invited')
      AND m.role IN ('platform_admin', 'production_operator')
  `).bind(organisationId, userId).first<TeamMemberRecord>();
}

async function isLastAdministrator(
  database: D1Database,
  organisationId: string,
  userId: string,
): Promise<boolean> {
  const result = await database.prepare(`
    SELECT COUNT(*) AS count FROM memberships
    WHERE organisation_id = ? AND role = 'platform_admin'
      AND revoked_at IS NULL AND status = 'active' AND user_id != ?
  `).bind(organisationId, userId).first<{ count: number }>();
  return (result?.count ?? 0) === 0;
}

// `isLastAdministrator` above is only a fast pre-check: two administrators
// demoting each other concurrently would both read a surviving peer and both
// commit. Every statement that removes or demotes an active platform
// administrator carries this guard so the mutation itself is conditional on a
// surviving peer. The predicate only inspects OTHER members, so it stays stable
// across the statements of one batch. Bind [guardActive ? 1 : 0,
// organisationId, targetUserId].
const administratorSurvivorGuard = `(? = 0 OR EXISTS (
  SELECT 1 FROM memberships other
  WHERE other.organisation_id = ? AND other.role = 'platform_admin'
    AND other.status = 'active' AND other.revoked_at IS NULL
    AND other.user_id != ?
))`;

async function deliverTeamInvitation(
  env: Env,
  organisationId: string,
  invitationId: string,
  email: string,
  role: "platform_admin" | "production_operator",
  expiresAt: string,
): Promise<{ status: "sent" | "failed"; error: string | null }> {
  let status: "sent" | "failed" = "sent";
  let deliveryError: string | null = null;
  try {
    await sendTeamInvitationEmail(env, email, role, expiresAt);
  } catch (error) {
    status = "failed";
    deliveryError = errorMessage(error).slice(0, 500);
  }
  await env.DB.batch([
    env.DB.prepare(`
      UPDATE organisation_invitations
      SET last_sent_at = datetime('now'), send_count = send_count + 1
      WHERE id = ? AND organisation_id = ?
    `).bind(invitationId, organisationId),
    env.DB.prepare(`
      INSERT INTO notification_deliveries
        (id, organisation_id, channel, template, recipient, status,
          error_message, sent_at)
      VALUES (?, ?, 'email', 'team_invitation', ?, ?, ?, ?)
    `).bind(
      crypto.randomUUID(),
      organisationId,
      email,
      status,
      deliveryError,
      status === "sent" ? new Date().toISOString() : null,
    ),
  ]);
  return { status, error: deliveryError };
}

async function acceptPendingOrganisationInvitation(
  database: D1Database,
  email: string,
): Promise<AuthContext | null> {
  const now = new Date().toISOString();
  await database.prepare(`
    UPDATE organisation_invitations SET status = 'expired'
    WHERE lower(email) = lower(?) AND status = 'pending' AND expires_at <= ?
  `).bind(email, now).run();
  const invitation = await database.prepare(`
    SELECT oi.id, oi.organisation_id AS organisationId, u.id AS userId,
      u.email, u.display_name AS displayName, m.role
    FROM organisation_invitations oi
    JOIN users u ON lower(u.email) = lower(oi.email)
    JOIN memberships m ON m.organisation_id = oi.organisation_id AND m.user_id = u.id
    WHERE lower(oi.email) = lower(?) AND oi.status = 'pending'
      AND oi.expires_at > ? AND m.status = 'invited' AND m.revoked_at IS NULL
    ORDER BY oi.invited_at DESC LIMIT 1
  `).bind(email, now).first<AuthContext & { id: string }>();
  if (!invitation) return null;
  await database.batch([
    database.prepare(`
      UPDATE memberships
      SET status = 'active', updated_at = datetime('now'), revoked_at = NULL
      WHERE organisation_id = ? AND user_id = ? AND status = 'invited'
    `).bind(invitation.organisationId, invitation.userId),
    database.prepare(`
      UPDATE organisation_invitations
      SET status = 'accepted', accepted_by = ?, accepted_at = datetime('now')
      WHERE id = ? AND status = 'pending' AND expires_at > ?
    `).bind(invitation.userId, invitation.id, now),
  ]);
  return {
    userId: invitation.userId,
    organisationId: invitation.organisationId,
    email: invitation.email,
    displayName: invitation.displayName,
    role: invitation.role,
  };
}

async function acceptPendingOrganisationInvitationForOrganisation(
  database: D1Database,
  organisationId: string,
  email: string,
): Promise<void> {
  const now = new Date().toISOString();
  await database.prepare(`
    UPDATE organisation_invitations SET status = 'expired'
    WHERE organisation_id = ? AND lower(email) = lower(?)
      AND status = 'pending' AND expires_at <= ?
  `).bind(organisationId, email, now).run();
  const invitation = await database.prepare(`
    SELECT oi.id, u.id AS userId
    FROM organisation_invitations oi
    JOIN users u ON lower(u.email) = lower(oi.email)
    JOIN memberships m
      ON m.organisation_id = oi.organisation_id
      AND m.user_id = u.id
    WHERE oi.organisation_id = ? AND lower(oi.email) = lower(?)
      AND oi.status = 'pending' AND oi.expires_at > ?
      AND m.status = 'invited' AND m.revoked_at IS NULL
    ORDER BY oi.invited_at DESC LIMIT 1
  `).bind(organisationId, email, now).first<{
    id: string;
    userId: string;
  }>();
  if (!invitation) return;
  await database.batch([
    database.prepare(`
      UPDATE memberships
      SET status = 'active', updated_at = datetime('now'), revoked_at = NULL
      WHERE organisation_id = ? AND user_id = ? AND status = 'invited'
    `).bind(organisationId, invitation.userId),
    database.prepare(`
      UPDATE organisation_invitations
      SET status = 'accepted', accepted_by = ?, accepted_at = datetime('now')
      WHERE id = ? AND status = 'pending' AND expires_at > ?
    `).bind(invitation.userId, invitation.id, now),
  ]);
}

// One sign-in can only ever onboard a bounded number of invitations, so a
// mis-seeded invitation set cannot spin this loop forever.
const maximumAutomaticInvitationAcceptances = 20;

async function hasActiveOrganisationMembership(
  database: D1Database,
  email: string,
): Promise<boolean> {
  const membership = await database.prepare(`
    SELECT 1 AS present FROM memberships m
    JOIN users u ON u.id = m.user_id
    WHERE lower(u.email) = lower(?) AND m.status = 'active' AND m.revoked_at IS NULL
    LIMIT 1
  `).bind(email).first<{ present: number }>();
  return Boolean(membership);
}

async function acceptPendingOrganisationInvitations(
  database: D1Database,
  email: string,
): Promise<void> {
  // Silent acceptance is only defensible as first-time onboarding. Once an
  // account holds an active membership anywhere, any platform administrator
  // could otherwise pre-create an invited membership for an arbitrary email and
  // capture that account's default workspace on its next sign-in, so those
  // invitations stay pending until the invitee accepts or declines explicitly.
  if (await hasActiveOrganisationMembership(database, email)) return;
  for (let accepted = 0; accepted < maximumAutomaticInvitationAcceptances; accepted += 1) {
    if (!(await acceptPendingOrganisationInvitation(database, email))) return;
  }
}

async function pendingOrganisationInvitations(
  database: D1Database,
  email: string,
): Promise<PendingOrganisationInvitation[]> {
  const invitations = await database.prepare(`
    SELECT oi.id, oi.organisation_id AS organisationId, o.name AS organisationName,
      oi.role, oi.invited_at AS invitedAt, oi.expires_at AS expiresAt
    FROM organisation_invitations oi
    JOIN organisations o ON o.id = oi.organisation_id
    JOIN users u ON lower(u.email) = lower(oi.email)
    JOIN memberships m ON m.organisation_id = oi.organisation_id AND m.user_id = u.id
    WHERE lower(oi.email) = lower(?) AND oi.status = 'pending' AND oi.expires_at > ?
      AND m.status = 'invited' AND m.revoked_at IS NULL
    ORDER BY oi.invited_at DESC
    LIMIT 50
  `).bind(email, new Date().toISOString()).all<PendingOrganisationInvitation>();
  return invitations.results;
}

async function acceptPendingProjectInvitations(database: D1Database, auth: AuthContext): Promise<void> {
  const now = new Date().toISOString();
  await database.batch([
    database.prepare(`
      UPDATE project_invitations SET status = 'expired'
      WHERE organisation_id = ? AND lower(email) = lower(?)
        AND status = 'pending' AND expires_at <= ?
    `).bind(auth.organisationId, auth.email, now),
    database.prepare(`
      INSERT INTO project_access
        (organisation_id, project_id, user_id, role, invited_by, granted_at, revoked_at)
      SELECT organisation_id, project_id, ?, role, invited_by, datetime('now'), NULL
      FROM project_invitations
      WHERE organisation_id = ? AND lower(email) = lower(?)
        AND status = 'pending' AND expires_at > ?
      ON CONFLICT(project_id, user_id) DO UPDATE SET
        role = excluded.role,
        invited_by = excluded.invited_by,
        granted_at = excluded.granted_at,
        revoked_at = NULL
    `).bind(auth.userId, auth.organisationId, auth.email, now),
    database.prepare(`
      UPDATE project_invitations
      SET status = 'accepted', accepted_by = ?, accepted_at = datetime('now')
      WHERE organisation_id = ? AND lower(email) = lower(?)
        AND status = 'pending' AND expires_at > ?
    `).bind(auth.userId, auth.organisationId, auth.email, now),
  ]);
}

