async function portfolioPreview(
  database: D1Database,
  organisationId: string,
  manifest: PortfolioManifest,
): Promise<Record<string, unknown>> {
  const fieldPlan = await portfolioManifestFieldPlan(database, organisationId, manifest);
  const existing = await database.prepare(`
    SELECT lower(name) AS normalized_name
    FROM projects WHERE organisation_id = ?
  `).bind(organisationId).all<{ normalized_name: string }>();
  const existingNames = new Set(existing.results.map((project) => project.normalized_name));
  const customerNames = new Set(
    manifest.projects
      .map((project) => project.customerName?.trim().toLowerCase())
      .filter((name): name is string => Boolean(name)),
  );
  const duplicateWorkspaceNames = manifest.projects
    .filter((project) => existingNames.has(project.name.trim().toLowerCase()))
    .map((project) => project.name);
  const duplicateManifestNames = manifest.projects
    .map((project) => project.name.trim().toLowerCase())
    .filter((name, index, names) => names.indexOf(name) !== index);
  const warnings: string[] = [];
  if (duplicateWorkspaceNames.length) {
    warnings.push(
      `${duplicateWorkspaceNames.length} imported project name${duplicateWorkspaceNames.length === 1 ? "" : "s"} already exist; new DRAFT records will still receive unique IDs and slugs.`,
    );
  }
  if (duplicateManifestNames.length) {
    warnings.push(
      `${new Set(duplicateManifestNames).size} project name${new Set(duplicateManifestNames).size === 1 ? "" : "s"} appear more than once in the import file.`,
    );
  }
  if (fieldPlan.fieldsToCreate.length) {
    warnings.push(
      `${fieldPlan.fieldsToCreate.length} project field definition${
        fieldPlan.fieldsToCreate.length === 1 ? "" : "s"
      } will be created in this workspace.`,
    );
  }
  for (const conflict of fieldPlan.conflicts) {
    warnings.push(
      `${conflict.label} (${conflict.key}) is ${conflict.sourceType} in the file but ${conflict.targetType} in this workspace.`,
    );
  }
  warnings.push(...fieldPlan.valueErrors);
  return {
    valid: fieldPlan.conflicts.length === 0 && fieldPlan.valueErrors.length === 0,
    format: manifest.format,
    schemaVersion: manifest.schemaVersion,
    summary: {
      projects: manifest.projects.length,
      customers: customerNames.size,
      existingNameMatches: duplicateWorkspaceNames.length,
      customFields: manifest.fieldDefinitions.length,
      fieldsToCreate: fieldPlan.fieldsToCreate.length,
    },
    warnings,
    conflicts: fieldPlan.conflicts,
    fieldsToCreate: fieldPlan.fieldsToCreate,
    projects: manifest.projects.map((project) => ({
      sourceId: project.sourceId ?? null,
      name: project.name,
      customerName: project.customerName ?? null,
      captureAdapter: project.captureAdapter,
      deliveryTemplate: project.deliveryTemplate,
      targetStatus: "DRAFT",
      nameAlreadyExists: existingNames.has(project.name.trim().toLowerCase()),
    })),
  };
}

async function portfolioManifestFieldPlan(
  database: D1Database,
  organisationId: string,
  manifest: PortfolioManifest,
): Promise<{
  fieldsToCreate: PortfolioManifest["fieldDefinitions"];
  conflicts: Array<{
    key: string;
    label: string;
    sourceType: ProjectCustomFieldType;
    targetType: ProjectCustomFieldType;
  }>;
  valueErrors: string[];
}> {
  const targetFields = await projectCustomFieldDefinitions(database, organisationId, false);
  const targetByKey = new Map(targetFields.map((field) => [field.key, field]));
  const fieldsToCreate = manifest.fieldDefinitions.filter((field) => !targetByKey.has(field.key));
  const conflicts = manifest.fieldDefinitions.flatMap((field) => {
    const target = targetByKey.get(field.key);
    if (!target || target.field_type === field.type) return [];
    return [{
      key: field.key,
      label: field.label,
      sourceType: field.type,
      targetType: target.field_type,
    }];
  });
  const definitions = new Map(manifest.fieldDefinitions.map((field) => [field.key, field]));
  const valueErrors: string[] = [];
  for (const project of manifest.projects) {
    for (const definition of manifest.fieldDefinitions) {
      const value = project.customFields[definition.key];
      if (definition.required && (value === undefined || value === null)) {
        valueErrors.push(`${project.name}: ${definition.label} is required.`);
      }
    }
    for (const [key, value] of Object.entries(project.customFields)) {
      if (value === null) continue;
      const definition = definitions.get(key);
      if (!definition) continue;
      const row: ProjectCustomFieldDefinitionRow = {
        id: "",
        organisation_id: organisationId,
        key: definition.key,
        label: definition.label,
        description: definition.description ?? null,
        field_type: definition.type,
        required: definition.required ? 1 : 0,
        options_json: JSON.stringify(definition.options),
        active: 1,
        sort_order: definition.sortOrder,
        client_operation_id: null,
        request_hash: null,
        created_at: "",
        updated_at: "",
      };
      const error = validateProjectCustomFieldValue(row, value);
      if (error) valueErrors.push(`${project.name}: ${error}.`);
    }
  }
  return {
    fieldsToCreate,
    conflicts,
    valueErrors: [...new Set(valueErrors)].slice(0, 100),
  };
}

function applySecurityHeaders(context: Context<AppEnvironment>): void {
  context.header("X-Content-Type-Options", "nosniff");
  context.header("Referrer-Policy", "strict-origin-when-cross-origin");
  context.header("Permissions-Policy", "camera=(), microphone=(), geolocation=(), payment=()");
  context.header("X-Frame-Options", "SAMEORIGIN");
  context.header("Cross-Origin-Opener-Policy", "same-origin");
  context.header("Cross-Origin-Resource-Policy", "same-origin");
  context.header(
    "Content-Security-Policy",
    "default-src 'self'; script-src 'self' 'wasm-unsafe-eval' https://static.cloudflareinsights.com https://challenges.cloudflare.com; style-src 'self' 'unsafe-inline'; img-src 'self' blob: data:; connect-src 'self' data: https://cloudflareinsights.com; worker-src 'self' blob:; frame-src 'self' https://challenges.cloudflare.com; font-src 'self' data:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self'",
  );
  if (context.env.APP_ENV === "production") context.header("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
}

async function isSameOrigin(context: Context<AppEnvironment>): Promise<boolean> {
  const origin = context.req.header("Origin");
  if (!origin) {
    const fetchSite = context.req.header("Sec-Fetch-Site");
    return !fetchSite || fetchSite === "same-origin" || fetchSite === "none";
  }
  try {
    if (origin === new URL(context.env.APP_ORIGIN).origin) return true;
  } catch {
    // Invalid configuration is handled by the normal application boundary.
  }
  const requestUrl = new URL(context.req.url);
  if (origin !== requestUrl.origin) return false;
  if (isPlatformHostname(context.env, requestUrl.hostname)) return false;
  const domain = await customDomainForHost(context.env.DB, requestUrl.hostname);
  return Boolean(domain && customDomainReady(domain));
}

function fileNameMatchesFormat(fileName: string, format: string): boolean {
  const lower = fileName.toLowerCase();
  return lower.endsWith(`.${format}`);
}

function legacyCaptureAdapter(adapter: CaptureAdapterId): Exclude<CaptureAdapterId, "drone-imagery"> {
  return adapter === "drone-imagery" ? "open-import" : adapter;
}

class RequestBodyError extends Error {
  readonly kind: "invalid_json" | "too_large";

  constructor(kind: "invalid_json" | "too_large", message: string) {
    super(message);
    this.name = "RequestBodyError";
    this.kind = kind;
  }
}

async function readJson(
  context: Context<AppEnvironment>,
  options?: { maxBytes?: number },
): Promise<unknown> {
  const maxBytes = options?.maxBytes ?? 1024 * 1024;
  const limitLabel = `JSON request body exceeds ${Math.floor(maxBytes / (1024 * 1024))} MiB`;
  const contentLength = Number(context.req.header("Content-Length") ?? "0");
  if (Number.isFinite(contentLength) && contentLength > maxBytes) {
    throw new RequestBodyError("too_large", limitLabel);
  }
  const body = await context.req.text();
  if (new TextEncoder().encode(body).byteLength > maxBytes) {
    throw new RequestBodyError("too_large", limitLabel);
  }
  try {
    return JSON.parse(body) as unknown;
  } catch {
    throw new RequestBodyError("invalid_json", "Request body is not valid JSON");
  }
}

// A release that never carried an operator-chosen splat budget publishes an
// explicit null so the viewer runs its device-aware and delivery-policy path
// instead of silently inheriting one fixed budget on every device.
function releaseSplatBudgetMillions(viewerConfig: unknown): number | null {
  if (!viewerConfig || typeof viewerConfig !== "object") return null;
  const budget = Reflect.get(viewerConfig, "splatBudgetMillions");
  return typeof budget === "number" && Number.isFinite(budget) ? budget : null;
}

function parseStoredObject(value: string): unknown {
  try {
    return JSON.parse(value) as unknown;
  } catch {
    return {};
  }
}

export function navigationArtifactMatchesFrozenConnections(
  artifact: unknown,
  parameters: unknown,
): boolean {
  const parsedArtifact = navigationArtifactSchema.safeParse(artifact);
  const candidateConnections = parameters && typeof parameters === "object"
    ? Reflect.get(parameters, "offMeshConnections")
    : undefined;
  const parsedConnections = authoredTraversalConnectionsSchema.safeParse(candidateConnections);
  if (!parsedArtifact.success || !parsedConnections.success) return false;
  if (parsedConnections.data.some((connection) =>
    !isSceneRegisteredTraversalEvidenceReceipt(connection.evidenceReceipt)
  )) return false;
  // V8 remains readable for existing immutable releases, but its artifact did
  // not preserve authored landings separately from Recast projections. New
  // processor completions and approvals must use V9 so the trust boundary can
  // bind both without accepting an arbitrary substituted landing.
  if (parsedArtifact.data.schemaVersion === "spatial-navigation-v8") return false;
  const comparable = (
    connections: typeof parsedConnections.data,
    useRequestedLandings: boolean,
  ) => connections.map((connection) => {
    const {
      requestedStartPosition,
      requestedEndPosition,
      startPosition,
      endPosition,
      ...semanticConnection
    } = connection;
    return {
      ...semanticConnection,
      startPosition: useRequestedLandings ? requestedStartPosition ?? startPosition : startPosition,
      endPosition: useRequestedLandings ? requestedEndPosition ?? endPosition : endPosition,
    };
  });
  return JSON.stringify(comparable(
    parsedArtifact.data.offMeshConnections,
    parsedArtifact.data.schemaVersion === "spatial-navigation-v9",
  )) === JSON.stringify(comparable(parsedConnections.data, false));
}

export function approvedFloorplanNavigationCanAutoAccept(parameters: unknown): boolean {
  if (!parameters || typeof parameters !== "object") return false;
  const automaticLayout = Reflect.get(parameters, "automaticLayout");
  if (!automaticLayout || typeof automaticLayout !== "object") return false;
  return (
    Reflect.get(automaticLayout, "schemaVersion") === "automatic-floorplan-layout-v2" &&
    typeof Reflect.get(automaticLayout, "floorplanExtractionId") === "string" &&
    typeof Reflect.get(automaticLayout, "floorplanRevisionId") === "string" &&
    /^[a-f0-9]{64}$/i.test(String(Reflect.get(automaticLayout, "planHash") ?? ""))
  );
}

// Every approval of a capture-pinned build — manual or automatic — freezes a
// receipt bound by hash to the exact final agreement and artifact it cleared,
// naming each crossing with its canonical geometry, the classification that
// covered it, and whether that answer came from frozen proposal evidence or
// an explicit manual resolution. The receipt must stand on its own: proving
// what was approved cannot depend on later re-interpreting a mutable column
// elsewhere. Returns null when the build pins no capture agreement.
export async function buildFinalCaptureApprovalReceipt(input: {
  artifactJson: string | null;
  coverage: readonly FinalAgreementCoverage[];
  sourceRevisionId: string | null;
  reviewedBy: string | null;
}): Promise<string | null> {
  const storedArtifact = parseStoredObject(input.artifactJson ?? "null");
  const finalAgreement = storedArtifact && typeof storedArtifact === "object"
    ? Reflect.get(storedArtifact, "finalCaptureAgreement")
    : undefined;
  const parsedAgreement = floorplanCaptureAgreementSchema.optional()
    .safeParse(finalAgreement ?? undefined);
  if (!parsedAgreement.success || !parsedAgreement.data) return null;
  return JSON.stringify({
    schemaVersion: "final-capture-approval-v2",
    finalAgreementSha256: await sha256Hex(JSON.stringify(parsedAgreement.data)),
    navigationArtifactSha256: await sha256Hex(input.artifactJson ?? ""),
    matcherVersion: "capture-reconciliation-v2",
    result: "passed",
    ...(input.sourceRevisionId ? { sourceRevisionId: input.sourceRevisionId } : {}),
    resolvedFindings: input.coverage,
    reviewedBy: input.reviewedBy,
    reviewedAt: new Date().toISOString(),
  });
}

export function approvedFloorplanNavigationAcceptanceDecision(input: {
  parameters: unknown;
  revision: { status: string; planHash: string; captureAgreementJson?: string | null } | null;
  frozenAuthoringHash: string | null;
  currentAuthoringHash: string | null;
  finalCaptureAgreement?: unknown;
}): {
  approved: boolean;
  reason: string;
  finalAgreementCoverage: FinalAgreementCoverage[];
} {
  if (!approvedFloorplanNavigationCanAutoAccept(input.parameters)) {
    return {
      approved: false,
      finalAgreementCoverage: [],
      reason: "Automatic acceptance is not available for a proposal-only or manual navigation build.",
    };
  }
  const automaticLayout = Reflect.get(input.parameters as object, "automaticLayout") as object;
  const expectedPlanHash = String(Reflect.get(automaticLayout, "planHash"));
  if (!input.revision || input.revision.status !== "approved") {
    return {
      approved: false,
      finalAgreementCoverage: [],
      reason: "Automatic acceptance blocked: the source floor-plan revision is no longer current and approved.",
    };
  }
  if (input.revision.planHash !== expectedPlanHash) {
    return {
      approved: false,
      finalAgreementCoverage: [],
      reason: `Automatic acceptance blocked: expected_plan_hash=${expectedPlanHash}, asked_plan_hash=${input.revision.planHash}.`,
    };
  }
  // The review endpoint already refuses to approve a plan while the capture
  // disputes a wall without an operator classification. Re-proving it from
  // the revision's own frozen blob keeps automatic acceptance objective: it
  // never trusts that some earlier endpoint enforced the rule.
  const agreementBlock = frozenCaptureAgreementBlockReason(
    input.revision.captureAgreementJson ?? null,
  );
  if (agreementBlock) {
    return { approved: false, finalAgreementCoverage: [], reason: agreementBlock };
  }
  // The proposal agreement above cannot see walls added or moved during the
  // review itself. When a capture was pinned for this build, the build's own
  // final agreement — computed on the exact barrier set the collision was
  // cooked from — must reconcile with the frozen classifications.
  const finalReconciliation = finalCaptureAgreementReconciliation({
    captureExpected: Boolean(
      Reflect.get(automaticLayout, "capture") &&
        typeof Reflect.get(automaticLayout, "capture") === "object",
    ),
    finalAgreement: input.finalCaptureAgreement,
    captureAgreementJson: input.revision.captureAgreementJson ?? null,
  });
  if (finalReconciliation.blockReason) {
    return {
      approved: false,
      finalAgreementCoverage: [],
      reason: finalReconciliation.blockReason,
    };
  }
  if (
    !input.frozenAuthoringHash || !input.currentAuthoringHash ||
    input.frozenAuthoringHash !== input.currentAuthoringHash
  ) {
    return {
      approved: false,
      finalAgreementCoverage: [],
      reason: `Automatic acceptance blocked: expected_authoring_hash=${input.frozenAuthoringHash ?? "missing"}, asked_authoring_hash=${input.currentAuthoringHash ?? "missing"}.`,
    };
  }
  return {
    approved: true,
    finalAgreementCoverage: finalReconciliation.coverage,
    reason: "Automatically accepted after schema, Recast reachability, Rapier physical, structural, revision, capture-agreement, and authoring-hash validation passed.",
  };
}


function storedPosterCamera(value: string): unknown {
  const provenance = parseStoredObject(value);
  return provenance && typeof provenance === "object"
    ? Reflect.get(provenance, "posterCamera")
    : undefined;
}

function storedCaptureAdapter(value: string): CaptureAdapterId | null {
  const provenance = parseStoredObject(value);
  if (!provenance || typeof provenance !== "object") return null;
  const candidate = Reflect.get(provenance, "assetProducer") ??
    Reflect.get(provenance, "adapter");
  return typeof candidate === "string" &&
      captureAdapterIds.includes(candidate as CaptureAdapterId)
    ? candidate as CaptureAdapterId
    : null;
}

function storedPairedCaptureJourney(value: string): PairedCaptureJourney | null {
  const provenance = parseStoredObject(value);
  return provenance && typeof provenance === "object"
    ? parsePairedCaptureJourney(Reflect.get(provenance, "captureJourney"))
    : null;
}

async function reconcileAutomaticPairedCaptureJourney(
  database: D1Database,
  projectId: string,
  versionId: string,
): Promise<PairedCaptureJourney | null> {
  const version = await database.prepare(`
    SELECT source_provenance_json
    FROM scene_versions
    WHERE id = ? AND project_id = ?
  `).bind(versionId, projectId).first<{ source_provenance_json: string }>();
  const journey = version
    ? storedPairedCaptureJourney(version.source_provenance_json)
    : null;
  if (
    !journey?.geometryAssetId ||
    journey.qualification?.method !== AUTOMATIC_PAIRED_CAPTURE_METHOD ||
    journey.qualification.status === "verified"
  ) return journey;

  const jobs = await database.prepare(`
    SELECT input_asset_id, state, output_json
    FROM processing_jobs
    WHERE project_id = ? AND version_id = ? AND input_asset_id IN (?, ?)
    ORDER BY created_at DESC
  `).bind(
    projectId,
    versionId,
    journey.primaryAssetId,
    journey.geometryAssetId,
  ).all<{ input_asset_id: string; state: string; output_json: string | null }>();
  const latestByAsset = new Map<string, { state: string; output_json: string | null }>();
  for (const job of jobs.results) {
    if (!latestByAsset.has(job.input_asset_id)) latestByAsset.set(job.input_asset_id, job);
  }
  const primaryJob = latestByAsset.get(journey.primaryAssetId);
  const geometryJob = latestByAsset.get(journey.geometryAssetId);
  if (!primaryJob || !geometryJob) return journey;
  const terminalStates = new Set(["SUCCEEDED", "FAILED", "DEAD_LETTER", "CANCELLED"]);
  if (!terminalStates.has(primaryJob.state) || !terminalStates.has(geometryJob.state)) return journey;

  const primaryEvidence = coordinateEvidenceFromJobOutput(primaryJob.output_json);
  const geometryEvidence = coordinateEvidenceFromJobOutput(geometryJob.output_json);
  let resolved: PairedCaptureJourney;
  if (!primaryEvidence || !geometryEvidence) {
    const missing = [
      ...(!primaryEvidence ? ["visual PLY"] : []),
      ...(!geometryEvidence ? ["geometry PLY"] : []),
    ].join(" and ");
    resolved = setPairedCaptureAutomaticQualification(journey, {
      method: AUTOMATIC_PAIRED_CAPTURE_METHOD,
      status: "blocked",
      reason: `Automatic qualification could not read complete coordinate evidence from the ${missing}.`,
    });
  } else {
    const result = qualifyPairedPlyCoordinateEvidence(primaryEvidence, geometryEvidence);
    resolved = setPairedCaptureAutomaticQualification(journey, result.qualified
      ? {
        method: result.method,
        status: "verified",
        coordinateFrameId: result.coordinateFrameId,
        sourceUpAxis: result.sourceUpAxis,
        worldUnit: result.worldUnit,
        overlapBounds: result.overlapBounds,
        visual: result.visual,
        geometry: result.geometry,
      }
      : {
        method: AUTOMATIC_PAIRED_CAPTURE_METHOD,
        status: "blocked",
        reason: result.reason,
      });
  }
  const parsedProvenance = parseStoredObject(version!.source_provenance_json);
  const provenance = parsedProvenance && typeof parsedProvenance === "object" &&
      !Array.isArray(parsedProvenance)
    ? { ...parsedProvenance }
    : {};
  await database.prepare(`
    UPDATE scene_versions
    SET source_provenance_json = ?, updated_at = datetime('now')
    WHERE id = ? AND project_id = ? AND source_provenance_json = ?
  `).bind(
    JSON.stringify({ ...provenance, captureJourney: resolved }),
    versionId,
    projectId,
    version!.source_provenance_json,
  ).run();
  return resolved;
}

function coordinateEvidenceFromJobOutput(value: string | null): PlyCoordinateEvidence | null {
  const output = parseStoredObject(value ?? "");
  const report = output && typeof output === "object" ? Reflect.get(output, "report") : null;
  const source = report && typeof report === "object" ? Reflect.get(report, "source") : null;
  return source && typeof source === "object"
    ? parsePlyCoordinateEvidenceReceipt(Reflect.get(source, "coordinateEvidence"))
    : null;
}

async function nextReleaseNumber(database: D1Database, projectId: string): Promise<number> {
  const allocated = await database.prepare(
    "SELECT COALESCE(MAX(release_number), 0) + 1 AS next FROM releases WHERE project_id = ?",
  ).bind(projectId).first<{ next: number }>();
  return allocated?.next ?? 1;
}

type ReleaseRepublishIntentResult = {
  id: string;
  status: "completed" | "failed";
  releaseId: string | null;
  error: string | null;
};

function failReleaseRepublishIntentForJobStatement(
  database: D1Database,
  jobId: string,
  message: string,
  organisationId?: string,
): D1PreparedStatement {
  const organisationGuard = organisationId ? " AND organisation_id = ?" : "";
  return database.prepare(`
    UPDATE release_republish_intents
    SET status = 'failed', error_message = ?, completed_at = datetime('now'),
      updated_at = datetime('now')
    WHERE navigation_build_id IN (
      SELECT id FROM scene_navigation_builds
      WHERE job_id = ?${organisationGuard}
    ) AND status = 'pending'
  `).bind(message, jobId, ...(organisationId ? [organisationId] : []));
}

async function failReleaseRepublishIntent(
  database: D1Database,
  navigationBuildId: string,
  message: string,
): Promise<ReleaseRepublishIntentResult | null> {
  const failed = await database.prepare(`
    UPDATE release_republish_intents
    SET status = 'failed', error_message = ?, completed_at = datetime('now'),
      updated_at = datetime('now')
    WHERE navigation_build_id = ? AND status = 'pending'
    RETURNING id
  `).bind(message, navigationBuildId).first<{ id: string }>();
  return failed
    ? { id: failed.id, status: "failed", releaseId: null, error: message }
    : null;
}

export async function completeReleaseRepublishIntent(
  env: Env,
  navigationBuildId: string,
  requestId: string,
): Promise<ReleaseRepublishIntentResult | null> {
  const intent = await env.DB.prepare(`
    SELECT i.id, i.organisation_id, i.project_id, i.version_id,
      i.source_release_id, i.requested_by, i.status,
      nb.status AS navigation_status,
      r.web_asset_id, r.poster_asset_id, r.access_policy, r.access_token_hash,
      r.viewer_config_json, r.expires_at, r.revoked_at,
      r.workflow_policy_revision_id AS source_policy_revision_id,
      rc.id AS channel_id, rc.slug, rc.active_release_id,
      web.integrity_status AS web_integrity_status, web.deleted_at AS web_deleted_at,
      poster.integrity_status AS poster_integrity_status, poster.deleted_at AS poster_deleted_at
    FROM release_republish_intents i
    JOIN scene_navigation_builds nb ON nb.id = i.navigation_build_id
      AND nb.organisation_id = i.organisation_id
      AND nb.project_id = i.project_id AND nb.version_id = i.version_id
    JOIN releases r ON r.id = i.source_release_id
      AND r.organisation_id = i.organisation_id
      AND r.project_id = i.project_id AND r.version_id = i.version_id
    LEFT JOIN release_channels rc ON rc.organisation_id = i.organisation_id
      AND rc.project_id = i.project_id AND rc.active_release_id = r.id
    JOIN assets web ON web.id = r.web_asset_id
      AND web.organisation_id = i.organisation_id
      AND web.project_id = i.project_id AND web.version_id = i.version_id
    LEFT JOIN assets poster ON poster.id = r.poster_asset_id
      AND poster.organisation_id = i.organisation_id
      AND poster.project_id = i.project_id AND poster.version_id = i.version_id
    WHERE i.navigation_build_id = ? AND i.status = 'pending'
  `).bind(navigationBuildId).first<{
    id: string;
    organisation_id: string;
    project_id: string;
    version_id: string;
    source_release_id: string;
    requested_by: string;
    status: string;
    navigation_status: string;
    web_asset_id: string;
    poster_asset_id: string | null;
    access_policy: string;
    access_token_hash: string | null;
    viewer_config_json: string;
    expires_at: string | null;
    revoked_at: string | null;
    channel_id: string | null;
    slug: string | null;
    active_release_id: string | null;
    web_integrity_status: string;
    web_deleted_at: string | null;
    poster_integrity_status: string | null;
    poster_deleted_at: string | null;
    source_policy_revision_id: string | null;
  }>();
  if (!intent) return null;
  const fail = (message: string) =>
    failReleaseRepublishIntent(env.DB, navigationBuildId, message);
  if (intent.navigation_status !== "APPROVED") return null;
  if (!intent.channel_id || !intent.slug || intent.active_release_id !== intent.source_release_id) {
    return fail("Automatic republish stopped because the source release is no longer active");
  }
  if (intent.revoked_at) {
    return fail("Automatic republish stopped because the source release was revoked");
  }
  if (intent.access_policy === "token") {
    return fail("Token-protected releases require manual publication with a new recipient token");
  }
  if (intent.expires_at && Date.parse(intent.expires_at) <= Date.now()) {
    return fail("Automatic republish stopped because the source release expired");
  }
  if (intent.web_integrity_status !== "verified" || intent.web_deleted_at) {
    return fail("Automatic republish stopped because the published web asset is no longer verified");
  }
  if (
    intent.poster_asset_id &&
    (intent.poster_integrity_status !== "verified" || intent.poster_deleted_at)
  ) {
    return fail("Automatic republish stopped because the published poster is no longer verified");
  }

  const project = await scopedProject(env.DB, intent.organisation_id, intent.project_id);
  if (!project) {
    return fail("Automatic republish stopped because the governed project no longer exists");
  }
  const frozenPolicy = await workflowPolicyForSceneVersion(
    env.DB,
    project,
    intent.version_id,
  );
  if (frozenPolicy.classificationStatus === "legacy_unknown") {
    return fail(
      "Automatic republish stopped because the scene version has an unclassified workflow policy",
    );
  }
  if (
    !frozenPolicy.revisionId ||
    frozenPolicy.revisionId !== intent.source_policy_revision_id
  ) {
    return fail(
      "Automatic republish stopped because the source release is not bound to the scene version's exact workflow-policy revision",
    );
  }
  const viewerConfig = parseStoredObject(intent.viewer_config_json);
  const defaultMovementMode = viewerConfig && typeof viewerConfig === "object"
    ? readStringProperty(viewerConfig, "defaultMovementMode") ?? "free-roam"
    : "free-roam";
  const policyViolations = releasePolicyViolations(frozenPolicy.policy, {
    accessPolicy: intent.access_policy,
    defaultMovementMode,
  });
  if (Object.keys(policyViolations).length) {
    return fail(
      `Automatic republish stopped because the frozen workflow policy rejects the source release: ${JSON.stringify(policyViolations)}`,
    );
  }
  const navigationClearanceViolations = await releaseNavigationClearanceViolations(
    env.DB,
    intent.project_id,
    intent.version_id,
    frozenPolicy.policy,
  );
  if (Object.keys(navigationClearanceViolations).length) {
    return fail(
      `Automatic republish stopped because navigation clearance no longer satisfies the frozen workflow policy: ${JSON.stringify(navigationClearanceViolations)}`,
    );
  }
  if (
    ["public", "unlisted"].includes(intent.access_policy) &&
    await sceneVersionUsesOperatorAttestation(env.DB, intent.project_id, intent.version_id)
  ) {
    return fail(
      "Automatic republish stopped because public release requires processor-qualified registration evidence",
    );
  }
  if (
    frozenPolicy.policy.hosting === "managed-required" &&
    !(await projectHasActiveManagedHosting(env.DB, intent.organisation_id, intent.project_id))
  ) {
    return fail(
      "Automatic republish stopped because the frozen workflow policy requires active managed hosting",
    );
  }

  try {
    const spatialSnapshot = await captureSpatialSnapshot(
      env.DB,
      intent.organisation_id,
      intent.project_id,
      intent.version_id,
    );
    const entities = Reflect.get(spatialSnapshot, "entities");
    const connectivity = inspectWalkableConnectivity(Array.isArray(entities) ? entities : []);
    if (connectivity.componentCount > 1) {
      return fail(
        `Automatic republish stopped because the rebuilt walking map has ${connectivity.componentCount} disconnected components`,
      );
    }
    const walkingPackage = await verifiedPhysicalNavigation(
      env,
      intent.organisation_id,
      intent.project_id,
      intent.version_id,
      spatialSnapshot,
    );
    if (!walkingPackage) {
      return fail(
        "Automatic republish stopped because the approved collision, navigation report, and Detour navmesh are not all verified",
      );
    }
    const navigationAssets = Reflect.get(spatialSnapshot, "navigationAssets");
    const snapshotNavigationBuildId = navigationAssets && typeof navigationAssets === "object"
      ? readNullableStringProperty(navigationAssets, "buildId")
      : null;
    if (snapshotNavigationBuildId !== navigationBuildId) {
      return fail(
        "Automatic republish stopped because the verified walking package is not the exact rebuilt navigation map",
      );
    }
    const completedWalkTest = await env.DB.prepare(`
      SELECT id FROM scene_navigation_walk_tests
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND navigation_build_id = ?
      ORDER BY completed_at DESC LIMIT 1
    `).bind(
      intent.organisation_id,
      intent.project_id,
      intent.version_id,
      navigationBuildId,
    ).first<{ id: string }>();
    if (!completedWalkTest) return null;

    const releaseId = crypto.randomUUID();
    const publishedAt = new Date().toISOString();
    const spatialSnapshotJson = JSON.stringify(spatialSnapshot);
    await env.DB.batch([
      env.DB.prepare(`
        INSERT INTO releases (
          id, organisation_id, project_id, version_id, web_asset_id, poster_asset_id,
          access_policy, access_token_hash, viewer_config_json, spatial_snapshot_json,
          published_at, expires_at, created_by, client_operation_id, release_number,
          workflow_policy_revision_id
        )
        SELECT ?, i.organisation_id, i.project_id, i.version_id,
          source.web_asset_id, source.poster_asset_id, source.access_policy,
          source.access_token_hash, source.viewer_config_json, ?, ?, source.expires_at,
          i.requested_by, i.id,
          (SELECT COALESCE(MAX(existing.release_number), 0) + 1
            FROM releases existing WHERE existing.project_id = i.project_id),
          source.workflow_policy_revision_id
        FROM release_republish_intents i
        JOIN release_channels rc ON rc.organisation_id = i.organisation_id
          AND rc.project_id = i.project_id AND rc.active_release_id = i.source_release_id
        JOIN releases source ON source.id = i.source_release_id
          AND source.organisation_id = i.organisation_id
          AND source.project_id = i.project_id AND source.version_id = i.version_id
        JOIN assets web ON web.id = source.web_asset_id
          AND web.organisation_id = i.organisation_id
          AND web.project_id = i.project_id AND web.version_id = i.version_id
        LEFT JOIN assets poster ON poster.id = source.poster_asset_id
          AND poster.organisation_id = i.organisation_id
          AND poster.project_id = i.project_id AND poster.version_id = i.version_id
        WHERE i.id = ? AND i.status = 'pending'
          AND source.revoked_at IS NULL AND source.access_policy != 'token'
          AND (source.expires_at IS NULL OR unixepoch(source.expires_at) > unixepoch('now'))
          AND web.integrity_status = 'verified' AND web.deleted_at IS NULL
          AND (source.poster_asset_id IS NULL OR (
            poster.integrity_status = 'verified' AND poster.deleted_at IS NULL
          ))
      `).bind(
        releaseId,
        spatialSnapshotJson,
        publishedAt,
        intent.id,
      ),
      env.DB.prepare(`
        UPDATE release_channels
        SET active_release_id = ?, activation_generation = activation_generation + 1,
          updated_at = datetime('now')
        WHERE id = ? AND active_release_id = ?
          AND EXISTS (SELECT 1 FROM releases WHERE id = ?)
      `).bind(releaseId, intent.channel_id, intent.source_release_id, releaseId),
      env.DB.prepare(
        "UPDATE scene_versions SET status = 'PUBLISHED', updated_at = datetime('now') WHERE id = ? AND EXISTS (SELECT 1 FROM releases WHERE id = ?)",
      ).bind(intent.version_id, releaseId),
      env.DB.prepare(
        "UPDATE projects SET status = 'PUBLISHED', updated_at = datetime('now') WHERE id = ? AND organisation_id = ? AND EXISTS (SELECT 1 FROM releases WHERE id = ?)",
      ).bind(intent.project_id, intent.organisation_id, releaseId),
      env.DB.prepare(`
        UPDATE release_republish_intents
        SET status = 'completed', completed_release_id = ?, error_message = NULL,
          completed_at = datetime('now'), updated_at = datetime('now')
        WHERE id = ? AND status = 'pending'
          AND EXISTS (SELECT 1 FROM release_channels WHERE id = ? AND active_release_id = ?)
      `).bind(releaseId, intent.id, intent.channel_id, releaseId),
      env.DB.prepare(`
        INSERT INTO audit_events (
          id, organisation_id, actor_user_id, action, resource_type, resource_id,
          request_id, metadata_json
        )
        SELECT ?, organisation_id, requested_by, 'release.auto_republish',
          'release', ?, ?, ?
        FROM release_republish_intents
        WHERE id = ? AND status = 'completed' AND completed_release_id = ?
      `).bind(
        crypto.randomUUID(),
        releaseId,
        requestId,
        JSON.stringify({
          slug: intent.slug,
          sourceReleaseId: intent.source_release_id,
          navigationBuildId,
        }),
        intent.id,
        releaseId,
      ),
    ]);
    const completed = await env.DB.prepare(`
      SELECT status, completed_release_id, error_message
      FROM release_republish_intents WHERE id = ?
    `).bind(intent.id).first<{
      status: "pending" | "completed" | "failed";
      completed_release_id: string | null;
      error_message: string | null;
    }>();
    if (completed?.status === "completed") {
      return {
        id: intent.id,
        status: "completed",
        releaseId: completed.completed_release_id,
        error: null,
      };
    }
    return fail(
      "Automatic republish stopped because the active release or its verified assets changed during publication",
    );
  } catch (error) {
    const message = `Automatic republish failed: ${errorMessage(error)}`;
    console.error(JSON.stringify({
      event: "release.auto_republish_failed",
      intentId: intent.id,
      navigationBuildId,
      error: errorMessage(error),
    }));
    return fail(message);
  }
}

function isReleaseNumberSequenceConflict(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  return message.includes("UNIQUE constraint failed") &&
    message.includes("releases.project_id") &&
    message.includes("releases.release_number");
}

function isFloorplanRevisionSequenceConflict(error: unknown): boolean {
  const message = error instanceof Error ? error.message : String(error);
  return message.includes("UNIQUE constraint failed") &&
    message.includes("floorplan_revisions.organisation_id") &&
    message.includes("floorplan_revisions.project_id") &&
    message.includes("floorplan_revisions.version_id") &&
    message.includes("floorplan_revisions.revision_number");
}

type MeasurementFootprint = {
  entityId: string;
  label: string;
  points: Array<[number, number]>;
};

function measurementFootprint(
  row: { id: string; label: string; geometry_json: string },
): MeasurementFootprint | null {
  let geometry: unknown;
  try {
    geometry = JSON.parse(row.geometry_json);
  } catch {
    return null;
  }
  if (!geometry || typeof geometry !== "object") return null;
  const type = Reflect.get(geometry, "type");
  const rawPoints = Reflect.get(geometry, "points");
  if (!Array.isArray(rawPoints)) return null;
  if (type === "box" && rawPoints.length === 2) {
    const first = finitePoint3(rawPoints[0]);
    const second = finitePoint3(rawPoints[1]);
    if (!first || !second) return null;
    const minX = Math.min(first[0], second[0]);
    const maxX = Math.max(first[0], second[0]);
    const minZ = Math.min(first[2], second[2]);
    const maxZ = Math.max(first[2], second[2]);
    if (maxX - minX < 0.05 || maxZ - minZ < 0.05) return null;
    return {
      entityId: row.id,
      label: row.label,
      points: [[minX, minZ], [maxX, minZ], [maxX, maxZ], [minX, maxZ]],
    };
  }
  if (type === "polygon" && rawPoints.length >= 3) {
    const points: Array<[number, number]> = [];
    for (const rawPoint of rawPoints) {
      const point = finitePoint3(rawPoint);
      if (!point) return null;
      points.push([point[0], point[2]]);
    }
    const area = Math.abs(points.reduce((sum, point, index) => {
      const next = points[(index + 1) % points.length]!;
      return sum + point[0] * next[1] - next[0] * point[1];
    }, 0) / 2);
    return area >= 0.0025 ? { entityId: row.id, label: row.label, points } : null;
  }
  return null;
}

function measurementSourceGeometry(footprints: MeasurementFootprint[]): string {
  return JSON.stringify(footprints.map((footprint) => ({
    entityId: footprint.entityId,
    label: footprint.label,
    points: footprint.points,
  })));
}

function polygonArea2(points: Array<[number, number]>): number {
  return Math.abs(points.reduce((sum, point, index) => {
    const next = points[(index + 1) % points.length]!;
    return sum + point[0] * next[1] - next[0] * point[1];
  }, 0) / 2);
}

function semanticExtractionApi(run: SemanticExtractionRow): Record<string, unknown> {
  return {
    id: run.id,
    projectId: run.project_id,
    versionId: run.version_id,
    inputAssetId: run.input_asset_id,
    jobId: run.job_id,
    method: run.method,
    status: run.status,
    parameters: parseStoredObject(run.parameters_json),
    summary: run.summary_json ? parseStoredObject(run.summary_json) : null,
    reportAssetId: run.report_asset_id,
    candidateCount: run.candidate_count,
    reviewDecision: run.review_decision,
    reviewNote: run.review_note,
    reviewedAt: run.reviewed_at,
    createdAt: run.created_at,
    updatedAt: run.updated_at,
  };
}

function semanticCandidateApi(value: unknown): Record<string, unknown> {
  const row = value && typeof value === "object"
    ? value as Record<string, unknown>
    : {};
  const {
    elevation_m: elevation,
    area_m2: area,
    world_unit: rawWorldUnit,
    ...rest
  } = row;
  return {
    ...rest,
    elevation,
    area,
    worldUnit: parseWorldUnit(rawWorldUnit),
  };
}

// Read-only evidence about a public ASTM E57 container. Vendor extension field
// names travel verbatim; nothing here decodes a vendor classification or mesh
// schema, so the Studio can list them without asserting what they mean.
function captureScanStructureApi(value: unknown): Record<string, unknown> {
  const row = value && typeof value === "object" ? value as Record<string, unknown> : {};
  const storedFieldNames = parseStoredObject(String(row.vendor_field_names_json ?? "[]"));
  const vendorFieldNames = (Array.isArray(storedFieldNames) ? storedFieldNames : [])
    .filter((name): name is string => typeof name === "string");
  return {
    id: row.id,
    assetId: row.asset_id,
    assetFileName: row.asset_file_name,
    assetFormat: row.asset_format,
    jobId: row.job_id,
    reportAssetId: row.report_asset_id,
    reportFileName: row.report_file_name,
    reportSha256: row.report_sha256 ?? row.report_asset_sha256 ?? null,
    method: row.method,
    status: row.status,
    sourceFormat: row.source_format,
    scanCount: row.scan_count,
    imageCount: row.image_count,
    hasPerScanPoses: row.has_per_scan_poses === 1,
    vendorFieldNames,
    unreadableReason: row.unreadable_reason ?? null,
    createdAt: row.created_at,
    limitation:
      "Only the public ASTM E57 container structure was read. Vendor classification and mesh semantics are not parsed, and no structural claim derives from this reading.",
  };
}

