function floorplanPlanIssue(plan: FloorplanPlan): string | null {
  const identifiers = new Set<string>();
  const elevationByLevel = new Map<string, number>();
  for (const level of plan.levels) {
    if (identifiers.has(level.id)) return `Duplicate floor-plan identifier: ${level.id}`;
    identifiers.add(level.id);
    elevationByLevel.set(level.id, level.elevationM);
    const wallIds = new Set<string>();
    for (const room of level.rooms) {
      if (identifiers.has(room.id)) return `Duplicate floor-plan identifier: ${room.id}`;
      identifiers.add(room.id);
      if (polygonArea2(room.points) < 0.01) {
        return `Room ${room.label} has less than 0.01 square metre of enclosed area`;
      }
      if (floorplanPolygonSelfIntersects(room.points)) {
        return `Room ${room.label} has a self-intersecting outline`;
      }
    }
    for (const wall of level.walls) {
      if (identifiers.has(wall.id)) return `Duplicate floor-plan identifier: ${wall.id}`;
      identifiers.add(wall.id);
      wallIds.add(wall.id);
      if (floorplanDistance(wall.start, wall.end) < 0.05) {
        return `Wall ${wall.label} is shorter than 0.05 metre`;
      }
    }
    for (const opening of level.openings) {
      if (identifiers.has(opening.id)) return `Duplicate floor-plan identifier: ${opening.id}`;
      identifiers.add(opening.id);
      const observedWidth = floorplanDistance(opening.start, opening.end);
      if (observedWidth < 0.05) return `Opening ${opening.label} is shorter than 0.05 metre`;
      if (Math.abs(observedWidth - opening.widthM) > Math.max(0.1, opening.widthM * 0.1)) {
        return `Opening ${opening.label} width does not match its endpoints`;
      }
      if (opening.wallId && !wallIds.has(opening.wallId)) {
        return `Opening ${opening.label} refers to a wall outside its level`;
      }
    }
  }
  for (const connector of plan.connectors) {
    if (identifiers.has(connector.id)) return `Duplicate floor-plan identifier: ${connector.id}`;
    identifiers.add(connector.id);
    const lowerElevation = elevationByLevel.get(connector.lowerLevelId);
    const upperElevation = elevationByLevel.get(connector.upperLevelId);
    if (lowerElevation === undefined || upperElevation === undefined ||
      upperElevation <= lowerElevation) {
      return `Connector ${connector.label} does not join two ascending levels`;
    }
    const elevations = connector.points.map((point) => point[1]);
    if (Math.abs(Math.min(...elevations) - lowerElevation) > 0.1 ||
      Math.abs(Math.max(...elevations) - upperElevation) > 0.1) {
      return `Connector ${connector.label} endpoints do not match its level elevations`;
    }
  }
  return null;
}

function floorplanPolygonSelfIntersects(points: Array<[number, number]>): boolean {
  for (let first = 0; first < points.length; first += 1) {
    const firstNext = (first + 1) % points.length;
    for (let second = first + 1; second < points.length; second += 1) {
      const secondNext = (second + 1) % points.length;
      if (
        first === second ||
        firstNext === second ||
        secondNext === first ||
        (first === 0 && secondNext === 0)
      ) continue;
      if (floorplanSegmentsIntersect(
        points[first]!,
        points[firstNext]!,
        points[second]!,
        points[secondNext]!,
      )) return true;
    }
  }
  return false;
}

function floorplanSegmentsIntersect(
  a: [number, number],
  b: [number, number],
  c: [number, number],
  d: [number, number],
): boolean {
  const cross = (
    first: [number, number],
    second: [number, number],
    third: [number, number],
  ) => (second[0] - first[0]) * (third[1] - first[1]) -
    (second[1] - first[1]) * (third[0] - first[0]);
  const first = cross(a, b, c);
  const second = cross(a, b, d);
  const third = cross(c, d, a);
  const fourth = cross(c, d, b);
  return (
    ((first > 0 && second < 0) || (first < 0 && second > 0)) &&
    ((third > 0 && fourth < 0) || (third < 0 && fourth > 0))
  );
}

function floorplanDistance(start: [number, number], end: [number, number]): number {
  return Math.hypot(end[0] - start[0], end[1] - start[1]);
}

function floorplanExportApi(row: FloorplanExportRow): Record<string, unknown> {
  return {
    id: row.id,
    revisionId: row.revision_id,
    assetId: row.asset_id,
    format: row.format,
    generatorVersion: row.generator_version,
    planHash: row.plan_hash,
    status: row.status,
    fileName: row.file_name,
    mimeType: row.mime_type,
    sizeBytes: row.size_bytes,
    sha256: row.sha256,
    createdAt: databaseTimestampToIso(row.created_at),
    downloadUrl:
      `/api/projects/${row.project_id}/spatial/floorplan-exports/${row.id}/download`,
  };
}

function databaseTimestampToIso(value: string): string {
  const timestamp = value.includes("T") ? value : `${value.replace(" ", "T")}Z`;
  const parsed = new Date(timestamp);
  return Number.isNaN(parsed.valueOf()) ? value : parsed.toISOString().replace(/\.\d{3}Z$/, "Z");
}

function floorplanExportBytes(
  plan: FloorplanPlan,
  format: "svg" | "pdf" | "dxf",
  metadata: {
    projectName: string;
    revisionNumber: number;
    planHash: string;
    approvedAt: string;
  },
): { bytes: Uint8Array; mimeType: string } {
  if (format === "svg") {
    return {
      bytes: new TextEncoder().encode(generateIndicativeFloorplanSvg(plan, metadata)),
      mimeType: "image/svg+xml",
    };
  }
  if (format === "dxf") {
    return {
      bytes: new TextEncoder().encode(generateIndicativeFloorplanDxf(plan, metadata)),
      mimeType: "application/dxf",
    };
  }
  return {
    bytes: generateIndicativeFloorplanPdf(plan, metadata),
    mimeType: "application/pdf",
  };
}

function floorplanLevelBounds(level: FloorplanPlan["levels"][number]): {
  minX: number;
  minY: number;
  maxX: number;
  maxY: number;
} {
  const points = [
    ...level.rooms.flatMap((room) => room.points),
    ...level.walls.flatMap((wall) => [wall.start, wall.end]),
    ...level.openings.flatMap((opening) => [opening.start, opening.end]),
  ];
  return {
    minX: Math.min(...points.map((point) => point[0])),
    minY: Math.min(...points.map((point) => point[1])),
    maxX: Math.max(...points.map((point) => point[0])),
    maxY: Math.max(...points.map((point) => point[1])),
  };
}

function generateIndicativeFloorplanSvg(
  plan: FloorplanPlan,
  metadata: {
    projectName: string;
    revisionNumber: number;
    planHash: string;
    approvedAt: string;
  },
): string {
  const scale = 80;
  const padding = 48;
  const titleHeight = 88;
  const levelGap = 80;
  const layouts = plan.levels.map((level) => {
    const bounds = floorplanLevelBounds(level);
    return {
      level,
      bounds,
      width: Math.max(1, bounds.maxX - bounds.minX) * scale + padding * 2,
      height: Math.max(1, bounds.maxY - bounds.minY) * scale + padding * 2 + 36,
    };
  });
  const width = Math.max(720, ...layouts.map((layout) => layout.width));
  const height = titleHeight + layouts.reduce((sum, layout) => sum + layout.height, 0) +
    Math.max(0, layouts.length - 1) * levelGap + 56;
  let offsetY = titleHeight;
  const groups = layouts.map(({ level, bounds, height: levelHeight }) => {
    const x = (value: number) => padding + (value - bounds.minX) * scale;
    const y = (value: number) => padding + (bounds.maxY - value) * scale;
    const roomPaths = level.rooms.map((room) => {
      const points = room.points.map((point) => `${dxfNumber(x(point[0]))},${dxfNumber(y(point[1]))}`).join(" ");
      const centroid = room.points.reduce(
        (sum, point) => [sum[0] + point[0], sum[1] + point[1]] as [number, number],
        [0, 0],
      ).map((value) => value / room.points.length) as [number, number];
      return `<polygon points="${points}" class="room"/><text x="${dxfNumber(x(centroid[0]))}" y="${dxfNumber(y(centroid[1]))}" class="label">${xmlText(room.label)}</text>`;
    }).join("");
    const walls = level.walls.map((wall) =>
      `<line x1="${dxfNumber(x(wall.start[0]))}" y1="${dxfNumber(y(wall.start[1]))}" x2="${dxfNumber(x(wall.end[0]))}" y2="${dxfNumber(y(wall.end[1]))}" class="wall"/>`
    ).join("");
    const openings = level.openings.map((opening) =>
      `<line x1="${dxfNumber(x(opening.start[0]))}" y1="${dxfNumber(y(opening.start[1]))}" x2="${dxfNumber(x(opening.end[0]))}" y2="${dxfNumber(y(opening.end[1]))}" class="opening"/>`
    ).join("");
    const connectors = plan.connectors
      .filter((connector) => connector.lowerLevelId === level.id || connector.upperLevelId === level.id)
      .map((connector) => `<polygon points="${connector.points.map((point) =>
        `${dxfNumber(x(point[0]))},${dxfNumber(y(point[2]))}`).join(" ")}" class="connector"/>`)
      .join("");
    const result = `<g transform="translate(0 ${dxfNumber(offsetY)})"><text x="${padding}" y="24" class="level">${xmlText(level.label)} · ${dxfNumber(level.elevationM)} m</text><g transform="translate(0 36)">${roomPaths}${walls}${openings}${connectors}</g></g>`;
    offsetY += levelHeight + levelGap;
    return result;
  }).join("");
  return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="${Math.ceil(width)}" height="${Math.ceil(height)}" viewBox="0 0 ${Math.ceil(width)} ${Math.ceil(height)}" role="img" aria-labelledby="title desc">
  <title id="title">${xmlText(metadata.projectName)} indicative floor plan</title>
  <desc id="desc">Operator-reviewed indicative floor plan; not a survey or construction drawing.</desc>
  <style>
    .room{fill:#f4f1e8;stroke:#b7ad99;stroke-width:1.5}
    .wall{stroke:#171916;stroke-width:8;stroke-linecap:square}
    .opening{stroke:#fff;stroke-width:12;stroke-linecap:butt}
    .opening+*{stroke:#2f786f}
    .connector{fill:#dfff66;fill-opacity:.45;stroke:#607d00;stroke-width:3;stroke-dasharray:8 5}
    .label{font:500 13px system-ui,sans-serif;text-anchor:middle;dominant-baseline:middle;fill:#20231f}
    .level{font:700 18px system-ui,sans-serif;fill:#20231f}
    .meta{font:500 12px ui-monospace,monospace;fill:#62675f}
    .watermark{font:800 28px system-ui,sans-serif;letter-spacing:4px;fill:#ad3b2f;opacity:.7}
  </style>
  <rect width="100%" height="100%" fill="#fcfbf7"/>
  <text x="${padding}" y="34" class="level">${xmlText(metadata.projectName)}</text>
  <text x="${padding}" y="58" class="meta">Revision ${metadata.revisionNumber} · approved ${xmlText(metadata.approvedAt)} · SHA-256 ${metadata.planHash.slice(0, 16)}…</text>
  <text x="${width - padding}" y="38" text-anchor="end" class="watermark">INDICATIVE</text>
  ${groups}
  <text x="${padding}" y="${height - 24}" class="meta">Operator-reviewed visual deliverable · metres · not for survey, construction, title, or regulated reliance</text>
</svg>
`;
}

function generateIndicativeFloorplanDxf(
  plan: FloorplanPlan,
  metadata: {
    projectName: string;
    revisionNumber: number;
    planHash: string;
    approvedAt: string;
  },
): string {
  const values = [
    "999", `Whyme Labs indicative floor plan: ${dxfText(metadata.projectName)}`,
    "999", `Revision ${metadata.revisionNumber}; approved ${dxfText(metadata.approvedAt)}`,
    "999", `Plan SHA-256: ${metadata.planHash}`,
    "999", "INDICATIVE ONLY - NOT FOR SURVEY, CONSTRUCTION, TITLE, OR REGULATED RELIANCE",
    "0", "SECTION", "2", "HEADER",
    "9", "$ACADVER", "1", "AC1009",
    "9", "$INSUNITS", "70", "6",
    "0", "ENDSEC",
    "0", "SECTION", "2", "TABLES",
    "0", "TABLE", "2", "LAYER", "70", "6",
    ...dxfLayer("ROOM_OUTLINE", 8),
    ...dxfLayer("WALL", 7),
    ...dxfLayer("OPENING", 4),
    ...dxfLayer("CONNECTOR", 3),
    ...dxfLayer("LABEL", 3),
    ...dxfLayer("INDICATIVE", 1),
    "0", "ENDTAB", "0", "ENDSEC",
    "0", "SECTION", "2", "ENTITIES",
  ];
  for (const level of plan.levels) {
    for (const room of level.rooms) {
      for (let index = 0; index < room.points.length; index += 1) {
        const start = room.points[index]!;
        const end = room.points[(index + 1) % room.points.length]!;
        values.push(...floorplanDxfLine("ROOM_OUTLINE", start, end, level.elevationM));
      }
      const centroid = room.points.reduce(
        (sum, point) => [sum[0] + point[0], sum[1] + point[1]] as [number, number],
        [0, 0],
      ).map((value) => value / room.points.length) as [number, number];
      values.push(
        "0", "TEXT", "8", "LABEL",
        "10", dxfNumber(centroid[0]), "20", dxfNumber(centroid[1]),
        "30", dxfNumber(level.elevationM), "40", "0.25",
        "1", dxfText(room.label), "72", "1", "73", "2",
        "11", dxfNumber(centroid[0]), "21", dxfNumber(centroid[1]),
        "31", dxfNumber(level.elevationM),
      );
    }
    for (const wall of level.walls) {
      values.push(...floorplanDxfLine("WALL", wall.start, wall.end, level.elevationM));
    }
    for (const opening of level.openings) {
      values.push(...floorplanDxfLine("OPENING", opening.start, opening.end, level.elevationM));
    }
  }
  for (const connector of plan.connectors) {
    for (let index = 0; index < connector.points.length; index += 1) {
      const start = connector.points[index]!;
      const end = connector.points[(index + 1) % connector.points.length]!;
      values.push(...floorplanDxfLine3("CONNECTOR", start, end));
    }
  }
  values.push(
    "0", "TEXT", "8", "INDICATIVE",
    "10", "0", "20", "0", "30", "0", "40", "0.35",
    "1", "INDICATIVE - OPERATOR REVIEWED - NOT A SURVEY",
    "0", "ENDSEC", "0", "EOF",
  );
  return `${values.join("\n")}\n`;
}

function floorplanDxfLine3(
  layer: string,
  start: [number, number, number],
  end: [number, number, number],
): string[] {
  return [
    "0", "LINE", "8", layer,
    "10", dxfNumber(start[0]), "20", dxfNumber(start[2]), "30", dxfNumber(start[1]),
    "11", dxfNumber(end[0]), "21", dxfNumber(end[2]), "31", dxfNumber(end[1]),
  ];
}

function floorplanDxfLine(
  layer: string,
  start: [number, number],
  end: [number, number],
  elevationM: number,
): string[] {
  return [
    "0", "LINE", "8", layer,
    "10", dxfNumber(start[0]), "20", dxfNumber(start[1]), "30", dxfNumber(elevationM),
    "11", dxfNumber(end[0]), "21", dxfNumber(end[1]), "31", dxfNumber(elevationM),
  ];
}

function generateIndicativeFloorplanPdf(
  plan: FloorplanPlan,
  metadata: {
    projectName: string;
    revisionNumber: number;
    planHash: string;
    approvedAt: string;
  },
): Uint8Array {
  const pageWidth = 842;
  const pageHeight = 595;
  const pageObjects: Array<{ page: number; content: number; stream: string }> = [];
  for (const [index, level] of plan.levels.entries()) {
    const bounds = floorplanLevelBounds(level);
    const drawingWidth = Math.max(0.1, bounds.maxX - bounds.minX);
    const drawingHeight = Math.max(0.1, bounds.maxY - bounds.minY);
    const scale = Math.min(740 / drawingWidth, 450 / drawingHeight);
    const offsetX = 50 + (740 - drawingWidth * scale) / 2;
    const offsetY = 70 + (450 - drawingHeight * scale) / 2;
    const x = (value: number) => offsetX + (value - bounds.minX) * scale;
    const y = (value: number) => offsetY + (value - bounds.minY) * scale;
    const commands = [
      "0.18 0.20 0.17 RG 0.8 w",
      ...level.rooms.flatMap((room) => {
        const [first, ...rest] = room.points;
        return [
          `${dxfNumber(x(first![0]))} ${dxfNumber(y(first![1]))} m`,
          ...rest.map((point) => `${dxfNumber(x(point[0]))} ${dxfNumber(y(point[1]))} l`),
          "h S",
        ];
      }),
      "0.05 0.06 0.05 RG 4 w",
      ...level.walls.map((wall) =>
        `${dxfNumber(x(wall.start[0]))} ${dxfNumber(y(wall.start[1]))} m ${dxfNumber(x(wall.end[0]))} ${dxfNumber(y(wall.end[1]))} l S`
      ),
      "0.20 0.55 0.50 RG 7 w",
      ...level.openings.map((opening) =>
        `${dxfNumber(x(opening.start[0]))} ${dxfNumber(y(opening.start[1]))} m ${dxfNumber(x(opening.end[0]))} ${dxfNumber(y(opening.end[1]))} l S`
      ),
      "0.38 0.49 0.00 RG 2 w [7 4] 0 d",
      ...plan.connectors
        .filter((connector) => connector.lowerLevelId === level.id || connector.upperLevelId === level.id)
        .flatMap((connector) => {
          const [first, ...rest] = connector.points;
          return [
            `${dxfNumber(x(first![0]))} ${dxfNumber(y(first![2]))} m`,
            ...rest.map((point) => `${dxfNumber(x(point[0]))} ${dxfNumber(y(point[2]))} l`),
            "h S",
          ];
        }),
      "[] 0 d",
      "BT /F1 16 Tf 50 555 Td",
      `(${pdfText(metadata.projectName)} - ${pdfText(level.label)}) Tj ET`,
      "BT /F1 9 Tf 50 537 Td",
      `(Revision ${metadata.revisionNumber} | elevation ${dxfNumber(level.elevationM)} m | approved ${pdfText(metadata.approvedAt)}) Tj ET`,
      "1 0.2 0.16 rg BT /F1 18 Tf 650 555 Td (INDICATIVE) Tj ET",
      "0.25 0.27 0.24 rg BT /F1 8 Tf 50 32 Td",
      `(Operator-reviewed visual deliverable | metres | SHA-256 ${metadata.planHash.slice(0, 20)}... | not a survey or construction drawing) Tj ET`,
    ];
    pageObjects.push({
      page: 4 + index * 2,
      content: 5 + index * 2,
      stream: `${commands.join("\n")}\n`,
    });
  }
  const objectCount = 3 + pageObjects.length * 2;
  const objects = new Map<number, string>([
    [1, "<< /Type /Catalog /Pages 2 0 R >>"],
    [2, `<< /Type /Pages /Count ${pageObjects.length} /Kids [${pageObjects.map((entry) => `${entry.page} 0 R`).join(" ")}] >>`],
    [3, "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"],
  ]);
  for (const entry of pageObjects) {
    objects.set(
      entry.page,
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pageWidth} ${pageHeight}] /Resources << /Font << /F1 3 0 R >> >> /Contents ${entry.content} 0 R >>`,
    );
    objects.set(
      entry.content,
      `<< /Length ${new TextEncoder().encode(entry.stream).byteLength} >>\nstream\n${entry.stream}endstream`,
    );
  }
  const chunks: string[] = ["%PDF-1.4\n"];
  const offsets = [0];
  let byteOffset = new TextEncoder().encode(chunks[0]!).byteLength;
  for (let index = 1; index <= objectCount; index += 1) {
    offsets[index] = byteOffset;
    const chunk = `${index} 0 obj\n${objects.get(index)}\nendobj\n`;
    chunks.push(chunk);
    byteOffset += new TextEncoder().encode(chunk).byteLength;
  }
  const xrefOffset = byteOffset;
  const xref = [
    `xref\n0 ${objectCount + 1}\n`,
    "0000000000 65535 f \n",
    ...offsets.slice(1).map((offset) => `${String(offset).padStart(10, "0")} 00000 n \n`),
    `trailer\n<< /Size ${objectCount + 1} /Root 1 0 R >>\nstartxref\n${xrefOffset}\n%%EOF\n`,
  ].join("");
  chunks.push(xref);
  return new TextEncoder().encode(chunks.join(""));
}

function xmlText(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll("\"", "&quot;")
    .replaceAll("'", "&apos;");
}

function pdfText(value: string): string {
  return value
    .normalize("NFKD")
    .replace(/[^\x20-\x7e]/g, "?")
    .replace(/([\\()])/g, "\\$1")
    .slice(0, 500);
}

function measurementDeliverableApi(row: MeasurementDeliverableRow): {
  id: string;
  briefId: string;
  versionId: string;
  qaReportId: string;
  assetId: string;
  deliverableType: string;
  sourceGeometryHash: string;
  generatorVersion: string;
  fileName: string;
  mimeType: string;
  sizeBytes: number;
  sha256: string;
  status: string;
  createdAt: string;
  downloadUrl: string;
} {
  return {
    id: row.id,
    briefId: row.brief_id,
    versionId: row.version_id,
    qaReportId: row.qa_report_id,
    assetId: row.asset_id,
    deliverableType: row.deliverable_type,
    sourceGeometryHash: row.source_geometry_hash,
    generatorVersion: row.generator_version,
    fileName: row.file_name,
    mimeType: row.mime_type,
    sizeBytes: row.size_bytes,
    sha256: row.sha256,
    status: row.status,
    createdAt: row.created_at,
    downloadUrl: `/api/projects/${row.project_id}/measurement/deliverables/${row.id}/download`,
  };
}

function generateMeasurementDxf(input: {
  footprints: MeasurementFootprint[];
  units: "metres" | "millimetres";
  productType: "measured_floor_plan" | "scan_to_cad";
  intendedUse: string;
  exclusions: string | null;
  coordinateReference: string | null;
  relianceClass: string;
  toleranceMm: number;
  qaReportId: string;
  pointCount: number;
  rmseMm: number;
  maxMm: number;
  sourceGeometryHash: string;
  generatorVersion: string;
}): string {
  const scale = input.units === "millimetres" ? 1000 : 1;
  const unitCode = input.units === "millimetres" ? 4 : 6;
  const values: string[] = [
    "999", `Whyme Labs ${input.productType === "scan_to_cad" ? "Scan-to-CAD" : "Measured floor plan"} draft`,
    "999", `Generator: ${input.generatorVersion}`,
    "999", `QA report: ${input.qaReportId}`,
    "999", `Evidence: ${input.pointCount} independent points; RMSE ${dxfNumber(input.rmseMm)} mm; max ${dxfNumber(input.maxMm)} mm; tolerance ${dxfNumber(input.toleranceMm)} mm`,
    "999", `Reliance: ${dxfText(input.relianceClass)}; intended use: ${dxfText(input.intendedUse)}`,
    "999", `Coordinate reference: ${dxfText(input.coordinateReference ?? "local scene coordinates")}`,
    "999", `Exclusions: ${dxfText(input.exclusions ?? "none stated")}`,
    "999", `Source geometry SHA-256: ${input.sourceGeometryHash}`,
    "0", "SECTION",
    "2", "HEADER",
    "9", "$ACADVER",
    "1", "AC1009",
    "9", "$INSUNITS",
    "70", String(unitCode),
    "0", "ENDSEC",
    "0", "SECTION",
    "2", "TABLES",
    "0", "TABLE",
    "2", "LAYER",
    "70", "2",
    ...dxfLayer("ROOM_OUTLINE", 7),
    ...dxfLayer("ROOM_LABEL", 3),
    "0", "ENDTAB",
    "0", "ENDSEC",
    "0", "SECTION",
    "2", "ENTITIES",
  ];
  for (const footprint of input.footprints) {
    const points = footprint.points.map(([x, y]) => [x * scale, y * scale] as const);
    for (let index = 0; index < points.length; index += 1) {
      const start = points[index]!;
      const end = points[(index + 1) % points.length]!;
      values.push(
        "0", "LINE",
        "8", "ROOM_OUTLINE",
        "10", dxfNumber(start[0]),
        "20", dxfNumber(start[1]),
        "30", "0",
        "11", dxfNumber(end[0]),
        "21", dxfNumber(end[1]),
        "31", "0",
      );
    }
    const centroid = points.reduce(
      (sum, point) => [sum[0] + point[0], sum[1] + point[1]] as [number, number],
      [0, 0] as [number, number],
    ).map((value) => value / points.length) as [number, number];
    values.push(
      "0", "TEXT",
      "8", "ROOM_LABEL",
      "10", dxfNumber(centroid[0]),
      "20", dxfNumber(centroid[1]),
      "30", "0",
      "40", dxfNumber(input.units === "millimetres" ? 250 : 0.25),
      "1", dxfText(footprint.label),
      "72", "1",
      "73", "2",
      "11", dxfNumber(centroid[0]),
      "21", dxfNumber(centroid[1]),
      "31", "0",
    );
  }
  values.push("0", "ENDSEC", "0", "EOF");
  return `${values.join("\n")}\n`;
}

function dxfLayer(name: string, color: number): string[] {
  return ["0", "LAYER", "2", name, "70", "0", "62", String(color), "6", "CONTINUOUS"];
}

function dxfText(value: string): string {
  return value.replace(/[\r\n\u0000-\u001f]+/g, " ").trim().slice(0, 1000);
}

function dxfNumber(value: number): string {
  if (!Number.isFinite(value)) return "0";
  const rounded = Math.round(value * 1_000_000) / 1_000_000;
  return Object.is(rounded, -0) ? "0" : String(rounded);
}

function canonicalSourceToWorldTransform(value: unknown): {
  sourceUpAxis: "Y" | "Z";
  worldUnit: "metres" | "scene_units";
  metresPerSourceUnit: number;
  yawDegrees: number;
  translationMetres: [number, number, number];
} | null {
  if (!value || typeof value !== "object") return null;
  const sourceUpAxis = Reflect.get(value, "sourceUpAxis");
  const metresPerSourceUnit = Number(Reflect.get(value, "metresPerSourceUnit"));
  const yawDegrees = Number(Reflect.get(value, "yawDegrees"));
  const translationMetres = finitePoint3(Reflect.get(value, "translationMetres"));
  if (
    (sourceUpAxis !== "Y" && sourceUpAxis !== "Z") ||
    !Number.isFinite(metresPerSourceUnit) ||
    metresPerSourceUnit <= 0 ||
    !Number.isFinite(yawDegrees) ||
    !translationMetres
  ) return null;
  return {
    sourceUpAxis,
    worldUnit: parseWorldUnit(Reflect.get(value, "worldUnit")),
    metresPerSourceUnit,
    yawDegrees,
    translationMetres,
  };
}

type RuntimeBox = {
  entityId: string;
  label: string;
  min: [number, number, number];
  max: [number, number, number];
};

type RuntimeObstacleBox = {
  entityId: string;
  label: string;
  min: [number, number, number];
  max: [number, number, number];
};

const defaultNavigationProfile = {
  worldUnit: "metres",
  agentRadius: 0.22,
  agentHeight: 1.8,
  eyeHeight: 1.6,
  maxStepMetres: 0.1,
  maxSlopeDegrees: 45,
  maxSpeed: 1.6,
  maxAcceleration: 8,
} as const;

async function spatialVersionWorldUnit(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<WorldUnit> {
  const profile = await database.prepare(`
    SELECT world_unit
    FROM scene_navigation_profiles
    WHERE organisation_id = ? AND project_id = ? AND version_id = ?
  `).bind(organisationId, projectId, versionId).first<{ world_unit: string }>();
  return parseWorldUnit(profile?.world_unit);
}

async function isMetricSpatialVersion(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<boolean> {
  const results = await database.batch([
    database.prepare(`
      SELECT world_unit
      FROM scene_navigation_profiles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT count(*) AS count FROM (
        SELECT id FROM scene_entities
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
          AND status = 'active' AND world_unit <> 'metres'
        UNION ALL
        SELECT id FROM scene_navigation_obstacles
        WHERE organisation_id = ? AND project_id = ? AND version_id = ?
          AND status = 'active' AND world_unit <> 'metres'
      )
    `).bind(
      organisationId,
      projectId,
      versionId,
      organisationId,
      projectId,
      versionId,
    ),
  ]);
  const profile = requiredBatchResult(results, 0).results[0];
  const incompatible = requiredBatchResult(results, 1).results[0] as
    | { count?: number }
    | undefined;
  return parseWorldUnit(
    profile && typeof profile === "object"
      ? Reflect.get(profile, "world_unit")
      : undefined,
  ) === "metres" && Number(incompatible?.count ?? 0) === 0;
}

async function captureSpatialSnapshot(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<Record<string, unknown>> {
  const results = await database.batch([
    database.prepare(`
      SELECT id, parent_id, kind, label, description, position_json, geometry_json,
        metadata_json, sort_order, world_unit
      FROM scene_entities
      WHERE organisation_id = ? AND project_id = ? AND version_id = ? AND status = 'active'
      ORDER BY kind, sort_order, label
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT id, label, description, accessibility, estimated_seconds
      FROM scene_routes
      WHERE organisation_id = ? AND project_id = ? AND version_id = ? AND status = 'active'
      ORDER BY created_at
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT rs.route_id, rs.entity_id, rs.sequence_number, rs.camera_pose_json, rs.narration
      FROM scene_route_stops rs
      JOIN scene_routes r ON r.id = rs.route_id
      WHERE r.organisation_id = ? AND r.project_id = ? AND r.version_id = ?
        AND r.status = 'active'
      ORDER BY rs.route_id, rs.sequence_number
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT id, label, bounds_json, metadata_json, world_unit
      FROM scene_navigation_obstacles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ? AND status = 'active'
      ORDER BY label, created_at
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT world_unit, agent_radius, agent_height, eye_height, max_step_metres,
        max_slope_degrees, max_speed, max_acceleration
      FROM scene_navigation_profiles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT nb.id, nb.artifact_json, nb.authoring_hash,
        nav.id AS navmesh_asset_id, nav.format AS navmesh_format,
        nav.sha256 AS navmesh_sha256, nav.size_bytes AS navmesh_size_bytes,
        report.id AS report_asset_id, report.format AS report_format,
        report.sha256 AS report_sha256, report.size_bytes AS report_size_bytes
      FROM scene_navigation_builds nb
      JOIN assets nav ON nav.id = nb.navmesh_asset_id
        AND nav.organisation_id = nb.organisation_id
        AND nav.project_id = nb.project_id AND nav.version_id = nb.version_id
        AND nav.kind = 'navmesh' AND nav.format = 'bin'
        AND nav.integrity_status = 'verified' AND nav.deleted_at IS NULL
      JOIN assets report ON report.id = nb.report_asset_id
        AND report.organisation_id = nb.organisation_id
        AND report.project_id = nb.project_id AND report.version_id = nb.version_id
        AND report.kind = 'report' AND report.format = 'json'
        AND report.integrity_status = 'verified' AND report.deleted_at IS NULL
      WHERE nb.organisation_id = ? AND nb.project_id = ? AND nb.version_id = ?
        AND nb.status = 'APPROVED' AND nb.artifact_json IS NOT NULL
      ORDER BY nb.reviewed_at DESC, nb.updated_at DESC LIMIT 25
    `).bind(organisationId, projectId, versionId),
    database.prepare(`${NAVIGATION_TRAVERSAL_EVIDENCE_SELECT}
      WHERE t.organisation_id = ? AND t.project_id = ? AND t.version_id = ?
      ORDER BY t.label, t.created_at
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT revision.id, revision.plan_hash, revision.collision_asset_id,
        revision.collision_sha256, revision.navigation_receipt_version,
        revision.capture_agreement_json,
        collision.sha256 AS current_collision_sha256,
        collision.integrity_status AS collision_integrity_status,
        collision.deleted_at AS collision_deleted_at
      FROM floorplan_revisions revision
      LEFT JOIN assets collision ON collision.id = revision.collision_asset_id
      WHERE revision.organisation_id = ? AND revision.project_id = ?
        AND revision.version_id = ? AND revision.status = 'approved'
      ORDER BY revision.revision_number DESC, revision.created_at DESC LIMIT 1
    `).bind(organisationId, projectId, versionId),
  ]);
  const entities = requiredBatchResult(results, 0).results;
  const obstacles = requiredBatchResult(results, 3).results;
  const profile = requiredBatchResult(results, 4).results[0];
  const routeStops = requiredBatchResult(results, 2).results;
  const navigationTraversalRows = requiredBatchResult(results, 6).results;
  const navigationTraversals = navigationTraversalRows.filter(
    (row) => row && typeof row === "object" && Reflect.get(row, "status") === "active",
  );
  const authoringHash = await navigationAuthoringHash(
    profile,
    entities,
    obstacles,
    routeStops,
    navigationTraversalRows,
    floorplanNavigationReceipt(requiredBatchResult(results, 7).results[0]),
  );
  const approvedNavigation = approvedNavigationBuild(
    requiredBatchResult(results, 5).results,
    authoringHash,
  );
  const runtime = buildSpatialRuntime(entities, obstacles, profile);
  return {
    schemaVersion: "spatial-runtime-v5",
    entities,
    routes: requiredBatchResult(results, 1).results,
    routeStops,
    navigationObstacles: obstacles,
    navigationTraversals,
    collisionProxy: runtime.collisionProxy,
    navigationMesh: runtime.navigationMesh,
    obstacleProxy: runtime.obstacleProxy,
    navigationProfile: runtime.navigationProfile,
    navigationArtifact: approvedNavigation?.artifact ?? null,
    navigationAssets: approvedNavigation?.assets ?? null,
  };
}

type ApprovedNavigationPreview = {
  spatial: Record<string, unknown>;
  collisionAsset: AssetRow;
  registration: QualifiedSceneRegistration;
};

type NavigationPreviewQualification =
  | { ready: true; value: ApprovedNavigationPreview }
  | { ready: false; code: "scene_registration_missing" | "walking_package_missing"; message: string };

async function qualifyNavigationPreview(
  env: Env,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<NavigationPreviewQualification> {
  const registration = await qualifiedSceneRegistration(
    env.DB,
    organisationId,
    projectId,
    versionId,
  );
  if (!registration) {
    return {
      ready: false,
      code: "scene_registration_missing",
      message:
        "This version has no verified capture-to-scene registration. Upload the visual and registered metric geometry together from the same unchanged capture frame, or attach an accepted measured capture registration before building or approving walking evidence.",
    };
  }
  const spatial = await captureSpatialSnapshot(
    env.DB,
    organisationId,
    projectId,
    versionId,
  );
  const verified = await verifiedPhysicalNavigation(
    env,
    organisationId,
    projectId,
    versionId,
    spatial,
  );
  if (!verified) {
    return {
      ready: false,
      code: "walking_package_missing",
      message:
        "This version needs the exact approved structural collision, Recast navigation, Detour reachability report, and Rapier movement proof before preview.",
    };
  }
  return {
    ready: true,
    value: { spatial, collisionAsset: verified.collisionAsset, registration },
  };
}

async function approvedNavigationPreview(
  env: Env,
  organisationId: string,
  projectId: string,
  versionId: string,
): Promise<ApprovedNavigationPreview | null> {
  const qualification = await qualifyNavigationPreview(
    env,
    organisationId,
    projectId,
    versionId,
  );
  return qualification.ready ? qualification.value : null;
}

async function projectComparisonReadiness(
  env: Env,
  organisationId: string,
  projectId: string,
  versionRows: readonly unknown[],
  assetRows: readonly unknown[],
): Promise<ComparisonReadiness> {
  const versions = versionRows.flatMap((row) => {
    if (!row || typeof row !== "object") return [];
    const versionId = readStringProperty(row, "id");
    const versionNumber = Number(Reflect.get(row, "version_number"));
    return versionId && Number.isSafeInteger(versionNumber)
      ? [{ versionId, versionNumber }]
      : [];
  });
  const reviewedStructure = await env.DB.prepare(`
    SELECT DISTINCT version_id FROM floorplan_revisions
    WHERE organisation_id = ? AND project_id = ? AND status = 'approved'
    UNION
    SELECT decision.version_id
    FROM version_review_decisions decision
    WHERE decision.organisation_id = ? AND decision.project_id = ?
      AND decision.decision = 'approved'
      AND decision.id = (
        SELECT latest.id FROM version_review_decisions latest
        WHERE latest.organisation_id = decision.organisation_id
          AND latest.project_id = decision.project_id
          AND latest.version_id = decision.version_id
        ORDER BY latest.created_at DESC, latest.id DESC LIMIT 1
      )
      AND EXISTS (
        SELECT 1 FROM scene_entities entity
        WHERE entity.organisation_id = decision.organisation_id
          AND entity.project_id = decision.project_id
          AND entity.version_id = decision.version_id
          AND entity.status = 'active' AND entity.world_unit = 'metres'
          AND entity.kind IN ('floor', 'room', 'doorway')
          AND entity.geometry_json IS NOT NULL
      )
  `).bind(
    organisationId,
    projectId,
    organisationId,
    projectId,
  ).all<{ version_id: string }>();
  const reviewedStructureIds = new Set(reviewedStructure.results.map((row) => row.version_id));
  const assets = assetRows.flatMap((row) => {
    if (!row || typeof row !== "object") return [];
    const id = readStringProperty(row, "id");
    const versionId = readStringProperty(row, "version_id");
    const kind = readStringProperty(row, "kind");
    const format = readStringProperty(row, "format")?.toLowerCase();
    const objectKey = readStringProperty(row, "object_key");
    const sha256 = readStringProperty(row, "sha256")?.toLowerCase();
    const integrityStatus = readStringProperty(row, "integrity_status");
    return id && versionId && kind && format && objectKey
      ? [{ id, versionId, kind, format, objectKey, sha256, integrityStatus }]
      : [];
  });
  const evidence = await Promise.all(versions.map(async (version) => {
    const versionAssets = assets.filter((asset) => asset.versionId === version.versionId);
    const webCandidates = versionAssets.filter((asset) =>
      asset.kind === "web" && allowedWebFormats.has(asset.format) &&
      asset.integrityStatus === "verified" && Boolean(asset.sha256)
    );
    const pointCloudCandidates = versionAssets.filter((asset) =>
      ["source", "master", "pointcloud"].includes(asset.kind) && asset.format === "ply" &&
      asset.integrityStatus === "verified" && Boolean(asset.sha256)
    );
    const [navigation, verifiedWebScene, verifiedSourcePointCloud] = await Promise.all([
      approvedNavigationPreview(env, organisationId, projectId, version.versionId),
      r2HasAny(env.SPATIAL_ASSETS, webCandidates.map((asset) => asset.objectKey)),
      r2HasAny(env.SPATIAL_ASSETS, pointCloudCandidates.map((asset) => asset.objectKey)),
    ]);
    const registration = navigation?.registration ?? await qualifiedSceneRegistration(
      env.DB,
      organisationId,
      projectId,
      version.versionId,
    );
    return {
      ...version,
      verifiedWebScene,
      approvedNavigation: Boolean(navigation),
      reviewedMetricStructure: reviewedStructureIds.has(version.versionId),
      verifiedSourcePointCloud,
      registrationEvidence: Boolean(registration),
    };
  }));
  return comparisonReadiness(evidence);
}

async function r2HasAny(bucket: R2Bucket, objectKeys: readonly string[]): Promise<boolean> {
  for (const objectKey of objectKeys) {
    if (await bucket.head(objectKey)) return true;
  }
  return false;
}

async function verifiedPhysicalNavigation(
  env: Env,
  organisationId: string,
  projectId: string,
  versionId: string,
  spatial: Record<string, unknown>,
): Promise<{ collisionAsset: AssetRow; reportAsset: AssetRow; detourAsset: AssetRow } | null> {
  const artifact = navigationArtifactSchema.safeParse(
    Reflect.get(spatial, "navigationArtifact"),
  );
  const derivatives = navigationAssetsSchema.safeParse(
    Reflect.get(spatial, "navigationAssets"),
  );
  if (!artifact.success || !isPhysicalNavigationArtifact(artifact.data) || !derivatives.success) {
    return null;
  }

  const results = await env.DB.batch([
    env.DB.prepare(`
      SELECT * FROM assets
      WHERE id = ? AND organisation_id = ? AND project_id = ? AND version_id = ?
        AND kind = 'collision' AND format = 'glb' AND integrity_status = 'verified'
        AND sha256 = ? AND deleted_at IS NULL
    `).bind(
      artifact.data.source.assetId,
      organisationId,
      projectId,
      versionId,
      artifact.data.source.sha256,
    ),
    env.DB.prepare(`
      SELECT * FROM assets
      WHERE id = ? AND organisation_id = ? AND project_id = ? AND version_id = ?
        AND kind = 'report' AND format = 'json' AND integrity_status = 'verified'
        AND sha256 = ? AND size_bytes = ? AND deleted_at IS NULL
    `).bind(
      derivatives.data.artifact.assetId,
      organisationId,
      projectId,
      versionId,
      derivatives.data.artifact.sha256,
      derivatives.data.artifact.sizeBytes,
    ),
    env.DB.prepare(`
      SELECT * FROM assets
      WHERE id = ? AND organisation_id = ? AND project_id = ? AND version_id = ?
        AND kind = 'navmesh' AND format = 'bin' AND integrity_status = 'verified'
        AND sha256 = ? AND size_bytes = ? AND deleted_at IS NULL
    `).bind(
      derivatives.data.detour.assetId,
      organisationId,
      projectId,
      versionId,
      derivatives.data.detour.sha256,
      derivatives.data.detour.sizeBytes,
    ),
  ]);
  const collisionAsset = requiredBatchResult(results, 0).results[0] as
    | AssetRow
    | undefined;
  const reportAsset = requiredBatchResult(results, 1).results[0] as
    | AssetRow
    | undefined;
  const navmeshAsset = requiredBatchResult(results, 2).results[0] as
    | AssetRow
    | undefined;
  if (!collisionAsset || !reportAsset || !navmeshAsset) return null;

  const [collisionObject, reportObject, navmeshObject] = await Promise.all([
    env.SPATIAL_ASSETS.head(collisionAsset.object_key),
    env.SPATIAL_ASSETS.head(reportAsset.object_key),
    env.SPATIAL_ASSETS.head(navmeshAsset.object_key),
  ]);
  if (
    collisionObject?.size !== collisionAsset.size_bytes ||
    reportObject?.size !== reportAsset.size_bytes ||
    navmeshObject?.size !== navmeshAsset.size_bytes
  ) return null;

  return { collisionAsset, reportAsset, detourAsset: navmeshAsset };
}

function isPhysicalNavigationArtifact(value: unknown): boolean {
  if (!value || typeof value !== "object") return false;
  return ["spatial-navigation-v7", "spatial-navigation-v8", "spatial-navigation-v9"].includes(
    String(Reflect.get(value, "schemaVersion")),
  );
}

function parseSpatialSnapshot(value: string): Record<string, unknown> | null {
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    return null;
  }
  if (!parsed || typeof parsed !== "object") return null;
  if (Reflect.get(parsed, "schemaVersion") !== "spatial-runtime-v5") return null;
  if (
    !Array.isArray(Reflect.get(parsed, "entities")) ||
    !Array.isArray(Reflect.get(parsed, "routes")) ||
    !Array.isArray(Reflect.get(parsed, "routeStops")) ||
    !Reflect.get(parsed, "navigationMesh")
  ) return null;
  return parsed as Record<string, unknown>;
}

function approvedNavigationArtifact(
  rows: unknown[],
  expectedAuthoringHash?: string,
): Record<string, unknown> | null {
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    if (Reflect.has(row, "status") && Reflect.get(row, "status") !== "APPROVED") continue;
    if (
      expectedAuthoringHash &&
      Reflect.get(row, "authoring_hash") !== expectedAuthoringHash
    ) continue;
    const artifactJson = Reflect.get(row, "artifact_json");
    if (typeof artifactJson !== "string") continue;
    try {
      const parsed = navigationArtifactSchema.safeParse(JSON.parse(artifactJson));
      if (parsed.success) return parsed.data;
    } catch {
      // A malformed approved build must not enter a release or live runtime.
    }
  }
  return null;
}

function approvedNavigationBuild(
  rows: unknown[],
  expectedAuthoringHash: string,
): {
  artifact: ReturnType<typeof navigationArtifactSchema.parse>;
  assets: ReturnType<typeof navigationAssetsSchema.parse>;
} | null {
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    if (Reflect.get(row, "authoring_hash") !== expectedAuthoringHash) continue;
    const artifactJson = Reflect.get(row, "artifact_json");
    if (typeof artifactJson !== "string") continue;
    try {
      const artifact = navigationArtifactSchema.safeParse(JSON.parse(artifactJson));
      if (!artifact.success || artifact.data.source.authoringHash !== expectedAuthoringHash) continue;
      const assets = navigationAssetsSchema.safeParse({
        buildId: Reflect.get(row, "id"),
        authoringHash: expectedAuthoringHash,
        artifact: {
          assetId: Reflect.get(row, "report_asset_id"),
          format: Reflect.get(row, "report_format"),
          sha256: Reflect.get(row, "report_sha256"),
          sizeBytes: Reflect.get(row, "report_size_bytes"),
        },
        detour: {
          assetId: Reflect.get(row, "navmesh_asset_id"),
          format: Reflect.get(row, "navmesh_format"),
          sha256: Reflect.get(row, "navmesh_sha256"),
          sizeBytes: Reflect.get(row, "navmesh_size_bytes"),
        },
      });
      if (assets.success) return { artifact: artifact.data, assets: assets.data };
    } catch {
      // Invalid derivative evidence cannot enter a release snapshot.
    }
  }
  return null;
}

export async function navigationAuthoringHash(
  profileRow: unknown,
  entityRows: unknown[],
  obstacleRows: unknown[],
  routeStopRows: unknown[] = [],
  traversalRows: unknown[] = [],
  floorplanReceipt: Record<string, unknown> | null = null,
): Promise<string> {
  const destinations = entityRows
    .flatMap(navigationDestinationFromEntity)
    .sort((left, right) => left.id.localeCompare(right.id));
  const obstacles = obstacleRows
    .flatMap(navigationObstacleBoxFromRow)
    .sort((left, right) => left.id.localeCompare(right.id));
  const walkableGeometry = entityRows
    .flatMap(canonicalWalkableAuthoringEntity)
    .sort((left, right) => left.id.localeCompare(right.id));
  const routeStops = routeStopRows
    .flatMap(canonicalNavigationRouteStop)
    .sort((left, right) => left.id.localeCompare(right.id));
  const traversals = traversalRows
    .flatMap(canonicalNavigationTraversal)
    .sort((left, right) => left.id.localeCompare(right.id));
  const authoring: Record<string, unknown> = {
    profile: navigationProfileFromRow(profileRow),
    destinations,
    obstacles,
    walkableGeometry,
    routeStops,
  };
  // A never-used registry preserves established v7 hashes. Once any traversal
  // record exists, including an archived one, its state remains hash-bound so
  // archiving the last link cannot resurrect an older approval.
  if (traversalRows.length) {
    authoring.traversalRegistry = {
      schemaVersion: "authored-traversal-registry-v1",
      records: traversals,
    };
  }
  if (traversals.length !== traversalRows.length) {
    authoring.invalidTraversals = traversalRows.map((row) => ({
      id: row && typeof row === "object" ? Reflect.get(row, "id") ?? null : null,
      invalid: true,
    }));
  }
  if (floorplanReceipt) {
    authoring.floorplanReceipt = floorplanReceipt;
  }
  return sha256Hex(JSON.stringify(authoring));
}

export async function currentNavigationAuthoringState(
  database: D1Database,
  organisationId: string,
  projectId: string,
  versionId: string,
  floorplanReceiptOverride: Record<string, unknown> | null = null,
): Promise<{
  authoringHash: string;
  offMeshConnections: ReturnType<typeof navigationTraversalConnectionFromRow>;
  profile: ReturnType<typeof navigationProfileFromRow>;
}> {
  const results = await database.batch([
    database.prepare(`
      SELECT world_unit, agent_radius, agent_height, eye_height, max_step_metres,
        max_slope_degrees, max_speed, max_acceleration
      FROM scene_navigation_profiles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT id, kind, position_json, geometry_json
      FROM scene_entities
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND status = 'active' AND kind IN ('room', 'floor', 'doorway')
      ORDER BY kind DESC, sort_order, label
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT id, label, bounds_json
      FROM scene_navigation_obstacles
      WHERE organisation_id = ? AND project_id = ? AND version_id = ?
        AND status = 'active'
      ORDER BY label, created_at
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT rs.route_id, rs.entity_id, rs.sequence_number, rs.camera_pose_json
      FROM scene_route_stops rs
      JOIN scene_routes r ON r.id = rs.route_id
      WHERE r.organisation_id = ? AND r.project_id = ? AND r.version_id = ?
        AND r.status = 'active'
      ORDER BY rs.route_id, rs.sequence_number
    `).bind(organisationId, projectId, versionId),
    database.prepare(`${NAVIGATION_TRAVERSAL_EVIDENCE_SELECT}
      WHERE t.organisation_id = ? AND t.project_id = ? AND t.version_id = ?
      ORDER BY t.id
    `).bind(organisationId, projectId, versionId),
    database.prepare(`
      SELECT revision.id, revision.plan_hash, revision.collision_asset_id,
        revision.collision_sha256, revision.navigation_receipt_version,
        revision.capture_agreement_json,
        collision.sha256 AS current_collision_sha256,
        collision.integrity_status AS collision_integrity_status,
        collision.deleted_at AS collision_deleted_at
      FROM floorplan_revisions revision
      LEFT JOIN assets collision ON collision.id = revision.collision_asset_id
      WHERE revision.organisation_id = ? AND revision.project_id = ?
        AND revision.version_id = ? AND revision.status = 'approved'
      ORDER BY revision.revision_number DESC, revision.created_at DESC LIMIT 1
    `).bind(organisationId, projectId, versionId),
  ]);
  const profileRow = requiredBatchResult(results, 0).results[0] ?? {
    world_unit: "metres",
    agent_radius: 0.25,
    agent_height: 1.7,
    eye_height: 1.6,
    max_step_metres: 0.2,
    max_slope_degrees: 45,
    max_speed: 1.6,
    max_acceleration: 8,
  };
  const traversalRows = requiredBatchResult(results, 4).results;
  const activeTraversalRows = traversalRows.filter(
    (row) => row && typeof row === "object" && Reflect.get(row, "status") === "active",
  );
  const profile = navigationProfileFromRow(profileRow);
  const offMeshConnections = traversalRows.flatMap((row, index) =>
    navigationTraversalConnectionFromRow(row, profile.agentRadius, index)
  );
  if (offMeshConnections.length !== activeTraversalRows.length) {
    throw new Error(
      `Active authored traversal records are invalid: stored=${activeTraversalRows.length}, usable=${offMeshConnections.length}`,
    );
  }
  const floorplanReceipt = floorplanReceiptOverride ??
    floorplanNavigationReceipt(requiredBatchResult(results, 5).results[0]);
  if (isInvalidFloorplanNavigationReceipt(floorplanReceipt)) {
    throw new Error(
      "The approved floor-plan collision receipt is missing or no longer matches its verified immutable asset",
    );
  }
  return {
    authoringHash: await navigationAuthoringHash(
      profileRow,
      requiredBatchResult(results, 1).results,
      requiredBatchResult(results, 2).results,
      requiredBatchResult(results, 3).results,
      traversalRows,
      floorplanReceipt,
    ),
    offMeshConnections,
    profile,
  };
}

// Distils a revision's frozen capture-agreement blob into the receipt shape.
// The exact same fragment is appended at review time (when the frozen
// authoring hash is computed) and here (when the current hash is recomputed),
// so the two hashes can only agree when the frozen resolutions still stand.
// Returns "invalid" for an unreadable blob or an unresolved crossing finding.
export function captureAgreementReceiptFragment(
  captureAgreementJson: string | null,
): { captureAgreement?: Record<string, unknown> } | "invalid" {
  const frozen = parseFrozenCaptureAgreement(captureAgreementJson);
  if (frozen === undefined) return {};
  if (frozen === null) return "invalid";
  if (unresolvedCaptureAgreementCrossings(frozen.report, frozen.resolutions).unresolved.length) {
    return "invalid";
  }
  const findings = frozen.report?.findings ?? [];
  return {
    captureAgreement: {
      schemaVersion: "shell-capture-agreement-receipt-v1",
      findingCount: findings.length,
      crossingCount: findings
        .filter((finding) => finding.kind === "barrier_crosses_open_capture").length,
      resolutions: frozen.resolutions,
    },
  };
}

function floorplanNavigationReceipt(row: unknown): Record<string, unknown> | null {
  if (!row || typeof row !== "object") return null;
  const floorplanRevisionId = readStringProperty(row, "id");
  const planHash = readStringProperty(row, "plan_hash")?.toLowerCase();
  const collisionAssetId = readStringProperty(row, "collision_asset_id");
  const collisionSha256 = readStringProperty(row, "collision_sha256")?.toLowerCase();
  const receiptVersion = readStringProperty(row, "navigation_receipt_version");
  if (!receiptVersion && !collisionAssetId && !collisionSha256) return null;
  const currentCollisionSha256 = readStringProperty(row, "current_collision_sha256")
    ?.toLowerCase();
  const collisionIntegrityStatus = readStringProperty(row, "collision_integrity_status");
  const collisionDeletedAt = Reflect.get(row, "collision_deleted_at");
  const agreementFragment = captureAgreementReceiptFragment(
    readStringProperty(row, "capture_agreement_json") ?? null,
  );
  if (
    receiptVersion === "floorplan-navigation-receipt-v1" &&
    floorplanRevisionId && planHash && /^[a-f0-9]{64}$/.test(planHash) &&
    collisionAssetId && collisionSha256 && /^[a-f0-9]{64}$/.test(collisionSha256) &&
    currentCollisionSha256 === collisionSha256 &&
    collisionIntegrityStatus === "verified" && collisionDeletedAt === null &&
    agreementFragment !== "invalid"
  ) {
    return {
      schemaVersion: "reviewed-floorplan-navigation-receipt-v1",
      floorplanRevisionId,
      planHash,
      collisionAssetId,
      collisionSha256,
      ...agreementFragment,
    };
  }
  return {
    schemaVersion: "invalid-reviewed-floorplan-navigation-receipt-v1",
    receiptVersion: receiptVersion ?? null,
    floorplanRevisionId: floorplanRevisionId ?? null,
    planHash: planHash ?? null,
    collisionAssetId: collisionAssetId ?? null,
    collisionSha256: collisionSha256 ?? null,
    currentCollisionSha256: currentCollisionSha256 ?? null,
    collisionIntegrityStatus: collisionIntegrityStatus ?? null,
    collisionDeleted: collisionDeletedAt !== null,
    captureAgreementInvalid: agreementFragment === "invalid",
  };
}

function isInvalidFloorplanNavigationReceipt(
  receipt: Record<string, unknown> | null,
): boolean {
  return receipt?.schemaVersion === "invalid-reviewed-floorplan-navigation-receipt-v1";
}

function canonicalNavigationTraversal(row: unknown): Array<{
  id: string;
  traversalKind: "elevator" | "ladder" | "moving_platform";
  label: string;
  path: Array<[number, number, number]>;
  bidirectional: boolean;
  speedUnitsPerSecond: number;
  reviewedPurpose: string;
  evidenceAssetId: string;
  evidenceSha256: string;
  evidenceManifestId: string;
  evidenceManifestSha256: string;
  evidenceAdapter: string;
  evidenceManifestReviewGeneration: number;
  evidenceRegistrationSha256: string;
  evidenceSourceToWorld: CaptureSceneRegistration["sourceToWorld"];
  evidenceSourcePath: Vector3Tuple[];
  status: "active" | "archived";
}> {
  if (!row || typeof row !== "object") return [];
  const id = readStringProperty(row, "id");
  const traversalKind = readStringProperty(row, "traversal_kind");
  const label = readStringProperty(row, "label");
  const reviewedPurpose = readStringProperty(row, "reviewed_purpose");
  const evidenceAssetId = readStringProperty(row, "evidence_asset_id");
  const evidenceSha256 = readStringProperty(row, "evidence_sha256")?.toLowerCase();
  const evidenceManifestId = readStringProperty(row, "evidence_manifest_id");
  const evidenceManifestSha256 = readStringProperty(row, "evidence_manifest_sha256")
    ?.toLowerCase();
  const evidenceAdapter = readStringProperty(row, "evidence_adapter");
  const evidenceManifestReviewGeneration = Number(
    Reflect.get(row, "evidence_manifest_review_generation"),
  );
  const evidenceRegistrationSha256 = readStringProperty(
    row,
    "evidence_registration_sha256",
  )?.toLowerCase();
  const evidenceSourceToWorld = canonicalSourceToWorldTransform(parseStoredObject(
    readStringProperty(row, "evidence_source_to_world_json") ?? "null",
  ));
  const evidenceSourcePath = canonicalTraversalSourcePath(
    readStringProperty(row, "evidence_source_path_json") ?? null,
  );
  const status = readStringProperty(row, "status");
  const evidenceJoined = Reflect.has(row, "current_evidence_sha256");
  const manifestJoined = Reflect.has(row, "current_evidence_manifest_sha256");
  const currentEvidenceSha256 = readStringProperty(row, "current_evidence_sha256")
    ?.toLowerCase();
  const evidenceIntegrityStatus = readStringProperty(row, "evidence_integrity_status");
  const evidenceDeletedAt = Reflect.get(row, "evidence_deleted_at");
  const currentEvidenceManifestSha256 = readStringProperty(
    row,
    "current_evidence_manifest_sha256",
  )?.toLowerCase();
  const currentEvidenceAdapter = readStringProperty(row, "current_evidence_adapter");
  const evidenceManifestStatus = readStringProperty(row, "evidence_manifest_status");
  const evidenceManifestResult = readStringProperty(row, "evidence_manifest_result");
  const evidenceManifestReviewDecision = readStringProperty(
    row,
    "evidence_manifest_review_decision",
  );
  const currentEvidenceManifestReviewGeneration = Number(
    Reflect.get(row, "current_evidence_manifest_review_generation"),
  );
  const currentEvidenceRegistrationSha256 = readStringProperty(
    row,
    "current_evidence_registration_sha256",
  )?.toLowerCase();
  const currentEvidenceSourceToWorld = canonicalSourceToWorldTransform(parseStoredObject(
    readStringProperty(row, "current_evidence_source_to_world_json") ?? "null",
  ));
  const speedUnitsPerSecond = Number(Reflect.get(row, "speed_units_per_second"));
  let path: unknown;
  try {
    path = JSON.parse(String(Reflect.get(row, "path_json") ?? ""));
  } catch {
    return [];
  }
  if (
    !id || !label || !reviewedPurpose || !evidenceAssetId || !evidenceManifestId ||
    !evidenceSha256 || !/^[a-f0-9]{64}$/i.test(evidenceSha256) ||
    !evidenceManifestSha256 || !/^[a-f0-9]{64}$/i.test(evidenceManifestSha256) ||
    !evidenceAdapter || !Number.isSafeInteger(evidenceManifestReviewGeneration) ||
    evidenceManifestReviewGeneration < 1 ||
    !evidenceRegistrationSha256 || !/^[a-f0-9]{64}$/i.test(evidenceRegistrationSha256) ||
    !evidenceSourceToWorld || evidenceSourceToWorld.worldUnit !== "metres" ||
    !evidenceSourcePath ||
    (evidenceJoined && (
      currentEvidenceSha256 !== evidenceSha256 ||
      evidenceIntegrityStatus !== "verified" ||
      evidenceDeletedAt !== null
    )) ||
    (manifestJoined && (
      currentEvidenceManifestSha256 !== evidenceManifestSha256 ||
      currentEvidenceAdapter !== evidenceAdapter ||
      evidenceManifestStatus !== "reviewed" ||
      evidenceManifestResult === "blocked" ||
      evidenceManifestReviewDecision !== "accepted" ||
      currentEvidenceManifestReviewGeneration !== evidenceManifestReviewGeneration
      || currentEvidenceRegistrationSha256 !== evidenceRegistrationSha256
      || JSON.stringify(currentEvidenceSourceToWorld) !== JSON.stringify(evidenceSourceToWorld)
    )) ||
    !["active", "archived"].includes(status ?? "") ||
    !["elevator", "ladder", "moving_platform"].includes(traversalKind ?? "") ||
    !Array.isArray(path) || path.length < 2 || !path.every(finitePoint3) ||
    JSON.stringify(path) !== JSON.stringify(evidenceSourcePath.map((point) =>
      transformSourcePoint(point, evidenceSourceToWorld)
    )) ||
    !Number.isFinite(speedUnitsPerSecond) || speedUnitsPerSecond <= 0
  ) return [];
  return [{
    id,
    traversalKind: traversalKind as "elevator" | "ladder" | "moving_platform",
    label,
    path: path as Array<[number, number, number]>,
    bidirectional: Number(Reflect.get(row, "bidirectional")) === 1,
    speedUnitsPerSecond,
    reviewedPurpose,
    evidenceAssetId,
    evidenceSha256,
    evidenceManifestId,
    evidenceManifestSha256,
    evidenceAdapter,
    evidenceManifestReviewGeneration,
    evidenceRegistrationSha256,
    evidenceSourceToWorld: {
      ...evidenceSourceToWorld,
      worldUnit: "metres",
    },
    evidenceSourcePath,
    status: status as "active" | "archived",
  }];
}

function navigationTraversalConnectionFromRow(
  row: unknown,
  agentRadius: number,
  index: number,
): Array<{
  id: string;
  traversalKind: "elevator" | "ladder" | "moving_platform";
  label: string;
  startPosition: [number, number, number];
  controlPoints: Array<[number, number, number]>;
  endPosition: [number, number, number];
  radius: number;
  bidirectional: boolean;
  speedUnitsPerSecond: number;
  area: number;
  flags: number;
  userId: number;
  reviewedPurpose: string;
  evidenceReceipt: {
    assetId: string;
    sha256: string;
    manifestId: string;
    manifestSha256: string;
    adapter: string;
    reviewGeneration: number;
    registrationSha256: string;
    sourceToWorld: CaptureSceneRegistration["sourceToWorld"];
    sourcePath: Vector3Tuple[];
  };
}> {
  const parsed = canonicalNavigationTraversal(row)[0];
  if (!parsed || parsed.status !== "active") return [];
  return [{
    id: parsed.id,
    traversalKind: parsed.traversalKind,
    label: parsed.label,
    startPosition: parsed.path[0]!,
    controlPoints: parsed.path.slice(1, -1),
    endPosition: parsed.path.at(-1)!,
    radius: agentRadius,
    bidirectional: parsed.bidirectional,
    speedUnitsPerSecond: parsed.speedUnitsPerSecond,
    area: 0,
    flags: 1,
    userId: index + 1,
    reviewedPurpose: parsed.reviewedPurpose,
    evidenceReceipt: {
      assetId: parsed.evidenceAssetId,
      sha256: parsed.evidenceSha256,
      manifestId: parsed.evidenceManifestId,
      manifestSha256: parsed.evidenceManifestSha256,
      adapter: parsed.evidenceAdapter,
      reviewGeneration: parsed.evidenceManifestReviewGeneration,
      registrationSha256: parsed.evidenceRegistrationSha256,
      sourceToWorld: parsed.evidenceSourceToWorld,
      sourcePath: parsed.evidenceSourcePath,
    },
  }];
}

function canonicalTraversalSourcePath(value: string | null): Vector3Tuple[] | null {
  if (!value) return null;
  let parsed: unknown;
  try {
    parsed = JSON.parse(value);
  } catch {
    return null;
  }
  if (
    !Array.isArray(parsed) || parsed.length < 2 || !parsed.every(finitePoint3) ||
    parsed.some((point: unknown, index: number) => index > 0 &&
      Array.isArray(point) && point.every((coordinate: unknown, axis: number) =>
        coordinate === (parsed[index - 1] as unknown[])[axis]
      ))
  ) return null;
  return parsed as Vector3Tuple[];
}

function buildSpatialRuntime(
  rows: unknown[],
  obstacleRows: unknown[] = [],
  profileRow: unknown = null,
): {
  collisionProxy: { version: "box-union-v1"; boxes: RuntimeBox[] };
  navigationMesh: {
    version: "room-box-triangles-v1" | "authored-polygon-triangles-v2";
    vertices: Array<[number, number, number]>;
    indices: number[];
    sourceEntityIds: string[];
  };
  obstacleProxy: {
    version: "authored-obstacle-boxes-v1";
    boxes: RuntimeObstacleBox[];
  };
  navigationProfile: {
    worldUnit: "metres" | "scene_units";
    agentRadius: number;
    agentHeight: number;
    eyeHeight: number;
    maxStepMetres: number;
    maxSlopeDegrees: number;
    maxSpeed: number;
    maxAcceleration: number;
  };
} {
  const regions: Array<{
    entityId: string;
    kind: "floor" | "room" | "doorway";
    label: string;
    box: RuntimeBox;
    polygon: Array<[number, number, number]> | null;
  }> = [];
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    const kind = Reflect.get(row, "kind");
    if (kind !== "floor" && kind !== "room" && kind !== "doorway") continue;
    const geometryJson = Reflect.get(row, "geometry_json");
    if (typeof geometryJson !== "string") continue;
    let geometry: unknown;
    try {
      geometry = JSON.parse(geometryJson);
    } catch {
      continue;
    }
    if (!geometry || typeof geometry !== "object") continue;
    const points = Reflect.get(geometry, "points");
    if (!Array.isArray(points)) continue;
    const type = Reflect.get(geometry, "type");
    let polygon: Array<[number, number, number]> | null = null;
    let first: [number, number, number] | null = null;
    let second: [number, number, number] | null = null;
    if (type === "box" && points.length === 2) {
      first = finitePoint3(points[0]);
      second = finitePoint3(points[1]);
    } else if (type === "polygon" && points.length >= 3) {
      const parsed = points.map(finitePoint3);
      if (parsed.some((point) => !point)) continue;
      polygon = parsed as Array<[number, number, number]>;
      first = [
        Math.min(...polygon.map((point) => point[0])),
        Math.min(...polygon.map((point) => point[1])),
        Math.min(...polygon.map((point) => point[2])),
      ];
      second = [
        Math.max(...polygon.map((point) => point[0])),
        Math.max(...polygon.map((point) => point[1])),
        Math.max(...polygon.map((point) => point[2])),
      ];
    }
    if (!first || !second) continue;
    const min: [number, number, number] = [
      Math.min(first[0], second[0]),
      Math.min(first[1], second[1]),
      Math.min(first[2], second[2]),
    ];
    const max: [number, number, number] = [
      Math.max(first[0], second[0]),
      Math.max(first[1], second[1]),
      Math.max(first[2], second[2]),
    ];
    if (max[0] - min[0] < 0.05 || max[2] - min[2] < 0.05) continue;
    const entityId = String(Reflect.get(row, "id") ?? "");
    const label = String(Reflect.get(row, "label") ?? "Walkable region");
    regions.push({
      entityId,
      kind,
      label,
      box: { entityId, label, min, max },
      polygon,
    });
  }

  const primaryWalkable = regions.some((region) => region.kind === "room")
    ? regions.filter((region) => region.kind === "room")
    : regions.filter((region) => region.kind === "floor");
  const walkable = [
    ...primaryWalkable,
    ...regions.filter((region) => region.kind === "doorway"),
  ];
  const boxes = walkable.map((region) => region.box);
  const vertices: Array<[number, number, number]> = [];
  const indices: number[] = [];
  for (const region of walkable) {
    const offset = vertices.length;
    if (region.polygon) {
      const floorY = region.polygon.reduce((sum, point) => sum + point[1], 0) /
        region.polygon.length + 0.02;
      vertices.push(...region.polygon.map((point) =>
        [point[0], floorY, point[2]] as [number, number, number]));
      indices.push(...triangulateWalkablePolygon(region.polygon).map((index) => offset + index));
    } else {
      const box = region.box;
      const floorY = box.min[1] + 0.02;
      vertices.push(
        [box.min[0], floorY, box.min[2]],
        [box.max[0], floorY, box.min[2]],
        [box.max[0], floorY, box.max[2]],
        [box.min[0], floorY, box.max[2]],
      );
      indices.push(offset, offset + 1, offset + 2, offset, offset + 2, offset + 3);
    }
  }
  const obstacleBoxes = obstacleRows.flatMap((row): RuntimeObstacleBox[] => {
    if (!row || typeof row !== "object") return [];
    const boundsJson = Reflect.get(row, "bounds_json");
    if (typeof boundsJson !== "string") return [];
    let geometry: unknown;
    try {
      geometry = JSON.parse(boundsJson);
    } catch {
      return [];
    }
    if (!geometry || typeof geometry !== "object" || Reflect.get(geometry, "type") !== "box") {
      return [];
    }
    const points = Reflect.get(geometry, "points");
    if (!Array.isArray(points) || points.length !== 2) return [];
    const first = finitePoint3(points[0]);
    const second = finitePoint3(points[1]);
    if (!first || !second) return [];
    return [{
      entityId: String(Reflect.get(row, "id") ?? ""),
      label: String(Reflect.get(row, "label") ?? "Obstacle"),
      min: [
        Math.min(first[0], second[0]),
        Math.min(first[1], second[1]),
        Math.min(first[2], second[2]),
      ],
      max: [
        Math.max(first[0], second[0]),
        Math.max(first[1], second[1]),
        Math.max(first[2], second[2]),
      ],
    }];
  });
  const navigationProfile = navigationProfileFromRow(profileRow);
  return {
    collisionProxy: { version: "box-union-v1", boxes },
    navigationMesh: {
      version: walkable.some((region) => region.polygon)
        ? "authored-polygon-triangles-v2"
        : "room-box-triangles-v1",
      vertices,
      indices,
      sourceEntityIds: walkable.map((region) => region.entityId),
    },
    obstacleProxy: {
      version: "authored-obstacle-boxes-v1",
      boxes: obstacleBoxes,
    },
    navigationProfile,
  };
}

function navigationProfileFromRow(
  row: unknown,
): typeof defaultNavigationProfile | {
  worldUnit: "metres" | "scene_units";
  agentRadius: number;
  agentHeight: number;
  eyeHeight: number;
  maxStepMetres: number;
  maxSlopeDegrees: number;
  maxSpeed: number;
  maxAcceleration: number;
} {
  if (!row || typeof row !== "object") return defaultNavigationProfile;
  const worldUnit = parseWorldUnit(Reflect.get(row, "world_unit"));
  const agentRadius = Number(Reflect.get(row, "agent_radius"));
  const agentHeight = Number(Reflect.get(row, "agent_height"));
  const eyeHeight = Number(Reflect.get(row, "eye_height"));
  const maxStepMetres = Number(Reflect.get(row, "max_step_metres"));
  const maxSlopeDegrees = Number(Reflect.get(row, "max_slope_degrees"));
  const maxSpeed = Number(Reflect.get(row, "max_speed"));
  const maxAcceleration = Number(Reflect.get(row, "max_acceleration"));
  if (
    !Number.isFinite(agentRadius) ||
    !Number.isFinite(agentHeight) ||
    !Number.isFinite(eyeHeight) ||
    !Number.isFinite(maxStepMetres) ||
    !Number.isFinite(maxSlopeDegrees) ||
    !Number.isFinite(maxSpeed) ||
    !Number.isFinite(maxAcceleration)
  ) return defaultNavigationProfile;
  return {
    worldUnit,
    agentRadius,
    agentHeight,
    eyeHeight,
    maxStepMetres,
    maxSlopeDegrees,
    maxSpeed,
    maxAcceleration,
  };
}

export function triangulateWalkablePolygon(points: Array<[number, number, number]>): number[] {
  const ring = points
    .map((point, index) => ({ point, index }))
    .filter((entry, index, entries) =>
      index === 0 || !sameWalkablePoint(entry.point, entries[index - 1]!.point));
  if (
    ring.length > 1 &&
    sameWalkablePoint(ring[0]!.point, ring[ring.length - 1]!.point)
  ) {
    ring.pop();
  }
  if (ring.length < 3) return [];
  const rings = splitWalkableRings(ring);
  const sourceWinding = Math.sign(walkableRingArea(ring));
  if (!sourceWinding) return [];
  const outerRings = rings
    .filter((candidate) => walkableRingArea(candidate) * sourceWinding > 1e-9)
    .sort((left, right) =>
      Math.abs(walkableRingArea(left)) - Math.abs(walkableRingArea(right)));
  const holeRings = rings.filter((candidate) =>
    walkableRingArea(candidate) * sourceWinding < -1e-9);
  const holesByOuter = new Map(outerRings.map((outer) => [outer, [] as typeof holeRings]));
  for (const hole of holeRings) {
    const owner = outerRings.find((outer) =>
      walkablePointInRing(hole[0]!.point, outer));
    if (owner) holesByOuter.get(owner)!.push(hole);
  }
  return outerRings.flatMap((outer) =>
    triangulateSimpleWalkableRing(outer, holesByOuter.get(outer) ?? []));
}

function splitWalkableRings(
  ring: Array<{ point: [number, number, number]; index: number }>,
): Array<Array<{ point: [number, number, number]; index: number }>> {
  for (let first = 0; first < ring.length; first += 1) {
    for (let second = first + 2; second < ring.length; second += 1) {
      if (first === 0 && second === ring.length - 1) continue;
      if (!sameWalkablePoint(ring[first]!.point, ring[second]!.point)) continue;
      const left = ring.slice(first, second);
      const right = [...ring.slice(second), ...ring.slice(0, first)];
      if (left.length < 3 || right.length < 3) continue;
      return [
        ...splitWalkableRings(left),
        ...splitWalkableRings(right),
      ];
    }
  }
  return [ring];
}

function triangulateSimpleWalkableRing(
  outer: Array<{ point: [number, number, number]; index: number }>,
  holes: Array<Array<{ point: [number, number, number]; index: number }>>,
): number[] {
  const flattened = [outer, ...holes].flat();
  const holeIndices: number[] = [];
  let offset = outer.length;
  for (const hole of holes) {
    holeIndices.push(offset);
    offset += hole.length;
  }
  const data = flattened.flatMap(({ point }) => [point[0], point[2]]);
  return Earcut.triangulate(data, holeIndices, 2).map((index) =>
    flattened[index]!.index);
}

function walkableRingArea(
  ring: Array<{ point: [number, number, number] }>,
): number {
  return ring.reduce((sum, entry, index) => {
    const next = ring[(index + 1) % ring.length]!;
    return sum + entry.point[0] * next.point[2] - next.point[0] * entry.point[2];
  }, 0) / 2;
}

function sameWalkablePoint(
  first: [number, number, number],
  second: [number, number, number],
): boolean {
  return Math.abs(first[0] - second[0]) <= 1e-9 &&
    Math.abs(first[2] - second[2]) <= 1e-9;
}

function walkablePointInRing(
  point: [number, number, number],
  ring: Array<{ point: [number, number, number] }>,
): boolean {
  let inside = false;
  for (let index = 0; index < ring.length; index += 1) {
    const first = ring[index]!.point;
    const second = ring[(index + 1) % ring.length]!.point;
    const cross = (point[0] - first[0]) * (second[2] - first[2]) -
      (point[2] - first[2]) * (second[0] - first[0]);
    if (
      Math.abs(cross) <= 1e-9 &&
      point[0] >= Math.min(first[0], second[0]) - 1e-9 &&
      point[0] <= Math.max(first[0], second[0]) + 1e-9 &&
      point[2] >= Math.min(first[2], second[2]) - 1e-9 &&
      point[2] <= Math.max(first[2], second[2]) + 1e-9
    ) return true;
    if (
      (first[2] > point[2]) !== (second[2] > point[2]) &&
      point[0] < (second[0] - first[0]) * (point[2] - first[2]) /
        (second[2] - first[2]) + first[0]
    ) {
      inside = !inside;
    }
  }
  return inside;
}

function finitePoint3(value: unknown): [number, number, number] | null {
  if (!Array.isArray(value) || value.length !== 3) return null;
  const point = value.map(Number);
  if (point.some((coordinate) => !Number.isFinite(coordinate))) return null;
  return point as [number, number, number];
}

function navigationDestinationFromEntity(row: unknown): Array<{
  id: string;
  position: [number, number, number];
}> {
  if (!row || typeof row !== "object") return [];
  const kind = Reflect.get(row, "kind");
  if (typeof kind === "string" && kind !== "room" && kind !== "floor") return [];
  const id = String(Reflect.get(row, "id") ?? "");
  if (!id) return [];
  const position = navigationPositionFromRow(row);
  return position ? [{ id, position }] : [];
}

function navigationDestinationFromRouteStop(row: unknown, eyeHeight: number): Array<{
  id: string;
  position: [number, number, number];
}> {
  if (!row || typeof row !== "object") return [];
  const routeId = String(Reflect.get(row, "route_id") ?? "");
  const entityId = String(Reflect.get(row, "entity_id") ?? "");
  const sequence = Number(Reflect.get(row, "sequence_number"));
  if (!routeId || !entityId || !Number.isSafeInteger(sequence) || sequence < 0) return [];
  const cameraPoseJson = Reflect.get(row, "camera_pose_json");
  if (typeof cameraPoseJson === "string") {
    try {
      const cameraPosition = finitePoint3(Reflect.get(JSON.parse(cameraPoseJson), "position"));
      if (cameraPosition) {
        return [{
          id: `route:${routeId}:${sequence}:${entityId}`,
          position: [cameraPosition[0], cameraPosition[1] - eyeHeight, cameraPosition[2]],
        }];
      }
    } catch {
      // Fall back to the referenced entity position.
    }
  }
  const position = navigationPositionFromRow(row);
  return position ? [{ id: `route:${routeId}:${sequence}:${entityId}`, position }] : [];
}

function navigationPositionFromRow(row: object): [number, number, number] | null {
  const positionJson = Reflect.get(row, "position_json");
  if (typeof positionJson === "string") {
    try {
      const position = finitePoint3(JSON.parse(positionJson));
      if (position) return position;
    } catch {
      // Fall through to the geometry centroid.
    }
  }
  const geometryJson = Reflect.get(row, "geometry_json");
  if (typeof geometryJson !== "string") return null;
  try {
    const geometry = JSON.parse(geometryJson) as { type?: unknown; points?: unknown[] };
    const points = Array.isArray(geometry.points)
      ? geometry.points.map(finitePoint3).filter((point): point is [number, number, number] => Boolean(point))
      : [];
    if (!points.length) return null;
    if (geometry.type === "polygon" && points.length >= 3) {
      const interior = interiorPointForWalkablePolygon(points);
      if (interior) return interior;
    }
    return [0, 1, 2].map((axis) =>
        points.reduce((sum, point) => sum + point[axis]!, 0) / points.length
      ) as [number, number, number];
  } catch {
    return null;
  }
}

export function interiorPointForWalkablePolygon(
  points: Array<[number, number, number]>,
): [number, number, number] | null {
  const indices = triangulateWalkablePolygon(points);
  let largestTriangle: [number, number, number] | null = null;
  let largestArea = 0;
  for (let index = 0; index < indices.length; index += 3) {
    const first = points[indices[index]!]!;
    const second = points[indices[index + 1]!]!;
    const third = points[indices[index + 2]!]!;
    const area = Math.abs(
      (second[0] - first[0]) * (third[2] - first[2]) -
      (second[2] - first[2]) * (third[0] - first[0]),
    ) / 2;
    if (area <= largestArea) continue;
    largestArea = area;
    largestTriangle = [0, 1, 2].map((axis) =>
      (first[axis]! + second[axis]! + third[axis]!) / 3
    ) as [number, number, number];
  }
  return largestTriangle;
}

function canonicalWalkableAuthoringEntity(row: unknown): Array<{
  id: string;
  kind: string;
  position: unknown;
  geometry: unknown;
}> {
  if (!row || typeof row !== "object") return [];
  const kind = String(Reflect.get(row, "kind") ?? "");
  if (!["floor", "room", "doorway"].includes(kind)) return [];
  const id = String(Reflect.get(row, "id") ?? "");
  if (!id) return [];
  return [{
    id,
    kind,
    position: parseStoredJsonValue(Reflect.get(row, "position_json")),
    geometry: parseStoredJsonValue(Reflect.get(row, "geometry_json")),
  }];
}

function canonicalNavigationRouteStop(row: unknown): Array<{
  id: string;
  entityId: string;
  cameraPose: unknown;
}> {
  if (!row || typeof row !== "object") return [];
  const routeId = String(Reflect.get(row, "route_id") ?? "");
  const entityId = String(Reflect.get(row, "entity_id") ?? "");
  const sequence = Number(Reflect.get(row, "sequence_number"));
  if (!routeId || !entityId || !Number.isSafeInteger(sequence) || sequence < 0) return [];
  return [{
    id: `${routeId}:${sequence}`,
    entityId,
    cameraPose: parseStoredJsonValue(Reflect.get(row, "camera_pose_json")),
  }];
}

function parseStoredJsonValue(value: unknown): unknown {
  if (typeof value !== "string") return null;
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
}

function navigationObstacleBoxFromRow(row: unknown): Array<{
  id: string;
  label: string;
  min: [number, number, number];
  max: [number, number, number];
}> {
  if (!row || typeof row !== "object") return [];
  const boundsJson = Reflect.get(row, "bounds_json");
  if (typeof boundsJson !== "string") return [];
  try {
    const geometry = JSON.parse(boundsJson) as { type?: unknown; points?: unknown[] };
    if (geometry.type !== "box" || !Array.isArray(geometry.points) || geometry.points.length !== 2) {
      return [];
    }
    const first = finitePoint3(geometry.points[0]);
    const second = finitePoint3(geometry.points[1]);
    if (!first || !second) return [];
    return [{
      id: String(Reflect.get(row, "id") ?? ""),
      label: String(Reflect.get(row, "label") ?? "Obstacle"),
      min: [
        Math.min(first[0], second[0]),
        Math.min(first[1], second[1]),
        Math.min(first[2], second[2]),
      ],
      max: [
        Math.max(first[0], second[0]),
        Math.max(first[1], second[1]),
        Math.max(first[2], second[2]),
      ],
    }];
  } catch {
    return [];
  }
}

function readStringProperty(value: unknown, property: string): string | null {
  if (!value || typeof value !== "object") return null;
  const candidate = Reflect.get(value, property);
  return typeof candidate === "string" ? candidate : null;
}

function readNullableStringProperty(value: unknown, property: string): string | null {
  return readStringProperty(value, property);
}

function readNumberProperty(value: unknown, property: string): number | null {
  if (!value || typeof value !== "object") return null;
  const candidate = Reflect.get(value, property);
  return typeof candidate === "number" && Number.isFinite(candidate) ? candidate : null;
}

function positiveInteger(value: string, fallback: number): number {
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : fallback;
}

// A fixed 10 MiB part size cannot complete an upload beyond ~97.6 GiB because
// R2 refuses more than 10,000 parts. Scale the boundary with the declared size
// so every accepted MAX_UPLOAD_BYTES value stays completable.
function uploadPartSizeBytes(sizeBytes: number): number {
  const requiredBytes = Math.ceil(sizeBytes / maximumUploadParts);
  const roundedBytes = Math.ceil(requiredBytes / (1024 * 1024)) * 1024 * 1024;
  return Math.min(Math.max(captureUploadPartBytes, roundedBytes), maximumPartBytes);
}

function scalarCount(result: D1Result<unknown>): number {
  return scalarNumber(result, "count");
}

function requiredBatchResult(results: D1Result<unknown>[], index: number): D1Result<unknown> {
  const result = results[index];
  if (!result) throw new Error(`D1 batch result ${index} is missing`);
  return result;
}

function scalarNumber(result: D1Result<unknown>, key: string): number {
  const first = result.results[0];
  if (!first || typeof first !== "object") return 0;
  const value = Reflect.get(first, key);
  return typeof value === "number" ? value : 0;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function comparisonAssetTokenScope(projectId: string, versionId: string, assetId: string): string {
  return `comparison:${projectId}:${versionId}:${assetId}`;
}

async function releaseAccessToken(operationId: string, secret: string): Promise<string> {
  return sha256Hex(`release-access:${operationId}:${secret}`);
}

function validationError(context: Context<AppEnvironment>, details: unknown): Response {
  return context.json({ error: "Validation failed", details, requestId: context.get("requestId") }, 400);
}

function unprocessable(
  context: Context<AppEnvironment>,
  details: unknown,
  message = "Request cannot be applied",
): Response {
  return context.json({ error: message, details, requestId: context.get("requestId") }, 422);
}

function unauthorized(context: Context<AppEnvironment>, message: string): Response {
  context.header("Cache-Control", "private, no-store");
  return context.json({ error: message, requestId: context.get("requestId") }, 401);
}

function forbidden(context: Context<AppEnvironment>, message: string): Response {
  context.header("Cache-Control", "private, no-store");
  return context.json({ error: message, requestId: context.get("requestId") }, 403);
}

function conflict(context: Context<AppEnvironment>, message: string): Response {
  return context.json({ error: message, requestId: context.get("requestId") }, 409);
}

function notFound(context: Context<AppEnvironment>, message: string): Response {
  return context.json({ error: message, requestId: context.get("requestId") }, 404);
}

function tooManyRequests(context: Context<AppEnvironment>, retryAfterSeconds = 60): Response {
  context.header("Retry-After", String(retryAfterSeconds));
  return context.json({ error: "Rate limit exceeded", requestId: context.get("requestId") }, 429);
}

function captureBundleApi(manifest: CaptureBundleRow): Record<string, unknown> {
  return {
    id: manifest.id,
    projectId: manifest.project_id,
    versionId: manifest.version_id,
    adapter: manifest.adapter_v2 ?? manifest.adapter,
    schemaVersion: manifest.schema_version,
    status: manifest.status,
    result: manifest.result,
    manifestAssetId: manifest.manifest_asset_id,
    manifestHash: manifest.manifest_hash,
    validation: parseStoredObject(manifest.validation_json),
    reviewDecision: manifest.review_decision,
    reviewNote: manifest.review_note,
    reviewGeneration: manifest.review_generation,
    reviewedAt: manifest.reviewed_at,
    createdAt: manifest.created_at,
    updatedAt: manifest.updated_at,
  };
}

function privacyScanApi(scan: PrivacyScanRow): Record<string, unknown> {
  return {
    id: scan.id,
    versionId: scan.version_id,
    status: scan.status,
    detector: scan.detector,
    detectorVersion: scan.detector_version,
    attemptCount: scan.attempt_count,
    maxAttempts: scan.max_attempts,
    inputCount: scan.input_count,
    candidateCount: scan.candidate_count,
    evidence: parseStoredObject(scan.evidence_json ?? "{}"),
    error: parseStoredObject(scan.error_json ?? "null"),
    createdAt: scan.created_at,
    updatedAt: scan.updated_at,
    startedAt: scan.started_at,
    completedAt: scan.completed_at,
  };
}

async function markPrivacyScanEnqueueFailure(
  database: D1Database,
  scanId: string,
  error: unknown,
): Promise<void> {
  await database.prepare(`
    UPDATE privacy_scans
    SET status = 'FAILED', error_json = ?, updated_at = datetime('now')
    WHERE id = ?
  `).bind(JSON.stringify({
    code: "queue_unavailable",
    message: errorMessage(error).slice(0, 1000),
    retryable: true,
    failedAt: new Date().toISOString(),
  }), scanId).run();
}

type NormalisedPrivacyBox = {
  xMin: number;
  yMin: number;
  xMax: number;
  yMax: number;
  confidence: number | null;
  raw: Record<string, unknown>;
};

export function normalisePrivacyBoxes(response: unknown): NormalisedPrivacyBox[] {
  if (!response || typeof response !== "object") return [];
  const objects = Reflect.get(response, "objects");
  if (!Array.isArray(objects)) return [];
  const boxes: NormalisedPrivacyBox[] = [];
  for (const candidate of objects) {
    if (!candidate || typeof candidate !== "object") continue;
    const raw = candidate as Record<string, unknown>;
    const nested = (
      Reflect.get(raw, "bbox") ??
      Reflect.get(raw, "box") ??
      Reflect.get(raw, "bounding_box")
    );
    let coordinates: number[] | null = null;
    if (Array.isArray(nested) && nested.length >= 4) {
      coordinates = nested.slice(0, 4).map(Number);
    } else {
      const source = nested && typeof nested === "object"
        ? nested as Record<string, unknown>
        : raw;
      coordinates = [
        numberFromProperties(source, ["x_min", "xmin", "xMin", "left", "x1"]),
        numberFromProperties(source, ["y_min", "ymin", "yMin", "top", "y1"]),
        numberFromProperties(source, ["x_max", "xmax", "xMax", "right", "x2"]),
        numberFromProperties(source, ["y_max", "ymax", "yMax", "bottom", "y2"]),
      ].map((value) => value ?? Number.NaN);
    }
    if (!coordinates.every(Number.isFinite)) continue;
    const maximum = Math.max(...coordinates);
    if (maximum > 1 && maximum <= 1000) {
      coordinates = coordinates.map((value) => value / 1000);
    }
    let [xMin, yMin, xMax, yMax] = coordinates;
    xMin = clampUnit(xMin!);
    yMin = clampUnit(yMin!);
    xMax = clampUnit(xMax!);
    yMax = clampUnit(yMax!);
    if (xMax <= xMin || yMax <= yMin || (xMax - xMin) * (yMax - yMin) < 0.00001) continue;
    const confidenceValue = numberFromProperties(raw, ["confidence", "score", "probability"]);
    boxes.push({
      xMin: roundCoordinate(xMin),
      yMin: roundCoordinate(yMin),
      xMax: roundCoordinate(xMax),
      yMax: roundCoordinate(yMax),
      confidence: confidenceValue === null ? null : clampUnit(confidenceValue),
      raw,
    });
  }
  return deduplicatePrivacyBoxes(boxes);
}

async function processPrivacyScan(
  env: Env,
  scanId: string,
  deliveryAttempt: number,
): Promise<void> {
  const scan = await env.DB.prepare(`
    UPDATE privacy_scans
    SET status = 'RUNNING', attempt_count = attempt_count + 1,
      started_at = datetime('now'), completed_at = NULL, error_json = NULL,
      updated_at = datetime('now')
    WHERE id = ? AND status IN ('QUEUED', 'FAILED')
    RETURNING *
  `).bind(scanId).first<PrivacyScanRow>();
  if (!scan) {
    const existing = await env.DB.prepare(
      "SELECT status FROM privacy_scans WHERE id = ?",
    ).bind(scanId).first<{ status: string }>();
    if (existing?.status === "COMPLETED" || existing?.status === "RUNNING") return;
    throw new Error("Privacy scan is unavailable for processing");
  }
  const startedAt = Date.now();
  try {
    const inputs = await env.DB.prepare(`
      SELECT a.*, psi.scan_id
      FROM privacy_scan_inputs psi
      JOIN assets a ON a.id = psi.asset_id
      WHERE psi.scan_id = ? AND a.organisation_id = ? AND a.project_id = ?
        AND a.version_id = ? AND a.integrity_status = 'verified'
        AND a.deleted_at IS NULL
      ORDER BY a.id
    `).bind(
      scan.id,
      scan.organisation_id,
      scan.project_id,
      scan.version_id,
    ).all<PrivacyScanInputRow>();
    if (!inputs.results.length || inputs.results.length !== scan.input_count) {
      throw new Error("Privacy scan inputs are missing or no longer verified");
    }
    await env.DB.prepare("DELETE FROM privacy_candidates WHERE scan_id = ?").bind(scan.id).run();
    const candidates: Array<{
      id: string;
      asset: AssetRow;
      target: string;
      label: string;
      box: NormalisedPrivacyBox;
      bboxJson: string;
      bboxHash: string;
    }> = [];
    let inferenceCount = 0;
    let inferenceAttemptCount = 0;
    let truncated = false;
    const ai = env.AI as unknown as {
      run(
        model: string,
        inputs: Record<string, unknown>,
        options?: Record<string, unknown>,
      ): Promise<unknown>;
    };
    for (const asset of inputs.results) {
      if (!asset.mime_type.startsWith("image/") || asset.size_bytes > maximumPrivacyImageBytes) {
        throw new Error(`Privacy input ${asset.file_name} is not a supported bounded image`);
      }
      const object = await env.SPATIAL_ASSETS.get(asset.object_key);
      if (!object) throw new Error(`Privacy input ${asset.file_name} is missing from private storage`);
      const bytes = new Uint8Array(await object.arrayBuffer());
      if (!bytes.byteLength || bytes.byteLength > maximumPrivacyImageBytes) {
        throw new Error(`Privacy input ${asset.file_name} has an invalid byte length`);
      }
      const dataUri = `data:${asset.mime_type};base64,${bytesToBase64(bytes)}`;
      for (const targetDefinition of privacyTargets) {
        const inference = await runPrivacyDetectionWithRetry(
          ai,
          {
            task: "detect",
            image: dataUri,
            target: targetDefinition.target,
            max_objects: 20,
            stream: false,
          },
          {
            tags: ["spatial-studio", "privacy-detection", scan.id.slice(0, 36)],
          },
        );
        const output = inference.output;
        inferenceAttemptCount += inference.attempts;
        inferenceCount += 1;
        for (const box of normalisePrivacyBoxes(output)) {
          if (candidates.length >= 250) {
            truncated = true;
            break;
          }
          const bboxJson = JSON.stringify({
            xMin: box.xMin,
            yMin: box.yMin,
            xMax: box.xMax,
            yMax: box.yMax,
          });
          candidates.push({
            id: crypto.randomUUID(),
            asset,
            target: targetDefinition.target,
            label: targetDefinition.label,
            box,
            bboxJson,
            bboxHash: await sha256Hex(bboxJson),
          });
        }
      }
    }
    for (let offset = 0; offset < candidates.length; offset += 50) {
      const chunk = candidates.slice(offset, offset + 50);
      await env.DB.batch(chunk.map((candidate) => env.DB.prepare(`
        INSERT INTO privacy_candidates
          (id, scan_id, organisation_id, project_id, version_id, asset_id,
            target, label, bbox_json, bbox_hash, confidence,
            detector_metadata_json)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).bind(
        candidate.id,
        scan.id,
        scan.organisation_id,
        scan.project_id,
        scan.version_id,
        candidate.asset.id,
        candidate.target,
        candidate.label,
        candidate.bboxJson,
        candidate.bboxHash,
        candidate.box.confidence,
        JSON.stringify({
          detector: privacyDetectorVersion,
          modelConfidenceUnavailable: candidate.box.confidence === null,
          raw: candidate.box.raw,
        }),
      )));
    }
    const completedAt = new Date().toISOString();
    const evidence = {
      detector: privacyDetector,
      detectorVersion: privacyDetectorVersion,
      targets: privacyTargets.map(({ target }) => target),
      inputs: inputs.results.map((asset) => ({
        assetId: asset.id,
        sha256: asset.sha256,
        mimeType: asset.mime_type,
        sizeBytes: asset.size_bytes,
      })),
      inferenceCount,
      inferenceAttemptCount,
      inferenceRetryCount: inferenceAttemptCount - inferenceCount,
      candidateCount: candidates.length,
      truncated,
      deliveryAttempt,
      durationMs: Date.now() - startedAt,
      completedAt,
      humanReviewRequired: true,
    };
    await env.DB.prepare(`
      UPDATE privacy_scans
      SET status = 'COMPLETED', candidate_count = ?, evidence_json = ?,
        error_json = NULL, completed_at = ?, updated_at = datetime('now')
      WHERE id = ?
    `).bind(candidates.length, JSON.stringify(evidence), completedAt, scan.id).run();
  } catch (error) {
    const exhausted = deliveryAttempt >= scan.max_attempts;
    await env.DB.prepare(`
      UPDATE privacy_scans
      SET status = ?, error_json = ?, completed_at = CASE WHEN ? THEN datetime('now') ELSE NULL END,
        updated_at = datetime('now')
      WHERE id = ?
    `).bind(
      exhausted ? "DEAD_LETTER" : "FAILED",
      JSON.stringify({
        code: "privacy_detection_failed",
        message: errorMessage(error).slice(0, 1000),
        retryable: !exhausted,
        detector: privacyDetectorVersion,
        deliveryAttempt,
        failedAt: new Date().toISOString(),
      }),
      exhausted ? 1 : 0,
      scan.id,
    ).run();
    throw error;
  }
}

export async function runPrivacyDetectionWithRetry(
  ai: {
    run(
      model: string,
      inputs: Record<string, unknown>,
      options?: Record<string, unknown>,
    ): Promise<unknown>;
  },
  inputs: Record<string, unknown>,
  options: Record<string, unknown>,
  maximumAttempts = 3,
): Promise<{ output: unknown; attempts: number }> {
  const attempts = Math.min(3, Math.max(1, Math.trunc(maximumAttempts)));
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return {
        output: await ai.run(privacyDetector, inputs, options),
        attempts: attempt,
      };
    } catch (error) {
      lastError = error;
      if (attempt === attempts) break;
      await new Promise<void>((resolve) => {
        setTimeout(resolve, Math.min(1_000, 250 * 2 ** (attempt - 1)));
      });
    }
  }
  throw lastError instanceof Error ? lastError : new Error(errorMessage(lastError));
}

function numberFromProperties(
  object: Record<string, unknown>,
  properties: string[],
): number | null {
  for (const property of properties) {
    const value = Reflect.get(object, property);
    const parsed = typeof value === "number" ? value : typeof value === "string" ? Number(value) : Number.NaN;
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function clampUnit(value: number): number {
  return Math.min(1, Math.max(0, value));
}

function roundCoordinate(value: number): number {
  return Math.round(value * 1_000_000) / 1_000_000;
}

function deduplicatePrivacyBoxes(boxes: NormalisedPrivacyBox[]): NormalisedPrivacyBox[] {
  const retained: NormalisedPrivacyBox[] = [];
  for (const candidate of boxes) {
    if (retained.some((existing) => privacyBoxIou(existing, candidate) >= 0.9)) continue;
    retained.push(candidate);
  }
  return retained;
}

function privacyBoxIou(left: NormalisedPrivacyBox, right: NormalisedPrivacyBox): number {
  const intersectionWidth = Math.max(0, Math.min(left.xMax, right.xMax) - Math.max(left.xMin, right.xMin));
  const intersectionHeight = Math.max(0, Math.min(left.yMax, right.yMax) - Math.max(left.yMin, right.yMin));
  const intersection = intersectionWidth * intersectionHeight;
  const leftArea = (left.xMax - left.xMin) * (left.yMax - left.yMin);
  const rightArea = (right.xMax - right.xMin) * (right.yMax - right.yMin);
  const union = leftArea + rightArea - intersection;
  return union > 0 ? intersection / union : 0;
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = "";
  for (let offset = 0; offset < bytes.length; offset += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(offset, offset + 0x8000));
  }
  return btoa(binary);
}

const worker = {
  async fetch(request: Request, env: Env, executionContext: ExecutionContext): Promise<Response> {
    return app.fetch(request, env, executionContext);
  },
  async scheduled(controller: ScheduledController, env: Env, executionContext: ExecutionContext): Promise<void> {
    if (controller.cron === "17 * * * *") {
      executionContext.waitUntil(runLifecycleEnforcement(env, "scheduled"));
    }
    executionContext.waitUntil(reapExpiredJobLeases(env));
    executionContext.waitUntil(reapDispatchExhaustedJobs(env));
    executionContext.waitUntil(enqueueDispatchableProcessingJobs(env));
    executionContext.waitUntil(enqueueDispatchableProjectAssetCopies(env));
  },
  async queue(batch: MessageBatch<SpatialQueueMessage>, env: Env): Promise<void> {
    for (const message of batch.messages) {
      if (
        message.body &&
        "type" in message.body &&
        message.body.type === "project_asset_copy"
      ) {
        if (
          typeof message.body.itemId !== "string" ||
          !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
            .test(message.body.itemId)
        ) {
          message.ack();
          continue;
        }
        try {
          await processProjectAssetCopy(env, message.body.itemId, message.attempts);
          message.ack();
        } catch (error) {
          console.error(JSON.stringify({
            event: "project_asset_handoff.copy_failed",
            itemId: message.body.itemId,
            attempt: message.attempts,
            error: errorMessage(error),
          }));
          message.retry({
            delaySeconds: Math.min(300, 15 * 2 ** Math.max(0, message.attempts - 1)),
          });
        }
        continue;
      }
      if (
        !message.body ||
        !("scanId" in message.body) ||
        typeof message.body.scanId !== "string" ||
        !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(message.body.scanId)
      ) {
        message.ack();
        continue;
      }
      try {
        await processPrivacyScan(env, message.body.scanId, message.attempts);
        message.ack();
      } catch (error) {
        console.error(JSON.stringify({
          event: "privacy.scan_failed",
          scanId: message.body.scanId,
          attempt: message.attempts,
          error: errorMessage(error),
        }));
        message.retry({ delaySeconds: Math.min(300, 15 * 2 ** Math.max(0, message.attempts - 1)) });
      }
    }
  },
} satisfies ExportedHandler<Env, SpatialQueueMessage>;

export default worker;
